insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','jz',1,1,'E sucedeu, depois da morte de Josué, que os filhos de Israel perguntaram ao SENHOR, dizendo: Quem dentre nós primeiro subirá aos cananeus, para pelejar contra eles?'),
('acf','jz',1,2,'E disse o Senhor: Judá subirá; eis que entreguei esta terra na sua mão.'),
('acf','jz',1,3,'Então disse Judá a Simeão, seu irmão: Sobe comigo à minha herança. E pelejemos contra os cananeus, e também eu contigo subirei à tua herança. E Simeão partiu com ele.'),
('acf','jz',1,4,'E subiu Judá, e o Senhor lhe entregou na sua mão os cananeus e os perizeus; e feriram deles, em Bezeque, a dez mil homens.'),
('acf','jz',1,5,'E acharam Adoni-Bezeque em Bezeque, e pelejaram contra ele; e feriram aos cananeus e aos perizeus.'),
('acf','jz',1,6,'Porém Adoni-Bezeque fugiu, mas o seguiram, e prenderam-no e cortaram-lhe os dedos polegares das mãos e dos pés.'),
('acf','jz',1,7,'Então disse Adoni-Bezeque: Setenta reis, com os dedos polegares das mãos e dos pés cortados, apanhavam as migalhas debaixo da minha mesa; assim como eu fiz, assim Deus me pagou. E levaram-no a Jerusalém, e morreu ali.'),
('acf','jz',1,8,'E os filhos de Judá pelejaram contra Jerusalém, e tomando-a, feriram-na ao fio da espada; e puseram fogo na cidade.'),
('acf','jz',1,9,'E depois os filhos de Judá desceram a pelejar contra os cananeus, que habitavam nas montanhas, e no sul, e nas planícies.'),
('acf','jz',1,10,'E partiu Judá contra os cananeus que habitavam em Hebrom (era porém outrora o nome de Hebrom, Quiriate-Arba), e feriram a Sesai, e a Aimã e Talmai.'),
('acf','jz',1,11,'E dali partiu contra os moradores de Debir; e era outrora o nome de Debir, Quiriate-Sefer.'),
('acf','jz',1,12,'E disse Calebe: Quem ferir a Quiriate-Sefer, e a tomar, lhe darei a minha filha Acsa por mulher.'),
('acf','jz',1,13,'E tomou-a Otniel, filho de Quenaz, o irmão de Calebe, mais novo do que ele; e Calebe lhe deu a sua filha Acsa por mulher.'),
('acf','jz',1,14,'E sucedeu que, indo ela a ele, o persuadiu que pedisse um campo a seu pai; e ela desceu do jumento, e Calebe lhe disse: Que é que tens?'),
('acf','jz',1,15,'E ela lhe disse: Dá-me uma bênção; pois me deste uma terra seca, dá-me também fontes de águas. E Calebe lhe deu as fontes superiores e as fontes inferiores.'),
('acf','jz',1,16,'Também os filhos do queneu, sogro de Moisés, subiram da cidade das palmeiras com os filhos de Judá ao deserto de Judá, que está ao sul de Arade, e foram, e habitaram com o povo.'),
('acf','jz',1,17,'E foi Judá com Simeão, seu irmão, e feriram aos cananeus que habitavam em Zefate; e totalmente a destruíram, e chamou-se o nome desta cidade Hormá.'),
('acf','jz',1,18,'Tomou mais Judá a Gaza com o seu termo, e a Ascalom com o seu termo, e a Ecrom com o seu termo.'),
('acf','jz',1,19,'E estava o Senhor com Judá, e despovoou as montanhas; porém não expulsou aos moradores do vale, porquanto tinham carros de ferro.'),
('acf','jz',1,20,'E deram Hebrom a Calebe, como Moisés o dissera; e dali expulsou os três filhos de Anaque.'),
('acf','jz',1,21,'Porém os filhos de Benjamim não expulsaram os jebuseus que habitavam em Jerusalém; antes os jebuseus ficaram habitando com os filhos de Benjamim em Jerusalém, até ao dia de hoje,'),
('acf','jz',1,22,'E subiu também a casa de José contra Betel, e foi o Senhor com eles.'),
('acf','jz',1,23,'E a casa de José mandou espias a Betel, e foi antes o nome desta cidade Luz.'),
('acf','jz',1,24,'E viram os espias a um homem, que saía da cidade, e lhe disseram: Ora, mostra-nos a entrada da cidade, e usaremos contigo de misericórdia.'),
('acf','jz',1,25,'E, mostrando-lhes ele a entrada da cidade, feriram-na ao fio da espada; porém àquele homem e a toda a sua família deixaram ir.'),
('acf','jz',1,26,'Então aquele homem se foi à terra dos heteus, e edificou uma cidade, e chamou o seu nome Luz; este é o seu nome até ao dia de hoje.'),
('acf','jz',1,27,'Manassés não expulsou os habitantes de Bete-Seã, nem mesmo dos lugares da sua jurisdição; nem a Taanaque, com os lugares da sua jurisdição; nem os moradores de Dor, com os lugares da sua jurisdição; nem os moradores de Ibleão, com os lugares da sua jurisdição; nem os moradores de Megido, com os lugares da sua jurisdição; e resolveram os cananeus habitar na mesma terra.'),
('acf','jz',1,28,'E sucedeu que, quando Israel cobrou mais forças, fez dos cananeus tributários; porém não os expulsou de todo.'),
('acf','jz',1,29,'Tampouco expulsou Efraim os cananeus que habitavam em Gezer; antes os cananeus ficaram habitando com ele, em Gezer.'),
('acf','jz',1,30,'Tampouco expulsou Zebulom os moradores de Quitrom, nem os moradores de Naalol; porém os cananeus ficaram habitando com ele, e foram tributários.'),
('acf','jz',1,31,'Tampouco Aser expulsou os moradores de Aco, nem os moradores de Sidom; como nem de Alabe, nem de Aczibe, nem de Helba, nem de Afeque, nem de Reobe;'),
('acf','jz',1,32,'Porém os aseritas habitaram no meio dos cananeus que habitavam na terra; porquanto não os expulsaram.'),
('acf','jz',1,33,'Tampouco Naftali expulsou os moradores de Bete-Semes, nem os moradores de Bete-Anate; mas habitou no meio dos cananeus que habitavam na terra; porém lhes foram tributários os moradores de Bete-Semes e Bete-Anate.'),
('acf','jz',1,34,'E os amorreus impeliram os filhos de Dã até às montanhas; porque nem os deixavam descer ao vale.'),
('acf','jz',1,35,'Também os amorreus quiseram habitar nas montanhas de Heres, em Aijalom e em Saalbim; porém prevaleceu a mão da casa de José, e ficaram tributários.'),
('acf','jz',1,36,'E foi o termo dos amorreus desde a subida de Acrabim, desde a penha, e dali para cima.'),
('acf','jz',2,1,'E subiu o anjo do SENHOR de Gilgal a Boquim, e disse: Do Egito vos fiz subir, e vos trouxe à terra que a vossos pais tinha jurado e disse: Nunca invalidarei a minha aliança convosco.'),
('acf','jz',2,2,'E, quanto a vós, não fareis acordo com os moradores desta terra, antes derrubareis os seus altares; mas vós não obedecestes à minha voz. Por que fizestes isso?'),
('acf','jz',2,3,'Assim também eu disse: Não os expulsarei de diante de vós; antes estarão como espinhos nas vossas ilhargas, e os seus deuses vos serão por laço.'),
('acf','jz',2,4,'E sucedeu que, falando o anjo do Senhor estas palavras a todos os filhos de Israel, o povo levantou a sua voz e chorou.'),
('acf','jz',2,5,'Por isso chamaram àquele lugar, Boquim; e sacrificaram ali ao Senhor.'),
('acf','jz',2,6,'E havendo Josué despedido o povo foram-se os filhos de Israel, cada um à sua herança, para possuírem a terra.'),
('acf','jz',2,7,'E serviu o povo ao Senhor todos os dias de Josué, e todos os dias dos anciãos que ainda sobreviveram depois de Josué, e viram toda aquela grande obra do Senhor, que fizera a Israel.'),
('acf','jz',2,8,'Faleceu, porém, Josué, filho de Num, servo do Senhor, com a idade de cento e dez anos;'),
('acf','jz',2,9,'E sepultaram-no no termo da sua herança, em Timnate-Heres, no monte de Efraim, para o norte do monte de Gaás.'),
('acf','jz',2,10,'E foi também congregada toda aquela geração a seus pais, e outra geração após ela se levantou, que não conhecia ao Senhor, nem tampouco a obra que ele fizera a Israel.'),
('acf','jz',2,11,'Então fizeram os filhos de Israel o que era mau aos olhos do Senhor; e serviram aos baalins.'),
('acf','jz',2,12,'E deixaram ao Senhor Deus de seus pais, que os tirara da terra do Egito, e foram-se após outros deuses, dentre os deuses dos povos, que havia ao redor deles, e adoraram a eles; e provocaram o Senhor à ira.'),
('acf','jz',2,13,'Porquanto deixaram ao Senhor, e serviram a Baal e a Astarote.'),
('acf','jz',2,14,'Por isso a ira do Senhor se acendeu contra Israel, e os entregou na mão dos espoliadores que os despojaram; e os entregou na mão dos seus inimigos ao redor; e não puderam mais resistir diante dos seus inimigos.'),
('acf','jz',2,15,'Por onde quer que saíam, a mão do Senhor era contra eles para mal, como o Senhor tinha falado, e como o Senhor lhes tinha jurado; e estavam em grande aflição.'),
('acf','jz',2,16,'E levantou o Senhor juízes, que os livraram da mão dos que os despojaram.'),
('acf','jz',2,17,'Porém tampouco ouviram aos juízes, antes prostituíram-se após outros deuses, e adoraram a eles; depressa se desviaram do caminho, por onde andaram seus pais, obedecendo os mandamentos do Senhor; mas eles assim não fizeram.'),
('acf','jz',2,18,'E, quando o Senhor lhes levantava juízes, o Senhor era com o juiz, e os livrava da mão dos seus inimigos, todos os dias daquele juiz; porquanto o Senhor se compadecia deles pelo seu gemido, por causa dos que os oprimiam e afligiam.'),
('acf','jz',2,19,'Porém sucedia que, falecendo o juiz, reincidiam e se corrompiam mais do que seus pais, andando após outros deuses, servindo-os, e adorando-os; nada deixavam das suas obras, nem do seu obstinado caminho.'),
('acf','jz',2,20,'Por isso a ira do Senhor se acendeu contra Israel, e disse: Porquanto este povo transgrediu a minha aliança, que tinha ordenado a seus pais, e não deram ouvidos à minha voz,'),
('acf','jz',2,21,'Tampouco desapossarei mais de diante deles a nenhuma das nações, que Josué deixou, quando morreu;'),
('acf','jz',2,22,'Para por elas provar a Israel, se há de guardar, ou não, o caminho do Senhor, como seus pais o guardaram, para nele andar.'),
('acf','jz',2,23,'Assim o Senhor deixou ficar aquelas nações, e não as desterrou logo, nem as entregou na mão de Josué.'),
('acf','jz',3,1,'Estas, pois, são as nações que o SENHOR deixou ficar, para por elas provar a Israel, a saber, a todos os que não sabiam de todas as guerras de Canaã.'),
('acf','jz',3,2,'Tão-somente para que as gerações dos filhos de Israel delas soubessem (para lhes ensinar a guerra), pelo menos os que dantes não sabiam delas.'),
('acf','jz',3,3,'Cinco príncipes dos filisteus, e todos os cananeus, e sidônios, e heveus que habitavam nas montanhas do Líbano desde o monte de Baal-Hermom, até à entrada de Hamate.'),
('acf','jz',3,4,'Estes, pois, ficaram, para por eles provar a Israel, para saber se dariam ouvido aos mandamentos do Senhor, que ele tinha ordenado a seus pais, pelo ministério de Moisés.'),
('acf','jz',3,5,'Habitando, pois, os filhos de Israel no meio dos cananeus, dos heteus, e amorreus, e perizeus, e heveus, e jebuseus,'),
('acf','jz',3,6,'Tomaram de suas filhas para si por mulheres, e deram as suas filhas aos filhos deles; e serviram aos seus deuses.'),
('acf','jz',3,7,'E os filhos de Israel fizeram o que era mau aos olhos do Senhor, e se esqueceram do Senhor seu Deus; e serviram aos baalins e a Astarote.'),
('acf','jz',3,8,'Então a ira do SENHOR se acendeu contra Israel, e ele os vendeu na mão de Cusã-Risataim, rei da mesopotâmia; e os filhos de Israel serviram a Cusã-Risataim oito anos.'),
('acf','jz',3,9,'E os filhos de Israel clamaram ao Senhor, e o Senhor levantou-lhes um libertador, que os libertou: Otniel, filho de Quenaz, irmão de Calebe, mais novo do que ele.'),
('acf','jz',3,10,'E veio sobre ele o Espírito do Senhor, e julgou a Israel, e saiu à peleja; e o Senhor entregou na sua mão a Cusã-Risataim, rei da Síria; contra o qual prevaleceu a sua mão.'),
('acf','jz',3,11,'Então a terra sossegou quarenta anos; e Otniel, filho de Quenaz, faleceu.'),
('acf','jz',3,12,'Porém os filhos de Israel tornaram a fazer o que era mau aos olhos do Senhor; então o Senhor fortaleceu a Eglom, rei dos moabitas, contra Israel; porquanto fizeram o que era mau aos olhos do Senhor.'),
('acf','jz',3,13,'E reuniu consigo os filhos de Amom e os amalequitas, e foi, e feriu a Israel, e tomaram a cidade das palmeiras.'),
('acf','jz',3,14,'E os filhos de Israel serviram a Eglom, rei dos moabitas, dezoito anos.'),
('acf','jz',3,15,'Então os filhos de Israel clamaram ao Senhor, e o Senhor lhes levantou um libertador, a Eúde, filho de Gera, filho de Jemim, homem canhoto. E os filhos de Israel enviaram pela sua mão um presente a Eglom, rei dos moabitas.'),
('acf','jz',3,16,'E Eúde fez para si uma espada de dois fios, do comprimento de um côvado; e cingiu-a por baixo das suas vestes, à sua coxa direita.'),
('acf','jz',3,17,'E levou aquele presente a Eglom, rei dos moabitas; e era Eglom homem muito gordo.'),
('acf','jz',3,18,'E sucedeu que, acabando de entregar o presente, despediu a gente que o trouxera.'),
('acf','jz',3,19,'Porém ele mesmo voltou das imagens de escultura que estavam ao pé de Gilgal, e disse: Tenho uma palavra secreta para ti, ó rei. O qual disse: Cala-te. E todos os que lhe assistiam saíram de diante dele.'),
('acf','jz',3,20,'E Eúde entrou numa sala de verão, que o rei tinha só para si, onde estava sentado, e disse: Tenho, para dizer-te, uma palavra de Deus. E levantou-se da cadeira.'),
('acf','jz',3,21,'Então Eúde estendeu a sua mão esquerda, e tirou a espada de sobre sua coxa direita, e lha cravou no ventre,'),
('acf','jz',3,22,'De tal maneira que entrou até o cabo após a lâmina, e a gordura encerrou a lâmina (porque não tirou a espada do ventre); e saiu-lhe o excremento.'),
('acf','jz',3,23,'Então Eúde saiu ao pátio, e fechou as portas da sala e as trancou.'),
('acf','jz',3,24,'E, saindo ele, vieram os servos do rei, e viram, e eis que as portas da sala estavam fechadas; e disseram: Sem dúvida está cobrindo seus pés na recâmara da sala de verão.'),
('acf','jz',3,25,'E, esperando até se alarmarem, eis que ele não abria as portas da sala; então tomaram a chave, e abriram, e eis ali seu senhor estendido morto em terra.'),
('acf','jz',3,26,'E Eúde escapou, enquanto eles se demoravam; porque ele passou pelas imagens de escultura, e escapou para Seirá.'),
('acf','jz',3,27,'E sucedeu que, chegando ele, tocou a buzina nas montanhas de Efraim, e os filhos de Israel desceram com ele das montanhas, e ele adiante deles.'),
('acf','jz',3,28,'E disse-lhes: Segui-me, porque o Senhor vos tem entregue vossos inimigos, os moabitas, nas vossas mãos; e desceram após ele, e tomaram os vaus do Jordão contra Moabe, e a ninguém deixaram passar.'),
('acf','jz',3,29,'E naquele tempo feriram dos moabitas uns dez mil homens, todos corpulentos, e todos homens valorosos; e não escapou nenhum.'),
('acf','jz',3,30,'Assim foi subjugado Moabe naquele dia debaixo da mão de Israel; e a terra sossegou oitenta anos.'),
('acf','jz',3,31,'Depois dele foi Sangar, filho de Anate, que feriu a seiscentos homens dos filisteus com uma aguilhada de bois; e também ele libertou a Israel.'),
('acf','jz',4,1,'Porém os filhos de Israel tornaram a fazer o que era mau aos olhos do SENHOR, depois de falecer Eúde.'),
('acf','jz',4,2,'E vendeu-os o Senhor na mão de Jabim, rei de Canaã, que reinava em Hazor; e Sísera era o capitão do seu exército, o qual então habitava em Harosete dos gentios.'),
('acf','jz',4,3,'Então os filhos de Israel clamaram ao Senhor, porquanto ele tinha novecentos carros de ferro, e por vinte anos oprimia violentamente os filhos de Israel.'),
('acf','jz',4,4,'E Débora, mulher profetisa, mulher de Lapidote, julgava a Israel naquele tempo.'),
('acf','jz',4,5,'Ela assentava-se debaixo das palmeiras de Débora, entre Ramá e Betel, nas montanhas de Efraim; e os filhos de Israel subiam a ela a juízo.'),
('acf','jz',4,6,'E mandou chamar a Baraque, filho de Abinoão de Quedes de Naftali, e disse-lhe: Porventura o Senhor Deus de Israel não deu ordem, dizendo: Vai, e atrai gente ao monte Tabor, e toma contigo dez mil homens dos filhos de Naftali e dos filhos de Zebulom;'),
('acf','jz',4,7,'E atrairei a ti para o ribeiro de Quisom, a Sísera, capitão do exército de Jabim, com os seus carros, e com a sua multidão; e o darei na tua mão.'),
('acf','jz',4,8,'Então lhe disse Baraque: Se fores comigo, irei; porém, se não fores comigo, não irei.'),
('acf','jz',4,9,'E disse ela: Certamente irei contigo, porém não será tua a honra da jornada que empreenderes; pois à mão de uma mulher o Senhor venderá a Sísera. E Débora se levantou, e partiu com Baraque para Quedes.'),
('acf','jz',4,10,'Então Baraque convocou a Zebulom e a Naftali em Quedes, e subiu com dez mil homens após ele; e Débora subiu com ele.'),
('acf','jz',4,11,'E Héber, queneu, se tinha apartado dos queneus, dos filhos de Hobabe, sogro de Moisés; e tinha estendido as suas tendas até ao carvalho de Zaanaim, que está junto a Quedes,'),
('acf','jz',4,12,'E anunciaram a Sísera que Baraque, filho de Abinoão, tinha subido ao monte Tabor.'),
('acf','jz',4,13,'E Sísera convocou todos os seus carros, novecentos carros de ferro, e todo o povo que estava com ele, desde Harosete dos gentios até ao ribeiro de Quisom.'),
('acf','jz',4,14,'Então disse Débora a Baraque: Levanta-te, porque este é o dia em que o Senhor tem dado a Sísera na tua mão; porventura o Senhor não saiu adiante de ti? Baraque, pois, desceu do monte Tabor, e dez mil homens após ele.'),
('acf','jz',4,15,'E o Senhor derrotou a Sísera, e a todos os seus carros, e a todo o seu exército ao fio da espada, diante de Baraque; e Sísera desceu do carro, e fugiu a pé.'),
('acf','jz',4,16,'E Baraque perseguiu os carros, e o exército, até Harosete dos gentios; e todo o exército de Sísera caiu ao fio da espada, até não ficar um só.'),
('acf','jz',4,17,'Porém Sísera fugiu a pé à tenda de Jael, mulher de Héber, queneu; porquanto havia paz entre Jabim, rei de Hazor, e a casa de Héber, queneu.'),
('acf','jz',4,18,'E Jael saiu ao encontro de Sísera, e disse-lhe: Entra, senhor meu, entra aqui, não temas. Ele entrou na sua tenda, e ela o cobriu com uma coberta.'),
('acf','jz',4,19,'Então ele lhe disse: Dá-me, peço-te, de beber um pouco de água, porque tenho sede. Então ela abriu um odre de leite, e deu-lhe de beber, e o cobriu.'),
('acf','jz',4,20,'E ele lhe disse: Põe-te à porta da tenda; e há de ser que se alguém vier e te perguntar: Há aqui alguém? Responderás então: Não.'),
('acf','jz',4,21,'Então Jael, mulher de Héber, tomou uma estaca da tenda, e lançou mão de um martelo, e chegou-se mansamente a ele, e lhe cravou a estaca na fonte, de sorte que penetrou na terra, estando ele, porém, num profundo sono, e já muito cansado; e assim morreu.'),
('acf','jz',4,22,'E eis que, seguindo Baraque a Sísera, Jael lhe saiu ao encontro, e disse-lhe: Vem, e mostrar-te-ei o homem que buscas. E foi a ela, e eis que Sísera jazia morto, com a estaca na fonte.'),
('acf','jz',4,23,'Assim Deus naquele dia sujeitou a Jabim, rei de Canaã, diante dos filhos de Israel.'),
('acf','jz',4,24,'E continuou a mão dos filhos de Israel a pesar e a endurecer-se sobre Jabim, rei de Canaã; até que exterminaram a Jabim, rei de Canaã.'),
('acf','jz',5,1,'E cantou Débora e Baraque, filho de Abinoão, naquele mesmo dia, dizendo:'),
('acf','jz',5,2,'Louvai ao Senhor pela vingança de Israel, quando o povo se ofereceu voluntariamente.'),
('acf','jz',5,3,'Ouvi, reis; dai ouvidos, príncipes; eu, eu cantarei ao Senhor; salmodiarei ao Senhor Deus de Israel.'),
('acf','jz',5,4,'Ó Senhor, saindo tu de Seir, caminhando tu desde o campo de Edom, a terra estremeceu; até os céus gotejaram; até as nuvens gotejaram águas.'),
('acf','jz',5,5,'Os montes se derreteram diante do Senhor, e até Sinai diante do Senhor Deus de Israel.'),
('acf','jz',5,6,'Nos dias de Sangar, filho de Anate, nos dias de Jael cessaram os caminhos; e os que andavam por veredas iam por caminhos torcidos.'),
('acf','jz',5,7,'Cessaram as aldeias em Israel, cessaram; até que eu, Débora, me levantei, por mãe em Israel me levantei.'),
('acf','jz',5,8,'E se escolhia deuses novos, logo a guerra estava às portas; via-se por isso escudo ou lança entre quarenta mil em Israel?'),
('acf','jz',5,9,'Meu coração é para os legisladores de Israel, que voluntariamente se ofereceram entre o povo; bendizei ao Senhor.'),
('acf','jz',5,10,'Vós os que cavalgais sobre jumentas brancas, que vos assentais em juízo, que andais pelo caminho, falai disto.'),
('acf','jz',5,11,'Donde se ouve o estrondo dos flecheiros, entre os lugares onde se tiram águas, ali falai das justiças do Senhor, das justiças que fez às suas aldeias em Israel; então o povo do Senhor descia às portas.'),
('acf','jz',5,12,'Desperta, desperta, Débora, desperta, desperta, entoa um cântico; levanta-te, Baraque, e leva presos os teus cativos, tu, filho de Abinoão.'),
('acf','jz',5,13,'Então fez dominar sobre os nobres entre o povo, aos que restaram; fez-me o Senhor dominar sobre os poderosos.'),
('acf','jz',5,14,'De Efraim saiu a sua raiz contra Amaleque; e depois de ti vinha Benjamim dentre os teus povos; de Maquir desceram os legisladores, e de Zebulom os que levaram a cana do escriba.'),
('acf','jz',5,15,'Também os principais de Issacar foram com Débora; e como Issacar, assim também Baraque, foi enviado a pé para o vale; nas divisões de Rúben foram grandes as resoluções do coração.'),
('acf','jz',5,16,'Por que ficaste tu entre os currais para ouvires os balidos dos rebanhos? Nas divisões de Rúben tiveram grandes esquadrinhações do coração.'),
('acf','jz',5,17,'Gileade ficou além do Jordão, e Dã por que se deteve nos navios? Aser se assentou na beira dos mares, e ficou junto às suas baías.'),
('acf','jz',5,18,'Zebulom é um povo que expôs a sua vida à morte, como também Naftali, nas alturas do campo.'),
('acf','jz',5,19,'Vieram reis, pelejaram; então pelejaram os reis de Canaã em Taanaque, junto às águas de Megido; não tomaram despojo de prata.'),
('acf','jz',5,20,'Desde os céus pelejaram; até as estrelas desde os lugares dos seus cursos pelejaram contra Sísera.'),
('acf','jz',5,21,'O ribeiro de Quisom os arrastou, aquele antigo ribeiro, o ribeiro de Quisom. Pisaste, ó minha alma, à força.'),
('acf','jz',5,22,'Então os cascos dos cavalos se despedaçaram; pelo galopar, o galopar dos seus valentes.'),
('acf','jz',5,23,'Amaldiçoai a Meroz, diz o anjo do Senhor, acremente amaldiçoai aos seus moradores; porquanto não vieram ao socorro do Senhor, ao socorro do Senhor com os valorosos.'),
('acf','jz',5,24,'Bendita seja entre as mulheres, Jael, mulher de Héber, o queneu; bendita seja entre as mulheres nas tendas.'),
('acf','jz',5,25,'Água pediu ele, leite lhe deu ela; em prato de nobres lhe ofereceu manteiga.'),
('acf','jz',5,26,'À estaca estendeu a sua mão esquerda, e ao martelo dos trabalhadores a sua direita; e matou a Sísera, e rachou-lhe a cabeça, quando lhe pregou e atravessou as fontes.'),
('acf','jz',5,27,'Entre os seus pés se encurvou, caiu, ficou estirado; entre os seus pés se encurvou, caiu; onde se encurvou, ali ficou abatido.'),
('acf','jz',5,28,'A mãe de Sísera olhava pela janela, e exclamava pela grade: Por que tarda em vir o seu carro? Por que se demoram os ruídos dos seus carros?'),
('acf','jz',5,29,'As mais sábias das suas damas responderam; e até ela respondia a si mesma:'),
('acf','jz',5,30,'Porventura não achariam e repartiriam despojos? Uma ou duas moças a cada homem? Para Sísera despojos de estofos coloridos, despojos de estofos coloridos bordados; de estofos coloridos bordados de ambos os lados como despojo para os pescoços.'),
('acf','jz',5,31,'Assim, ó Senhor, pereçam todos os teus inimigos! Porém os que te amam sejam como o sol quando sai na sua força.'),
('acf','jz',5,32,'E sossegou a terra quarenta anos.'),
('acf','jz',6,1,'Porém os filhos de Israel fizeram o que era mau aos olhos do SENHOR; e o SENHOR os deu nas mãos dos midianitas por sete anos.'),
('acf','jz',6,2,'E, prevalecendo a mão dos midianitas sobre Israel, fizeram os filhos de Israel para si, por causa dos midianitas, as covas que estão nos montes, as cavernas e as fortificações.'),
('acf','jz',6,3,'Porque sucedia que, semeando Israel, os midianitas e os amalequitas, e também os do oriente, contra ele subiam.'),
('acf','jz',6,4,'E punham-se contra ele em campo, e destruíam os frutos da terra, até chegarem a Gaza; e não deixavam mantimento em Israel, nem ovelhas, nem bois, nem jumentos.'),
('acf','jz',6,5,'Porque subiam com os seus gados e tendas; vinham como gafanhotos, em grande multidão que não se podia contar, nem a eles nem aos seus camelos; e entravam na terra, para a destruir.'),
('acf','jz',6,6,'Assim Israel empobreceu muito pela presença dos midianitas; então os filhos de Israel clamaram ao Senhor.'),
('acf','jz',6,7,'E sucedeu que, clamando os filhos de Israel ao Senhor por causa dos midianitas,'),
('acf','jz',6,8,'Enviou o Senhor um profeta aos filhos de Israel, que lhes disse: Assim diz o Senhor Deus de Israel: Do Egito eu vos fiz subir, e vos tirei da casa da servidão;'),
('acf','jz',6,9,'E vos livrei da mão dos egípcios, e da mão de todos quantos vos oprimiam; e os expulsei de diante de vós, e a vós dei a sua terra.'),
('acf','jz',6,10,'E vos disse: Eu sou o Senhor vosso Deus; não temais aos deuses dos amorreus, em cuja terra habitais; mas não destes ouvidos à minha voz.'),
('acf','jz',6,11,'Então o anjo do Senhor veio, e assentou-se debaixo do carvalho que está em Ofra, que pertencia a Joás, abiezrita; e Gideão, seu filho, estava malhando o trigo no lagar, para o salvar dos midianitas.'),
('acf','jz',6,12,'Então o anjo do Senhor lhe apareceu, e lhe disse: O Senhor é contigo, homem valoroso.'),
('acf','jz',6,13,'Mas Gideão lhe respondeu: Ai, Senhor meu, se o Senhor é conosco, por que tudo isto nos sobreveio? E que é feito de todas as suas maravilhas que nossos pais nos contaram, dizendo: Não nos fez o Senhor subir do Egito? Porém agora o Senhor nos desamparou, e nos deu nas mãos dos midianitas.'),
('acf','jz',6,14,'Então o Senhor olhou para ele, e disse: Vai nesta tua força, e livrarás a Israel das mãos dos midianitas; porventura não te enviei eu?'),
('acf','jz',6,15,'E ele lhe disse: Ai, Senhor meu, com que livrarei a Israel? Eis que a minha família é a mais pobre em Manassés, e eu o menor na casa de meu pai.'),
('acf','jz',6,16,'E o Senhor lhe disse: Porquanto eu hei de ser contigo, tu ferirás aos midianitas como se fossem um só homem.'),
('acf','jz',6,17,'E ele disse: Se agora tenho achado graça aos teus olhos, dá-me um sinal de que és tu que falas comigo.'),
('acf','jz',6,18,'Rogo-te que daqui não te apartes, até que eu volte e traga o meu presente, e o ponha perante ti. E disse: Eu esperarei até que voltes.'),
('acf','jz',6,19,'E entrou Gideão e preparou um cabrito e pães ázimos de um efa de farinha; a carne pôs num cesto e o caldo pôs numa panela; e trouxe-lho até debaixo do carvalho, e lho ofereceu.'),
('acf','jz',6,20,'Porém o anjo de Deus lhe disse: Toma a carne e os pães ázimos, e põe-nos sobre esta penha e derrama-lhe o caldo. E assim fez.'),
('acf','jz',6,21,'E o anjo do Senhor estendeu a ponta do cajado, que estava na sua mão, e tocou a carne e os pães ázimos; então subiu o fogo da penha, e consumiu a carne e os pães ázimos; e o anjo do Senhor desapareceu de seus olhos.'),
('acf','jz',6,22,'Então viu Gideão que era o anjo do SENHOR e disse: Ah, Senhor DEUS, pois vi o anjo do SENHOR face a face.'),
('acf','jz',6,23,'Porém o Senhor lhe disse: Paz seja contigo; não temas; não morrerás.'),
('acf','jz',6,24,'Então Gideão edificou ali um altar ao SENHOR, e chamou-lhe: O SENHOR É PAZ; e ainda até o dia de hoje está em Ofra dos abiezritas.'),
('acf','jz',6,25,'E aconteceu naquela mesma noite, que o Senhor lhe disse: Toma o boi que pertence a teu pai, a saber, o segundo boi de sete anos, e derruba o altar de Baal, que é de teu pai; e corta o bosque que está ao pé dele.'),
('acf','jz',6,26,'E edifica ao Senhor teu Deus um altar no cume deste lugar forte, num lugar conveniente; e toma o segundo boi, e o oferecerás em holocausto com a lenha que cortares do bosque.'),
('acf','jz',6,27,'Então Gideão tomou dez homens dentre os seus servos, e fez como o Senhor lhe dissera; e sucedeu que, temendo ele a casa de seu pai, e os homens daquela cidade, não o fez de dia, mas fê-lo de noite.'),
('acf','jz',6,28,'Levantando-se, pois, os homens daquela cidade, de madrugada, eis que estava o altar de Baal derrubado, e o bosque estava ao pé dele, cortado; e o segundo boi oferecido no altar que fora edificado.'),
('acf','jz',6,29,'E uns aos outros disseram: Quem fez esta coisa? E, esquadrinhando, e inquirindo, disseram: Gideão, o filho de Joás, fez esta coisa.'),
('acf','jz',6,30,'Então os homens daquela cidade disseram a Joás: Tira para fora a teu filho; para que morra; pois derribou o altar de Baal, e cortou o bosque que estava ao pé dele.'),
('acf','jz',6,31,'Porém Joás disse a todos os que se puseram contra ele: Contendereis vós por Baal? Livrá-lo-eis vós? Qualquer que por ele contender ainda esta manhã será morto; se é deus, por si mesmo contenda; pois derrubaram o seu altar.'),
('acf','jz',6,32,'Por isso naquele dia lhe chamaram Jerubaal, dizendo: Baal contenda contra ele, pois derrubou o seu altar.'),
('acf','jz',6,33,'E todos os midianitas e amalequitas, e os filhos do oriente se ajuntaram, e passaram, e acamparam no vale de Jizreel.'),
('acf','jz',6,34,'Então o Espírito do SENHOR revestiu a Gideão, o qual tocou a buzina, e os abiezritas se ajuntaram após ele.'),
('acf','jz',6,35,'E enviou mensageiros por toda a tribo de Manassés, que também se ajuntou após ele; também enviou mensageiros a Aser, e a Zebulom, e a Naftali, que saíram-lhe ao encontro.'),
('acf','jz',6,36,'E disse Gideão a Deus: Se hás de livrar a Israel por minha mão, como disseste,'),
('acf','jz',6,37,'Eis que eu porei um velo de lã na eira; se o orvalho estiver somente no velo, e toda a terra ficar seca, então conhecerei que hás de livrar a Israel por minha mão, como disseste.'),
('acf','jz',6,38,'E assim sucedeu; porque no outro dia se levantou de madrugada, e apertou o velo; e do orvalho que espremeu do velo, encheu uma taça de água.'),
('acf','jz',6,39,'E disse Gideão a Deus: Não se acenda contra mim a tua ira, se ainda falar só esta vez; rogo-te que só esta vez faça a prova com o velo; rogo-te que só o velo fique seco, e em toda a terra haja o orvalho.'),
('acf','jz',6,40,'E Deus assim fez naquela noite; pois só o velo ficou seco, e sobre toda a terra havia orvalho.'),
('acf','jz',7,1,'Então Jerubaal (que é Gideão) se levantou de madrugada, e todo o povo que com ele havia, e se acamparam junto à fonte de Harode, de maneira que tinha o arraial dos midianitas para o norte, no vale, perto do outeiro de Moré.'),
('acf','jz',7,2,'E disse o Senhor a Gideão: Muito é o povo que está contigo, para eu dar aos midianitas em sua mão; a fim de que Israel não se glorie contra mim, dizendo: A minha mão me livrou.'),
('acf','jz',7,3,'Agora, pois, apregoa aos ouvidos do povo, dizendo: Quem for medroso e tímido, volte, e retire-se apressadamente das montanhas de Gileade. Então voltaram do povo vinte e dois mil, e dez mil ficaram.'),
('acf','jz',7,4,'E disse o Senhor a Gideão: Ainda há muito povo; faze-os descer às águas, e ali os provarei; e será que, daquele de que eu te disser: Este irá contigo, esse contigo irá; porém de todo aquele, de que eu te disser: Este não irá contigo, esse não irá.'),
('acf','jz',7,5,'E fez descer o povo às águas. Então o Senhor disse a Gideão: Qualquer que lamber as águas com a sua língua, como as lambe o cão, esse porás à parte; como também a todo aquele que se abaixar de joelhos a beber.'),
('acf','jz',7,6,'E foi o número dos que lamberam, levando a mão à boca, trezentos homens; e todo o restante do povo se abaixou de joelhos a beber as águas.'),
('acf','jz',7,7,'E disse o Senhor a Gideão: Com estes trezentos homens que lamberam as águas vos livrarei, e darei os midianitas na tua mão; portanto, todos os demais se retirem, cada um ao seu lugar.'),
('acf','jz',7,8,'E o povo tomou na sua mão a provisão e as suas buzinas, e enviou a todos os outros homens de Israel cada um à sua tenda, porém os trezentos homens reteve; e estava o arraial dos midianitas embaixo, no vale.'),
('acf','jz',7,9,'E sucedeu que, naquela mesma noite, o Senhor lhe disse: Levanta-te, e desce ao arraial, porque o tenho dado na tua mão.'),
('acf','jz',7,10,'E, se ainda temes descer, desce tu e teu moço Purá, ao arraial;'),
('acf','jz',7,11,'E ouvirás o que dizem, e então, fortalecidas as tuas mãos descerás ao arraial. Então desceu ele com o seu moço Purá até ao extremo das sentinelas que estavam no arraial.'),
('acf','jz',7,12,'E os midianitas, os amalequitas, e todos os filhos do oriente jaziam no vale como gafanhotos em multidão; e eram inumeráveis os seus camelos, como a areia que há na praia do mar.'),
('acf','jz',7,13,'Chegando, pois, Gideão, eis que estava contando um homem ao seu companheiro um sonho, e dizia: Eis que tive um sonho, eis que um pão de cevada torrado rodava pelo arraial dos midianitas, e chegava até à tenda, e a feriu, e caiu, e a transtornou de cima para baixo; e ficou caída.'),
('acf','jz',7,14,'E respondeu o seu companheiro, e disse: Não é isto outra coisa, senão a espada de Gideão, filho de Joás, varão israelita. Deus tem dado na sua mão aos midianitas, e todo este arraial.'),
('acf','jz',7,15,'E sucedeu que, ouvindo Gideão a narração deste sonho, e a sua explicação, adorou; e voltou ao arraial de Israel, e disse: Levantai-vos, porque o Senhor tem dado o arraial dos midianitas nas nossas mãos.'),
('acf','jz',7,16,'Então dividiu os trezentos homens em três companhias; e deu-lhes a cada um, nas suas mãos, buzinas, e cântaros vazios, com tochas neles acesas.'),
('acf','jz',7,17,'E disse-lhes: Olhai para mim, e fazei como eu fizer; e eis que, chegando eu à extremidade do arraial, será que, como eu fizer, assim fareis vós.'),
('acf','jz',7,18,'Tocando eu a buzina, eu e todos os que comigo estiverem, então também vós tocareis a buzina ao redor de todo o arraial, e direis: Espada do Senhor, e de Gideão.'),
('acf','jz',7,19,'Chegou, pois, Gideão, e os cem homens que com ele iam, ao extremo do arraial, ao princípio da vigília da meia-noite, havendo sido de pouco trocadas as guardas; então tocaram as buzinas, e quebraram os cântaros, que tinham nas mãos.'),
('acf','jz',7,20,'Assim tocaram as três companhias as buzinas, e quebraram os cântaros; e tinham nas suas mãos esquerdas as tochas acesas, e nas suas mãos direitas as buzinas, para tocarem, e clamaram: Espada do Senhor, e de Gideão.'),
('acf','jz',7,21,'E conservou-se cada um no seu lugar ao redor do arraial; então todo o exército pôs-se a correr e, gritando, fugiu.'),
('acf','jz',7,22,'Tocando, pois, os trezentos as buzinas, o Senhor tornou a espada de um contra o outro, e isto em todo o arraial, que fugiu para Zererá, até Bete-Sita, até aos limites de Abel-Meolá, acima de Tabate.'),
('acf','jz',7,23,'Então os homens de Israel, de Naftali, de Aser e de todo o Manassés foram convocados, e perseguiram aos midianitas.'),
('acf','jz',7,24,'Também Gideão enviou mensageiros a todas as montanhas de Efraim, dizendo: Descei ao encontro dos midianitas, e tomai-lhes as águas até Bete-Bara, e também o Jordão. Convocados, pois, todos os homens de Efraim, tomaram-lhes as águas até Bete-Bara e o Jordão.'),
('acf','jz',7,25,'E prenderam a dois príncipes dos midianitas, a Orebe e a Zeebe; e mataram a Orebe na penha de Orebe, e a Zeebe mataram no lagar de Zeebe, e perseguiram aos midianitas; e trouxeram as cabeças de Orebe e de Zeebe a Gideão, além do Jordão.'),
('acf','jz',8,1,'Então os homens de Efraim lhe disseram: Que é isto que nos fizeste, que não nos chamaste, quando foste pelejar contra os midianitas? E contenderam com ele fortemente.'),
('acf','jz',8,2,'Porém ele lhes disse: Que mais fiz eu agora do que vós? Não são porventura os rabiscos de Efraim melhores do que a vindima de Abiezer?'),
('acf','jz',8,3,'Deus vos deu na vossa mão os príncipes dos midianitas, Orebe e Zeebe; que mais pude eu fazer do que vós? Então a sua ira se abrandou para com ele, quando falou esta palavra.'),
('acf','jz',8,4,'E, como Gideão veio ao Jordão, passou com os trezentos homens que com ele estavam, já cansados, mas ainda perseguindo.'),
('acf','jz',8,5,'E disse aos homens de Sucote: Dai, peço-vos, alguns pedaços de pão ao povo, que segue as minhas pisadas; porque estão cansados, e eu vou ao encalço de Zeba e Salmuna, reis dos midianitas.'),
('acf','jz',8,6,'Porém os príncipes de Sucote disseram: Estão já, Zeba e Salmuna, em tua mão, para que demos pão ao teu exército?'),
('acf','jz',8,7,'Então disse Gideão: Pois quando o Senhor der na minha mão a Zeba e a Salmuna, trilharei a vossa carne com os espinhos do deserto, e com os abrolhos.'),
('acf','jz',8,8,'E dali subiu a Penuel, e falou-lhes da mesma maneira; e os homens de Penuel lhe responderam como os homens de Sucote lhe haviam respondido.'),
('acf','jz',8,9,'Por isso também falou aos homens de Penuel, dizendo: Quando eu voltar em paz, derribarei esta torre.'),
('acf','jz',8,10,'Estavam, pois, Zeba e Salmuna em Carcor, e os seus exércitos com eles, uns quinze mil homens, todos os que restaram do exército dos filhos do oriente; e os que caíram foram cento e vinte mil homens, que puxavam da espada.'),
('acf','jz',8,11,'E subiu Gideão pelo caminho dos que habitavam em tendas, para o oriente de Nobá e Jogbeá; e feriu aquele exército, porquanto o exército estava descuidado.'),
('acf','jz',8,12,'E fugiram Zeba e Salmuna; porém ele os perseguiu, e tomou presos a ambos os reis dos midianitas, a Zeba e a Salmuna, e afugentou a todo o exército.'),
('acf','jz',8,13,'Voltando, pois, Gideão, filho de Joás, da peleja, antes do nascer do sol,'),
('acf','jz',8,14,'Tomou preso a um moço dos homens de Sucote, e lhe fez perguntas; o qual lhe deu por escrito os nomes dos príncipes de Sucote, e dos seus anciãos, setenta e sete homens.'),
('acf','jz',8,15,'Então veio aos homens de Sucote, e disse: Vede aqui a Zeba e a Salmuna, a respeito dos quais desprezivelmente me escarnecestes, dizendo: Estão já, Zeba e Salmuna, na tua mão, para que demos pão aos teus homens, já cansados?'),
('acf','jz',8,16,'E tomou os anciãos daquela cidade, e os espinhos do deserto, e os abrolhos; e com eles ensinou aos homens de Sucote.'),
('acf','jz',8,17,'E derrubou a torre de Penuel, e matou os homens da cidade.'),
('acf','jz',8,18,'Depois perguntou a Zeba e a Salmuna: Que homens eram os que matastes em Tabor? E disseram: Como és tu, assim eram eles; cada um parecia filho de rei.'),
('acf','jz',8,19,'Então disse ele: Meus irmãos eram, filhos de minha mãe; vive o Senhor, que, se os tivésseis deixado com vida, eu não vos mataria.'),
('acf','jz',8,20,'E disse a Jeter, seu primogênito: Levanta-te, mata-os. Porém o moço não puxou da sua espada, porque temia; porquanto ainda era jovem.'),
('acf','jz',8,21,'Então disseram Zeba e Salmuna: Levanta-te, e acomete-nos; porque, qual o homem, tal a sua valentia. Levantou-se, pois, Gideão, e matou a Zeba e a Salmuna, e tomou os ornamentos que estavam nos pescoços dos seus camelos.'),
('acf','jz',8,22,'Então os homens de Israel disseram a Gideão: Domina sobre nós, tanto tu, como teu filho e o filho de teu filho; porquanto nos livraste da mão dos midianitas.'),
('acf','jz',8,23,'Porém Gideão lhes disse: Sobre vós eu não dominarei, nem tampouco meu filho sobre vós dominará; o Senhor sobre vós dominará.'),
('acf','jz',8,24,'E disse-lhes mais Gideão: Uma petição vos farei: Dá-me, cada um de vós, os pendentes do seu despojo (porque tinham pendentes de ouro, porquanto eram ismaelitas).'),
('acf','jz',8,25,'E disseram eles: De boa vontade os daremos. E estenderam uma capa, e cada um deles deitou ali um pendente do seu despojo.'),
('acf','jz',8,26,'E foi o peso dos pendentes de ouro, que pediu, mil e setecentos siclos de ouro, afora os ornamentos, e as cadeias, e as vestes de púrpura que traziam os reis dos midianitas, e afora as coleiras que os camelos traziam ao pescoço.'),
('acf','jz',8,27,'E fez Gideão dele um éfode, e colocou-o na sua cidade, em Ofra; e todo o Israel prostituiu-se ali após ele; e foi por tropeço a Gideão e à sua casa.'),
('acf','jz',8,28,'Assim foram abatidos os midianitas diante dos filhos de Israel, e nunca mais levantaram a sua cabeça; e sossegou a terra quarenta anos nos dias de Gideão.'),
('acf','jz',8,29,'E foi Jerubaal, filho de Joás, e habitou em sua casa.'),
('acf','jz',8,30,'E teve Gideão setenta filhos, que procederam dele, porque tinha muitas mulheres.'),
('acf','jz',8,31,'E sua concubina, que estava em Siquém, lhe deu à luz também um filho; e pôs-lhe por nome Abimeleque.'),
('acf','jz',8,32,'E faleceu Gideão, filho de Joás, numa boa velhice; e foi sepultado no sepulcro de seu pai Joás, em Ofra dos abiezritas.'),
('acf','jz',8,33,'E sucedeu que, como Gideão faleceu, os filhos de Israel tornaram a se prostituir após os baalins; e puseram a Baal-Berite por deus.'),
('acf','jz',8,34,'E assim os filhos de Israel não se lembraram do Senhor seu Deus, que os livrara da mão de todos os seus inimigos ao redor.'),
('acf','jz',8,35,'Nem usaram de beneficência com a casa de Jerubaal, a saber, de Gideão, conforme a todo o bem que ele havia feito a Israel.'),
('acf','jz',9,1,'E Abimeleque, filho de Jerubaal, foi a Siquém, aos irmãos de sua mãe, e falou-lhes e a toda a geração da casa do pai de sua mãe, dizendo:'),
('acf','jz',9,2,'Falai, peço-vos, aos ouvidos de todos os cidadãos de Siquém: Qual é melhor para vós, que setenta homens, todos os filhos de Jerubaal, dominem sobre vós, ou que um homem sobre vós domine? Lembrai-vos também de que sou osso vosso e carne vossa.'),
('acf','jz',9,3,'Então os irmãos de sua mãe falaram acerca dele perante os ouvidos de todos os cidadãos de Siquém todas aquelas palavras; e o coração deles se inclinou a seguir Abimeleque, porque disseram: É nosso irmão.'),
('acf','jz',9,4,'E deram-lhe setenta peças de prata, da casa de Baal-Berite; e com elas alugou Abimeleque uns homens ociosos e levianos, que o seguiram.'),
('acf','jz',9,5,'E veio à casa de seu pai, a Ofra, e matou a seus irmãos, os filhos de Jerubaal, setenta homens, sobre uma pedra. Porém Jotão, filho menor de Jerubaal, ficou, porque se tinha escondido.'),
('acf','jz',9,6,'Então se ajuntaram todos os cidadãos de Siquém, e toda a casa de Milo; e foram, e constituíram a Abimeleque rei, junto ao carvalho alto que está perto de Siquém.'),
('acf','jz',9,7,'E, dizendo-o a Jotão, foi e pôs-se no cume do monte de Gerizim, e levantou a sua voz, e clamou e disse-lhes: Ouvi-me, cidadãos de Siquém, e Deus vos ouvirá a vós;'),
('acf','jz',9,8,'Foram uma vez as árvores a ungir para si um rei, e disseram à oliveira: Reina tu sobre nós.'),
('acf','jz',9,9,'Porém a oliveira lhes disse: Deixaria eu a minha gordura, que Deus e os homens em mim prezam, e iria pairar sobre as árvores?'),
('acf','jz',9,10,'Então disseram as árvores à figueira: Vem tu, e reina sobre nós.'),
('acf','jz',9,11,'Porém a figueira lhes disse: Deixaria eu a minha doçura, o meu bom fruto, e iria pairar sobre as árvores?'),
('acf','jz',9,12,'Então disseram as árvores à videira: Vem tu, e reina sobre nós.'),
('acf','jz',9,13,'Porém a videira lhes disse: Deixaria eu o meu mosto, que alegra a Deus e aos homens, e iria pairar sobre as árvores?'),
('acf','jz',9,14,'Então todas as árvores disseram ao espinheiro: Vem tu, e reina sobre nós.'),
('acf','jz',9,15,'E disse o espinheiro às árvores: Se, na verdade, me ungis por rei sobre vós, vinde, e confiai-vos debaixo da minha sombra; mas, se não, saia fogo do espinheiro que consuma os cedros do Líbano.'),
('acf','jz',9,16,'Agora, pois, se é que em verdade e sinceridade agistes, fazendo rei a Abimeleque, e se bem fizestes para com Jerubaal e para com a sua casa, e se com ele usastes conforme ao merecimento das suas mãos'),
('acf','jz',9,17,'(Porque meu pai pelejou por vós, e desprezou a sua vida, e vos livrou da mão dos midianitas;'),
('acf','jz',9,18,'Porém vós hoje vos levantastes contra a casa de meu pai, e matastes a seus filhos, setenta homens, sobre uma pedra; e a Abimeleque, filho da sua serva, fizestes reinar sobre os cidadãos de Siquém, porque é vosso irmão);'),
('acf','jz',9,19,'Pois, se em verdade e sinceridade usastes com Jerubaal e com a sua casa hoje, alegrai-vos com Abimeleque, e também ele se alegre convosco.'),
('acf','jz',9,20,'Mas, se não, saia fogo de Abimeleque, e consuma aos cidadãos de Siquém, e a casa de Milo; e saia fogo dos cidadãos de Siquém, e da casa de Milo, que consuma a Abimeleque.'),
('acf','jz',9,21,'Então partiu Jotão, e fugiu e foi para Beer; e ali habitou por medo de Abimeleque, seu irmão.'),
('acf','jz',9,22,'Havendo, pois, Abimeleque dominado três anos sobre Israel,'),
('acf','jz',9,23,'Enviou Deus um mau espírito entre Abimeleque e os cidadãos de Siquém; e estes se houveram aleivosamente contra Abimeleque;'),
('acf','jz',9,24,'Para que a violência feita aos setenta filhos de Jerubaal viesse, e o seu sangue caísse sobre Abimeleque, seu irmão, que os matara, e sobre os cidadãos de Siquém, que fortaleceram as mãos dele para matar a seus irmãos;'),
('acf','jz',9,25,'E os cidadãos de Siquém puseram contra ele quem lhe armasse emboscadas sobre os cumes dos montes; e a todo aquele que passava pelo caminho junto a eles o assaltavam; e contou-se isso a Abimeleque.'),
('acf','jz',9,26,'Veio também Gaal, filho de Ebede, com seus irmãos, e passaram a Siquém; e os cidadãos de Siquém confiaram nele.'),
('acf','jz',9,27,'E saíram ao campo, e vindimaram as suas vinhas, e pisaram as uvas, e fizeram festas; e foram à casa de seu deus, e comeram, e beberam, e amaldiçoaram a Abimeleque.'),
('acf','jz',9,28,'E disse Gaal, filho de Ebede: Quem é Abimeleque, e quem é Siquém, para que o sirvamos? Não é porventura filho de Jerubaal? E não é Zebul o seu mordomo? Servi antes aos homens de Hamor, pai de Siquém; pois, por que razão serviríamos nós a ele?'),
('acf','jz',9,29,'Ah! se este povo estivera na minha mão, eu expulsaria a Abimeleque. E diria a Abimeleque: Multiplica o teu exército, e sai.'),
('acf','jz',9,30,'E, ouvindo Zebul, o maioral da cidade, as palavras de Gaal, filho de Ebede, se acendeu a sua ira;'),
('acf','jz',9,31,'E enviou astutamente mensageiros a Abimeleque, dizendo: Eis que Gaal, filho de Ebede, e seus irmãos vieram a Siquém, e eis que eles estão sublevando esta cidade contra ti.'),
('acf','jz',9,32,'Levanta-te, pois, de noite, tu e o povo que tiveres contigo, e põe emboscadas no campo.'),
('acf','jz',9,33,'E levanta-te pela manhã ao sair o sol, e dá de golpe sobre a cidade; e eis que, saindo contra ti, ele e o povo que tiver com ele, faze-lhe como puderes.'),
('acf','jz',9,34,'Levantou-se, pois, Abimeleque, e todo o povo que com ele havia, de noite, e puseram emboscadas a Siquém, com quatro tropas.'),
('acf','jz',9,35,'E Gaal, filho de Ebede, saiu, e pôs-se à entrada da porta da cidade; e Abimeleque, e todo o povo que com ele havia, se levantou das emboscadas.'),
('acf','jz',9,36,'E, vendo Gaal aquele povo, disse a Zebul: Eis que desce gente dos cumes dos montes. Zebul, ao contrário, lhe disse: As sombras dos montes vês como se fossem homens.'),
('acf','jz',9,37,'Porém Gaal ainda tornou a falar, e disse: Eis ali desce gente do meio da terra, e uma tropa vem do caminho do carvalho de Meonenim.'),
('acf','jz',9,38,'Então lhe disse Zebul: Onde está agora a tua boca, com a qual dizias: Quem é Abimeleque, para que o sirvamos? Não é este porventura o povo que desprezaste? Sai pois, peço-te, e peleja contra ele.'),
('acf','jz',9,39,'E saiu Gaal à vista dos cidadãos de Siquém, e pelejou contra Abimeleque.'),
('acf','jz',9,40,'E Abimeleque o perseguiu porquanto fugiu de diante dele; e muitos feridos caíram até à entrada da porta da cidade.'),
('acf','jz',9,41,'E Abimeleque ficou em Aruma. E Zebul expulsou a Gaal e a seus irmãos, para que não pudessem habitar em Siquém.'),
('acf','jz',9,42,'E sucedeu no dia seguinte que o povo saiu ao campo; disto foi avisado Abimeleque.'),
('acf','jz',9,43,'Então tomou o povo, e o repartiu em três tropas, e pôs emboscadas no campo; e olhou, e eis que o povo saía da cidade, e levantou-se contra ele, e o feriu.'),
('acf','jz',9,44,'Porque Abimeleque, e as tropas que com ele havia, romperam de improviso, e pararam à entrada da porta da cidade; e as outras duas tropas deram de improviso sobre todos quantos estavam no campo, e os feriram.'),
('acf','jz',9,45,'E Abimeleque pelejou contra a cidade todo aquele dia, e tomou a cidade, e matou o povo que nela havia; e assolou a cidade, e a semeou de sal.'),
('acf','jz',9,46,'O que ouvindo todos os cidadãos da torre de Siquém, entraram na fortaleza, na casa do deus Berite.'),
('acf','jz',9,47,'E contou-se a Abimeleque que todos os cidadãos da torre de Siquém se haviam congregado.'),
('acf','jz',9,48,'Subiu, pois, Abimeleque ao monte Salmom, ele e todo o povo que com ele havia; e Abimeleque tomou na sua mão um machado, e cortou um ramo de árvore, e o levantou, e pô-lo ao seu ombro, e disse ao povo, que com ele havia: O que me vistes fazer apressai-vos a fazê-lo assim como eu.'),
('acf','jz',9,49,'Assim, pois, cada um de todo o povo, também cortou o seu ramo e seguiu a Abimeleque; e pondo os ramos junto da fortaleza, queimaram-na a fogo com os que nela estavam, de modo que todos os da torre de Siquém morreram, uns mil homens e mulheres.'),
('acf','jz',9,50,'Então Abimeleque foi a Tebes e a sitiou, e a tomou.'),
('acf','jz',9,51,'Havia, porém, no meio da cidade uma torre forte; e todos os homens e mulheres, e todos os cidadãos da cidade se refugiaram nela, e fecharam após si as portas, e subiram ao eirado da torre.'),
('acf','jz',9,52,'E Abimeleque veio até à torre, e a combateu; e chegou-se até à porta da torre, para a incendiar.'),
('acf','jz',9,53,'Porém uma mulher lançou um pedaço de uma mó sobre a cabeça de Abimeleque; e quebrou-lhe o crânio.'),
('acf','jz',9,54,'Então chamou logo ao moço, que levava as suas armas, e disse-lhe: Desembainha a tua espada, e mata-me; para que não se diga de mim: Uma mulher o matou. E o moço o atravessou e ele morreu.'),
('acf','jz',9,55,'Vendo, pois, os homens de Israel que Abimeleque já era morto, foram-se cada um para o seu lugar.'),
('acf','jz',9,56,'Assim Deus fez tornar sobre Abimeleque o mal que tinha feito a seu pai, matando a seus setenta irmãos.'),
('acf','jz',9,57,'Como também todo o mal dos homens de Siquém fez tornar sobre a cabeça deles; e a maldição de Jotão, filho de Jerubaal, veio sobre eles.'),
('acf','jz',10,1,'E depois de Abimeleque, se levantou, para livrar a Israel, Tola, filho de Puá, filho de Dodo, homem de Issacar; e habitava em Samir, na montanha de Efraim.'),
('acf','jz',10,2,'E julgou a Israel vinte e três anos; e morreu, e foi sepultado em Samir.'),
('acf','jz',10,3,'E depois dele se levantou Jair, gileadita, e julgou a Israel vinte e dois anos.'),
('acf','jz',10,4,'E tinha este trinta filhos, que cavalgavam sobre trinta jumentos; e tinham trinta cidades, a que chamaram Havote-Jair, até ao dia de hoje; as quais estão na terra de Gileade.'),
('acf','jz',10,5,'E morreu Jair, e foi sepultado em Camom.'),
('acf','jz',10,6,'Então tornaram os filhos de Israel a fazer o que era mau aos olhos do Senhor, e serviram aos baalins, e a Astarote, e aos deuses da Síria, e aos deuses de Sidom, e aos deuses de Moabe, e aos deuses dos filhos de Amom, e aos deuses dos filisteus; e deixaram ao Senhor, e não o serviram.'),
('acf','jz',10,7,'E a ira do Senhor se acendeu contra Israel; e vendeu-os nas mãos dos filisteus, e nas mãos dos filhos de Amom.'),
('acf','jz',10,8,'E naquele mesmo ano oprimiram e vexaram aos filhos de Israel; dezoito anos oprimiram a todos os filhos de Israel que estavam além do Jordão, na terra dos amorreus, que está em Gileade.'),
('acf','jz',10,9,'Até os filhos de Amom passaram o Jordão, para pelejar também contra Judá, e contra Benjamim, e contra a casa de Efraim; de modo que Israel ficou muito angustiado.'),
('acf','jz',10,10,'Então os filhos de Israel clamaram ao Senhor, dizendo: Contra ti havemos pecado, visto que deixamos a nosso Deus, e servimos aos baalins.'),
('acf','jz',10,11,'Porém o Senhor disse aos filhos de Israel: Porventura dos egípcios, e dos amorreus, e dos filhos de Amom, e dos filisteus,'),
('acf','jz',10,12,'E dos sidônios, e dos amalequitas, e dos maonitas, que vos oprimiam, quando a mim clamastes, não vos livrei das suas mãos?'),
('acf','jz',10,13,'Contudo vós me deixastes a mim, e servistes a outros deuses; pelo que não vos livrarei mais.'),
('acf','jz',10,14,'Ide, e clamai aos deuses que escolhestes; que eles vos livrem no tempo do vosso aperto.'),
('acf','jz',10,15,'Mas os filhos de Israel disseram ao Senhor: Pecamos; faze-nos conforme a tudo quanto te parecer bem aos teus olhos; tão-somente te rogamos que nos livres nesta vez.'),
('acf','jz',10,16,'E tiraram os deuses alheios do meio de si, e serviram ao Senhor; então se angustiou a sua alma por causa da desgraça de Israel.'),
('acf','jz',10,17,'E os filhos de Amom se reuniram e se acamparam em Gileade; e também os de Israel se congregaram, e se acamparam em Mizpá.'),
('acf','jz',10,18,'Então o povo e os príncipes de Gileade disseram uns aos outros: Quem será o homem que começará a pelejar contra os filhos de Amom? Ele será por cabeça de todos os moradores de Gileade.'),
('acf','jz',11,1,'Era então Jefté, o gileadita, homem valoroso, porém filho de uma prostituta; mas Gileade gerara a Jefté.'),
('acf','jz',11,2,'Também a mulher de Gileade lhe deu filhos, e, sendo os filhos desta mulher já grandes, expulsaram a Jefté, e lhe disseram: Não herdarás na casa de nosso pai, porque és filho de outra mulher.'),
('acf','jz',11,3,'Então Jefté fugiu de diante de seus irmãos, e habitou na terra de Tobe; e homens levianos se ajuntaram a Jefté, e saíam com ele.'),
('acf','jz',11,4,'E aconteceu que, depois de algum tempo, os filhos de Amom pelejaram contra Israel.'),
('acf','jz',11,5,'E sucedeu que, como os filhos de Amom pelejassem contra Israel, foram os anciãos de Gileade buscar a Jefté na terra de Tobe.'),
('acf','jz',11,6,'E disseram a Jefté: Vem, e sê o nosso chefe; para que combatamos contra os filhos de Amom.'),
('acf','jz',11,7,'Porém Jefté disse aos anciãos de Gileade: Porventura não me odiastes a mim, e não me expulsastes da casa de meu pai? Por que, pois, agora viestes a mim, quando estais em aperto?'),
('acf','jz',11,8,'E disseram os anciãos de Gileade a Jefté: Por isso tornamos a ti, para que venhas conosco, e combatas contra os filhos de Amom; e nos sejas por chefe sobre todos os moradores de Gileade.'),
('acf','jz',11,9,'Então Jefté disse aos anciãos de Gileade: Se me levardes de volta para combater contra os filhos de Amom, e o Senhor mos der diante de mim, então eu vos serei por chefe?'),
('acf','jz',11,10,'E disseram os anciãos de Gileade a Jefté: O Senhor será testemunha entre nós, e assim o faremos conforme a tua palavra.'),
('acf','jz',11,11,'Assim Jefté foi com os anciãos de Gileade, e o povo o pôs por chefe e príncipe sobre si; e Jefté falou todas as suas palavras perante o Senhor em Mizpá.'),
('acf','jz',11,12,'E enviou Jefté mensageiros ao rei dos filhos de Amom, dizendo: Que há entre mim e ti, que vieste a mim a pelejar contra a minha terra?'),
('acf','jz',11,13,'E disse o rei dos filhos de Amom aos mensageiros de Jefté: É porque, saindo Israel do Egito, tomou a minha terra, desde Arnom até Jaboque, e ainda até ao Jordão: Restitui-ma agora, em paz.'),
('acf','jz',11,14,'Porém Jefté prosseguiu ainda em enviar mensageiros ao rei dos filhos de Amom,'),
('acf','jz',11,15,'Dizendo-lhe: Assim diz Jefté: Israel não tomou, nem a terra dos moabitas, nem a terra dos filhos de Amom.'),
('acf','jz',11,16,'Porque, subindo Israel do Egito, andou pelo deserto até ao Mar Vermelho, e chegou até Cades.'),
('acf','jz',11,17,'E Israel enviou mensageiros ao rei dos edomitas, dizendo: Rogo-te que me deixes passar pela tua terra. Porém o rei dos edomitas não lhe deu ouvidos; enviou também ao rei dos moabitas, o qual igualmente não consentiu; e assim Israel ficou em Cades.'),
('acf','jz',11,18,'Depois andou pelo deserto e rodeou a terra dos edomitas e a terra dos moabitas, e veio do nascente do sol à terra dos moabitas, e alojou-se além de Arnom; porém não entrou nos limites dos moabitas, porque Arnom é limite dos moabitas.'),
('acf','jz',11,19,'Mas Israel enviou mensageiros a Siom, rei dos amorreus, rei de Hesbom; e disse-lhe Israel: Deixa-nos, peço-te, passar pela tua terra até ao meu lugar.'),
('acf','jz',11,20,'Porém Siom não confiou em Israel para este passar nos seus limites; antes Siom ajuntou todo o seu povo, e se acamparam em Jasa, e combateu contra Israel.'),
('acf','jz',11,21,'E o Senhor Deus de Israel deu a Siom, com todo o seu povo, na mão de Israel, que os feriu; e Israel tomou por herança toda a terra dos amorreus que habitavam naquela região.'),
('acf','jz',11,22,'E por herança tomaram todos os limites dos amorreus, desde Arnom até Jaboque, e desde o deserto até ao Jordão.'),
('acf','jz',11,23,'Assim o Senhor Deus de Israel desapossou os amorreus de diante do seu povo de Israel; e os possuirias tu?'),
('acf','jz',11,24,'Não possuirias tu aquilo que Quemós, teu deus, desapossasse de diante de ti? Assim possuiremos nós todos quantos o Senhor nosso Deus desapossar de diante de nós.'),
('acf','jz',11,25,'Agora, pois, és tu ainda melhor do que Balaque, filho de Zipor, rei dos moabitas? Porventura contendeu ele em algum tempo com Israel, ou pelejou alguma vez contra ele?'),
('acf','jz',11,26,'Enquanto Israel habitou trezentos anos em Hesbom e nas suas vilas, e em Aroer e nas suas vilas, em todas as cidades que estão ao longo de Arnom, por que o não recuperastes naquele tempo?'),
('acf','jz',11,27,'Tampouco pequei eu contra ti! Porém tu usas mal comigo em pelejar contra mim; o Senhor, que é juiz julgue hoje entre os filhos de Israel e entre os filhos de Amom.'),
('acf','jz',11,28,'Porém o rei dos filhos de Amom não deu ouvidos às palavras que Jefté lhe enviou.'),
('acf','jz',11,29,'Então o Espírito do Senhor veio sobre Jefté, e atravessou ele por Gileade e Manassés, passando por Mizpá de Gileade, e de Mizpá de Gileade passou até aos filhos de Amom.'),
('acf','jz',11,30,'E Jefté fez um voto ao Senhor, e disse: Se totalmente deres os filhos de Amom na minha mão,'),
('acf','jz',11,31,'Aquilo que, saindo da porta de minha casa, me vier ao encontro, voltando eu dos filhos de Amom em paz, isso será do Senhor, e o oferecerei em holocausto.'),
('acf','jz',11,32,'Assim Jefté passou aos filhos de Amom, a combater contra eles; e o Senhor os deu na sua mão.'),
('acf','jz',11,33,'E os feriu com grande mortandade, desde Aroer até chegar a Minite, vinte cidades, e até Abel-Queramim; assim foram subjugados os filhos de Amom diante dos filhos de Israel.'),
('acf','jz',11,34,'Vindo, pois, Jefté a Mizpá, à sua casa, eis que a sua filha lhe saiu ao encontro com adufes e com danças; e era ela a única filha; não tinha ele outro filho nem filha.'),
('acf','jz',11,35,'E aconteceu que, quando a viu, rasgou as suas vestes, e disse: Ah! filha minha, muito me abateste, e estás entre os que me turbam! Porque eu abri a minha boca ao Senhor, e não tornarei atrás.'),
('acf','jz',11,36,'E ela lhe disse: Meu pai, tu deste a palavra ao Senhor, faze de mim conforme o que prometeste; pois o Senhor te vingou dos teus inimigos, os filhos de Amom.'),
('acf','jz',11,37,'Disse mais a seu pai: Concede-me isto: Deixa-me por dois meses que vá, e desça pelos montes, e chore a minha virgindade, eu e as minhas companheiras.'),
('acf','jz',11,38,'E disse ele: Vai. E deixou-a ir por dois meses; então foi ela com as suas companheiras, e chorou a sua virgindade pelos montes.'),
('acf','jz',11,39,'E sucedeu que, ao fim de dois meses, tornou ela para seu pai, o qual cumpriu nela o seu voto que tinha feito; e ela não conheceu homem; e daí veio o costume de Israel,'),
('acf','jz',11,40,'Que as filhas de Israel iam de ano em ano lamentar, por quatro dias, a filha de Jefté, o gileadita.'),
('acf','jz',12,1,'Então se convocaram os homens de Efraim, e passaram para o norte, e disseram a Jefté: Por que passaste a combater contra os filhos de Amom, e não nos chamaste para ir contigo? Queimaremos a fogo a tua casa contigo.'),
('acf','jz',12,2,'E Jefté lhes disse: Eu e o meu povo tivemos grande contenda com os filhos de Amom; e chamei-vos, e não me livrastes da sua mão;'),
('acf','jz',12,3,'E, vendo eu que não me livráveis, arrisquei a minha vida, e passei contra os filhos de Amom, e o Senhor mos entregou nas mãos; por que, pois, subistes vós hoje, para combater contra mim?'),
('acf','jz',12,4,'E ajuntou Jefté a todos os homens de Gileade, e combateu contra Efraim; e os homens de Gileade feriram a Efraim; porque este dissera-lhe: Fugitivos sois de Efraim, vós gileaditas que habitais entre Efraim e Manassés,'),
('acf','jz',12,5,'Porque tomaram os gileaditas aos efraimitas os vaus do Jordão; e sucedeu que, quando algum dos fugitivos de Efraim dizia: Deixai-me passar; então os gileaditas perguntavam: És tu efraimita? E dizendo ele: Não,'),
('acf','jz',12,6,'Então lhe diziam: Dize, pois, Chibolete; porém ele dizia: Sibolete; porque não o podia pronunciar bem; então pegavam dele, e o degolavam nos vaus do Jordão; e caíram de Efraim naquele tempo quarenta e dois mil.'),
('acf','jz',12,7,'E Jefté julgou a Israel seis anos; e Jefté, o gileadita, faleceu, e foi sepultado numa das cidades de Gileade.'),
('acf','jz',12,8,'E depois dele julgou a Israel Ibzã de Belém.'),
('acf','jz',12,9,'E tinha este trinta filhos, e trinta filhas que casou fora; e trinta filhas trouxe de fora para seus filhos; e julgou a Israel sete anos.'),
('acf','jz',12,10,'Então faleceu Ibzã, e foi sepultado em Belém.'),
('acf','jz',12,11,'E depois dele julgou a Israel Elom, o zebulonita; e julgou a Israel dez anos.'),
('acf','jz',12,12,'E faleceu Elom, o zebulonita, e foi sepultado em Aijalom, na terra de Zebulom.'),
('acf','jz',12,13,'E depois dele julgou a Israel Abdom, filho de Hilel, o piratonita.'),
('acf','jz',12,14,'E tinha este quarenta filhos, e trinta netos, que cavalgavam sobre setenta jumentos; e julgou a Israel oito anos.'),
('acf','jz',12,15,'Então faleceu Abdom, filho de Hilel, o piratonita; e foi sepultado em Piratom, na terra de Efraim, no monte dos amalequitas.'),
('acf','jz',13,1,'E os filhos de Israel tornaram a fazer o que era mau aos olhos do SENHOR, e o SENHOR os entregou na mão dos filisteus por quarenta anos.'),
('acf','jz',13,2,'E havia um homem de Zorá, da tribo de Dã, cujo nome era Manoá; e sua mulher, sendo estéril, não tinha filhos.'),
('acf','jz',13,3,'E o anjo do Senhor apareceu a esta mulher, e disse-lhe: Eis que agora és estéril, e nunca tens concebido; porém conceberás, e terás um filho.'),
('acf','jz',13,4,'Agora, pois, guarda-te de beber vinho, ou bebida forte, ou comer coisa imunda.'),
('acf','jz',13,5,'Porque eis que tu conceberás e terás um filho sobre cuja cabeça não passará navalha; porquanto o menino será nazireu de Deus desde o ventre; e ele começará a livrar a Israel da mão dos filisteus.'),
('acf','jz',13,6,'Então a mulher entrou, e falou a seu marido, dizendo: Um homem de Deus veio a mim, cuja aparência era semelhante a de um anjo de Deus, terribilíssima; e não lhe perguntei donde era, nem ele me disse o seu nome.'),
('acf','jz',13,7,'Porém disse-me: Eis que tu conceberás e terás um filho; agora pois, não bebas vinho, nem bebida forte, e não comas coisa imunda; porque o menino será nazireu de Deus, desde o ventre até ao dia da sua morte.'),
('acf','jz',13,8,'Então Manoá orou ao Senhor, e disse: Ah! Senhor meu, rogo-te que o homem de Deus, que enviaste, ainda venha para nós outra vez e nos ensine o que devemos fazer ao menino que há de nascer.'),
('acf','jz',13,9,'E Deus ouviu a voz de Manoá; e o anjo de Deus veio outra vez à mulher, e ela estava no campo, porém não estava com ela seu marido Manoá.'),
('acf','jz',13,10,'Apressou-se, pois, a mulher, e correu, e noticiou-o a seu marido, e disse-lhe: Eis que aquele homem que veio a mim o outro dia me apareceu.'),
('acf','jz',13,11,'Então Manoá levantou-se, e seguiu a sua mulher, e foi àquele homem, e disse-lhe: És tu aquele homem que falou a esta mulher? E disse: Eu sou.'),
('acf','jz',13,12,'Então disse Manoá: Cumpram-se as tuas palavras; mas qual será o modo de viver e o serviço do menino?'),
('acf','jz',13,13,'E disse o anjo do Senhor a Manoá: De tudo quanto eu disse à mulher se guardará ela.'),
('acf','jz',13,14,'De tudo quanto procede da videira não comerá, nem vinho nem bebida forte beberá, nem coisa imunda comerá; tudo quanto lhe tenho ordenado guardará.'),
('acf','jz',13,15,'Então Manoá disse ao anjo do Senhor: Ora deixa que te detenhamos, e te preparemos um cabrito.'),
('acf','jz',13,16,'Porém o anjo do Senhor disse a Manoá: Ainda que me detenhas, não comerei de teu pão; e se fizeres holocausto o oferecerás ao Senhor. Porque não sabia Manoá que era o anjo do Senhor.'),
('acf','jz',13,17,'E disse Manoá ao anjo do Senhor: Qual é o teu nome, para que, quando se cumprir a tua palavra, te honremos?'),
('acf','jz',13,18,'E o anjo do Senhor lhe disse: Por que perguntas assim pelo meu nome, visto que é maravilhoso?'),
('acf','jz',13,19,'Então Manoá tomou um cabrito e uma oferta de alimentos, e os ofereceu sobre uma penha ao Senhor: e houve-se o anjo maravilhosamente, observando-o Manoá e sua mulher.'),
('acf','jz',13,20,'E sucedeu que, subindo a chama do altar para o céu, o anjo do Senhor subiu na chama do altar; o que vendo Manoá e sua mulher, caíram em terra sobre seus rostos.'),
('acf','jz',13,21,'E nunca mais apareceu o anjo do Senhor a Manoá, nem a sua mulher; então compreendeu Manoá que era o anjo do Senhor.'),
('acf','jz',13,22,'E disse Manoá à sua mulher: Certamente morreremos, porquanto temos visto a Deus.'),
('acf','jz',13,23,'Porém sua mulher lhe disse: Se o Senhor nos quisesse matar, não aceitaria da nossa mão o holocausto e a oferta de alimentos, nem nos mostraria tudo isto, nem nos deixaria ouvir tais coisas neste tempo.'),
('acf','jz',13,24,'Depois teve esta mulher um filho, a quem pôs o nome de Sansão; e o menino cresceu, e o Senhor o abençoou.'),
('acf','jz',13,25,'E o Espírito do SENHOR começou a incitá-lo de quando em quando para o campo de Maané-Dã, entre Zorá e Estaol.'),
('acf','jz',14,1,'E desceu Sansão a Timnate; e, vendo em Timnate uma mulher das filhas dos filisteus,'),
('acf','jz',14,2,'Subiu, e declarou-o a seu pai e a sua mãe, e disse: Vi uma mulher em Timnate, das filhas dos filisteus; agora, pois, tomai-ma por mulher.'),
('acf','jz',14,3,'Porém seu pai e sua mãe lhe disseram: Não há, porventura, mulher entre as filhas de teus irmãos, nem entre todo o meu povo, para que tu vás tomar mulher dos filisteus, daqueles incircuncisos? E disse Sansão a seu pai: Toma-me esta, porque ela agrada aos meus olhos.'),
('acf','jz',14,4,'Mas seu pai e sua mãe não sabiam que isto vinha do Senhor; pois buscava ocasião contra os filisteus; porquanto naquele tempo os filisteus dominavam sobre Israel.'),
('acf','jz',14,5,'Desceu, pois, Sansão com seu pai e com sua mãe a Timnate; e, chegando às vinhas de Timnate eis que um filho de leão, rugindo, lhe saiu ao encontro.'),
('acf','jz',14,6,'Então o Espírito do Senhor se apossou dele tão poderosamente que despedaçou o leão, como quem despedaça um cabrito, sem ter nada na sua mão; porém nem a seu pai nem a sua mãe deu a saber o que tinha feito.'),
('acf','jz',14,7,'E desceu, e falou àquela mulher, e ela agradou aos olhos de Sansão.'),
('acf','jz',14,8,'E depois de alguns dias voltou ele para tomá-la; e, apartando-se do caminho para ver o corpo do leão morto, eis que nele havia um enxame de abelhas com mel.'),
('acf','jz',14,9,'E tomou-o nas suas mãos, e foi andando e comendo dele; e foi a seu pai e a sua mãe, e deu-lhes do mel, e comeram; porém não lhes deu a saber que tomara o mel do corpo do leão.'),
('acf','jz',14,10,'Descendo, pois, seu pai àquela mulher, fez Sansão ali um banquete; porque assim os moços costumavam fazer.'),
('acf','jz',14,11,'E sucedeu que, como o vissem, trouxeram trinta companheiros para estarem com ele.'),
('acf','jz',14,12,'Disse-lhes, pois, Sansão: Eu vos darei um enigma para decifrar; e, se nos sete dias das bodas o decifrardes e descobrirdes, eu vos darei trinta lençóis e trinta mudas de roupas.'),
('acf','jz',14,13,'E, se não puderdes decifrar, vós me dareis a mim trinta lençóis e as trinta mudas de roupas. E eles lhe disseram: Dá-nos o teu enigma a decifrar, para que o ouçamos.'),
('acf','jz',14,14,'Então lhes disse: Do comedor saiu comida, e do forte saiu doçura. E em três dias não puderam decifrar o enigma.'),
('acf','jz',14,15,'E sucedeu que, ao sétimo dia, disseram à mulher de Sansão: Persuade a teu marido que nos declare o enigma, para que porventura não queimemos a fogo a ti e à casa de teu pai; chamastes-nos aqui para vos apossardes do que é nosso, não é assim?'),
('acf','jz',14,16,'E a mulher de Sansão chorou diante dele, e disse: Tão-somente me desprezas, e não me amas; pois deste aos filhos do meu povo um enigma para decifrar, e ainda não o declaraste a mim. E ele lhe disse: Eis que nem a meu pai nem a minha mãe o declarei, e to declararia a ti?'),
('acf','jz',14,17,'E chorou diante dele os sete dias em que celebravam as bodas; sucedeu, pois, que ao sétimo dia lho declarou, porquanto o importunava; então ela declarou o enigma aos filhos do seu povo.'),
('acf','jz',14,18,'Disseram, pois, a Sansão os homens daquela cidade, ao sétimo dia, antes de se pôr o sol: Que coisa há mais doce do que o mel? E que coisa há mais forte do que o leão? E ele lhes disse: Se vós não lavrásseis com a minha novilha, nunca teríeis descoberto o meu enigma.'),
('acf','jz',14,19,'Então o Espírito do Senhor tão poderosamente se apossou dele, que desceu aos ascalonitas, e matou deles trinta homens, e tomou as suas roupas, e deu as mudas de roupas aos que declararam o enigma; porém acendeu-se a sua ira, e subiu à casa de seu pai.'),
('acf','jz',14,20,'E a mulher de Sansão foi dada ao seu companheiro que antes o acompanhava.'),
('acf','jz',15,1,'E aconteceu, depois de alguns dias, que, na sega do trigo, Sansão visitou a sua mulher, com um cabrito, e disse: Entrarei na câmara de minha mulher. Porém o pai dela não o deixou entrar.'),
('acf','jz',15,2,'E disse-lhe seu pai: Por certo pensava eu que de todo a desprezavas; de sorte que a dei ao teu companheiro; porém não é sua irmã mais nova, mais formosa do que ela? Toma-a, pois, em seu lugar.'),
('acf','jz',15,3,'Então Sansão disse acerca deles: Inocente sou esta vez para com os filisteus, quando lhes fizer algum mal.'),
('acf','jz',15,4,'E foi Sansão, e pegou trezentas raposas; e, tomando tochas, as virou cauda a cauda, e lhes pôs uma tocha no meio de cada duas caudas.'),
('acf','jz',15,5,'E chegou fogo às tochas, e largou-as na seara dos filisteus; e assim abrasou os molhos com a sega do trigo, e as vinhas e os olivais.'),
('acf','jz',15,6,'Então perguntaram os filisteus: Quem fez isto? E responderam: Sansão, o genro do timnita, porque lhe tomou a sua mulher, e a deu a seu companheiro. Então subiram os filisteus, e queimaram a fogo a ela e a seu pai.'),
('acf','jz',15,7,'Então lhes disse Sansão: É assim que fazeis? Pois, havendo-me vingado eu de vós, então cessarei.'),
('acf','jz',15,8,'E feriu-os com grande ferimento, pernas juntamente com coxa; e desceu, e habitou na fenda da rocha de Etã.'),
('acf','jz',15,9,'Então os filisteus subiram, e acamparam-se contra Judá, e estenderam-se por Leí.'),
('acf','jz',15,10,'E perguntaram-lhes os homens de Judá: Por que subistes contra nós? E eles responderam: Subimos para amarrar a Sansão, para lhe fazer a ele como ele nos fez a nós.'),
('acf','jz',15,11,'Então três mil homens de Judá desceram até a fenda da rocha de Etã, e disseram a Sansão: Não sabias tu que os filisteus dominam sobre nós? Por que, pois, nos fizeste isto? E ele lhes disse: Assim como eles me fizeram a mim, eu lhes fiz a eles.'),
('acf','jz',15,12,'E disseram-lhe: Descemos para te amarrar e te entregar nas mãos dos filisteus. Então Sansão lhes disse: Jurai-me que vós mesmos não me acometereis.'),
('acf','jz',15,13,'E eles lhe falaram, dizendo: Não, mas fortemente te amarraremos, e te entregaremos nas mãos deles; porém de maneira nenhuma te mataremos. E amarraram-no com duas cordas novas e fizeram-no subir da rocha.'),
('acf','jz',15,14,'E, vindo ele a Leí, os filisteus lhe saíram ao encontro, jubilando; porém o Espírito do Senhor poderosamente se apossou dele, e as cordas que ele tinha nos braços se tornaram como fios de linho que se queimaram no fogo, e as suas amarraduras se desfizeram das suas mãos.'),
('acf','jz',15,15,'E achou uma queixada fresca de um jumento, e estendeu a sua mão, e tomou-a, e feriu com ela mil homens.'),
('acf','jz',15,16,'Então disse Sansão: Com uma queixada de jumento, montões sobre montões; com uma queixada de jumento feri a mil homens.'),
('acf','jz',15,17,'E aconteceu que, acabando ele de falar, lançou a queixada da sua mão; e chamou aquele lugar Ramate-Leí.'),
('acf','jz',15,18,'E como tivesse grande sede, clamou ao Senhor, e disse: Pela mão do teu servo tu deste esta grande salvação; morrerei eu pois agora de sede, e cairei na mão destes incircuncisos?'),
('acf','jz',15,19,'Então Deus fendeu uma cavidade que estava na queixada; e saiu dela água, e bebeu; e recobrou o seu espírito e reanimou-se; por isso chamou aquele lugar: A fonte do que clama, que está em Leí até ao dia de hoje.'),
('acf','jz',15,20,'E julgou a Israel, nos dias dos filisteus, vinte anos.'),
('acf','jz',16,1,'E foi Sansão a Gaza, e viu ali uma mulher prostituta, e entrou a ela.'),
('acf','jz',16,2,'E foi dito aos gazitas: Sansão entrou aqui. Cercaram-no, e toda a noite lhe puseram espias à porta da cidade; porém toda a noite estiveram quietos, dizendo: Até à luz da manhã esperaremos; então o mataremos.'),
('acf','jz',16,3,'Porém Sansão deitou-se até à meia-noite, e à meia-noite se levantou, e arrancou as portas da entrada da cidade com ambas as umbreiras, e juntamente com a tranca as tomou, pondo-as sobre os ombros; e levou-as para cima até ao cume do monte que está defronte de Hebrom.'),
('acf','jz',16,4,'E depois disto aconteceu que se afeiçoou a uma mulher do vale de Soreque, cujo nome era Dalila.'),
('acf','jz',16,5,'Então os príncipes dos filisteus subiram a ela, e lhe disseram: Persuade-o, e vê em que consiste a sua grande força, e como poderíamos assenhorear-nos dele e amarrá-lo, para assim o afligirmos; e te daremos, cada um de nós, mil e cem moedas de prata.'),
('acf','jz',16,6,'Disse, pois, Dalila a Sansão: Declara-me, peço-te, em que consiste a tua grande força, e com que poderias ser amarrado para te poderem afligir.'),
('acf','jz',16,7,'Disse-lhe Sansão: Se me amarrassem com sete vergas de vimes frescos, que ainda não estivessem secos, então me enfraqueceria, e seria como qualquer outro homem.'),
('acf','jz',16,8,'Então os príncipes dos filisteus lhe trouxeram sete vergas de vimes frescos, que ainda não estavam secos; e amarraram-no com elas.'),
('acf','jz',16,9,'E o espia estava com ela na câmara interior. Então ela lhe disse: Os filisteus vêm sobre ti, Sansão. Então quebrou as vergas de vimes, como se quebra o fio da estopa ao cheiro do fogo; assim não se soube em que consistia a sua força.'),
('acf','jz',16,10,'Então disse Dalila a Sansão: Eis que zombaste de mim, e me disseste mentiras; ora declara-me agora com que poderias ser amarrado.'),
('acf','jz',16,11,'E ele disse: Se me amarrassem fortemente com cordas novas, que ainda não houvessem sido usadas, então me enfraqueceria, e seria como qualquer outro homem.'),
('acf','jz',16,12,'Então Dalila tomou cordas novas, e o amarrou com elas, e disse-lhe: Os filisteus vêm sobre ti, Sansão. E o espia estava na recâmara interior. Então as quebrou de seus braços como a um fio.'),
('acf','jz',16,13,'E disse Dalila a Sansão: Até agora zombaste de mim, e me disseste mentiras; declara-me pois, agora, com que poderias ser amarrado? E ele lhe disse: Se teceres sete tranças dos cabelos da minha cabeça com os liços da teia.'),
('acf','jz',16,14,'E ela as fixou com uma estaca, e disse-lhe: Os filisteus vêm sobre ti, Sansão: Então ele despertou do seu sono, e arrancou a estaca das tranças tecidas, juntamente com o liço da teia.'),
('acf','jz',16,15,'Então ela lhe disse: Como dirás: Tenho-te amor, não estando comigo o teu coração? Já três vezes zombaste de mim, e ainda não me declaraste em que consiste a tua força.'),
('acf','jz',16,16,'E sucedeu que, importunando-o ela todos os dias com as suas palavras, e molestando-o, a sua alma se angustiou até a morte.'),
('acf','jz',16,17,'E descobriu-lhe todo o seu coração, e disse-lhe: Nunca passou navalha pela minha cabeça, porque sou nazireu de Deus desde o ventre de minha mãe; se viesse a ser rapado, ir-se-ia de mim a minha força, e me enfraqueceria, e seria como qualquer outro homem.'),
('acf','jz',16,18,'Vendo, pois, Dalila que já lhe descobrira todo o seu coração, mandou chamar os príncipes dos filisteus, dizendo: Subi esta vez, porque agora me descobriu ele todo o seu coração. E os príncipes dos filisteus subiram a ter com ela, trazendo com eles o dinheiro.'),
('acf','jz',16,19,'Então ela o fez dormir sobre os seus joelhos, e chamou a um homem, e rapou-lhe as sete tranças do cabelo de sua cabeça; e começou a afligi-lo, e retirou-se dele a sua força.'),
('acf','jz',16,20,'E disse ela: Os filisteus vêm sobre ti, Sansão. E despertou ele do seu sono, e disse: Sairei ainda esta vez como dantes, e me sacudirei. Porque ele não sabia que já o Senhor se tinha retirado dele.'),
('acf','jz',16,21,'Então os filisteus pegaram nele, e arrancaram-lhe os olhos, e fizeram-no descer a Gaza, e amarraram-no com duas cadeias de bronze, e girava ele um moinho no cárcere.'),
('acf','jz',16,22,'E o cabelo da sua cabeça começou a crescer, como quando foi rapado.'),
('acf','jz',16,23,'Então os príncipes dos filisteus se ajuntaram para oferecer um grande sacrifício ao seu deus Dagom, e para se alegrarem, e diziam: Nosso deus nos entregou nas mãos a Sansão, nosso inimigo.'),
('acf','jz',16,24,'Semelhantemente, vendo-o o povo, louvava ao seu deus; porque dizia: Nosso deus nos entregou nas mãos o nosso inimigo, e ao que destruía a nossa terra, e ao que multiplicava os nossos mortos.'),
('acf','jz',16,25,'E sucedeu que, alegrando-se-lhes o coração, disseram: Chamai a Sansão, para que brinque diante de nós. E chamaram a Sansão do cárcere, que brincava diante deles, e fizeram-no estar em pé entre as colunas.'),
('acf','jz',16,26,'Então disse Sansão ao moço que o tinha pela mão: Guia-me para que apalpe as colunas em que se sustém a casa, para que me encoste a elas.'),
('acf','jz',16,27,'Ora estava a casa cheia de homens e mulheres; e também ali estavam todos os príncipes dos filisteus; e sobre o telhado havia uns três mil homens e mulheres, que estavam vendo Sansão brincar.'),
('acf','jz',16,28,'Então Sansão clamou ao SENHOR, e disse: Senhor DEUS, peço-te que te lembres de mim, e fortalece-me agora só esta vez, ó Deus, para que de uma vez me vingue dos filisteus, pelos meus dois olhos.'),
('acf','jz',16,29,'Abraçou-se, pois, Sansão com as duas colunas do meio, em que se sustinha a casa, e arrimou-se sobre elas, com a sua mão direita numa, e com a sua esquerda na outra.'),
('acf','jz',16,30,'E disse Sansão: Morra eu com os filisteus. E inclinou-se com força, e a casa caiu sobre os príncipes e sobre todo o povo que nela havia; e foram mais os mortos que matou na sua morte do que os que matara em sua vida.'),
('acf','jz',16,31,'Então seus irmãos desceram, e toda a casa de seu pai, e tomaram-no, e subiram com ele, e sepultaram-no entre Zorá e Estaol, no sepulcro de Manoá, seu pai. Ele julgou a Israel vinte anos.'),
('acf','jz',17,1,'E havia um homem da montanha de Efraim, cujo nome era Mica.'),
('acf','jz',17,2,'O qual disse à sua mãe: As mil e cem moedas de prata que te foram tiradas, por cuja causa lançaste maldições, e de que também me falaste, eis que esse dinheiro está comigo; eu o tomei. Então lhe disse sua mãe: Bendito do Senhor seja meu filho.'),
('acf','jz',17,3,'Assim restituiu as mil e cem moedas de prata à sua mãe; porém sua mãe disse: Inteiramente tenho dedicado este dinheiro da minha mão ao Senhor, para meu filho fazer uma imagem de escultura e uma de fundição; de sorte que agora to tornarei a dar.'),
('acf','jz',17,4,'Porém ele restituiu aquele dinheiro à sua mãe; e sua mãe tomou duzentas moedas de prata, e as deu ao ourives, o qual fez delas uma imagem de escultura e uma de fundição, que ficaram em casa de Mica.'),
('acf','jz',17,5,'E teve este homem, Mica, uma casa de deuses; e fez um éfode e terafins, e consagrou um de seus filhos, para que lhe fosse por sacerdote.'),
('acf','jz',17,6,'Naqueles dias não havia rei em Israel; cada um fazia o que parecia bem aos seus olhos.'),
('acf','jz',17,7,'E havia um moço de Belém de Judá, da tribo de Judá, que era levita, e peregrinava ali.'),
('acf','jz',17,8,'E este homem partiu da cidade de Belém de Judá para peregrinar onde quer que achasse conveniente. Chegando ele, pois, à montanha de Efraim, até à casa de Mica, seguindo o seu caminho,'),
('acf','jz',17,9,'Disse-lhe Mica: Donde vens? E ele lhe disse: Sou levita de Belém de Judá, e vou peregrinar onde quer que achar conveniente.'),
('acf','jz',17,10,'Então lhe disse Mica: Fica comigo, e sê-me por pai e sacerdote; e cada ano te darei dez moedas de prata, e vestuário, e o sustento. E o levita entrou.'),
('acf','jz',17,11,'E consentiu o levita em ficar com aquele homem; e o moço lhe foi como um de seus filhos.'),
('acf','jz',17,12,'E Mica consagrou o levita, e aquele moço lhe foi por sacerdote; e esteve em casa de Mica.'),
('acf','jz',17,13,'Então disse Mica: Agora sei que o SENHOR me fará bem; porquanto tenho um levita por sacerdote.'),
('acf','jz',18,1,'Naqueles dias não havia rei em Israel; e nos mesmos dias a tribo dos danitas buscava para si herança para habitar; porquanto até àquele dia entre as tribos de Israel não lhe havia caído por sorte sua herança.'),
('acf','jz',18,2,'E enviaram os filhos de Dã, da sua tribo, cinco homens dentre eles, homens valorosos, de Zorá e de Estaol, a espiar e reconhecer a terra, e lhes disseram: Ide, reconhecei a terra. E chegaram à montanha de Efraim, até à casa de Mica, e passaram ali a noite.'),
('acf','jz',18,3,'E quando eles estavam junto da casa de Mica, reconheceram a voz do moço, do levita; e dirigindo-se para lá, lhe disseram: Quem te trouxe aqui? Que fazes aqui? E que é que tens aqui?'),
('acf','jz',18,4,'E ele lhes disse: Assim e assim me tem feito Mica; pois me tem contratado, e eu lhe sirvo de sacerdote.'),
('acf','jz',18,5,'Então lhe disseram: Consulta a Deus, para que possamos saber se prosperará o caminho que seguimos.'),
('acf','jz',18,6,'E disse-lhes o sacerdote: Ide em paz; o caminho que seguis está perante o Senhor.'),
('acf','jz',18,7,'Então foram-se aqueles cinco homens, e chegaram a Laís; e viram que o povo que havia no meio dela estava seguro, conforme ao costume dos sidônios, quieto e confiado; nem havia autoridade alguma do reino que por qualquer coisa envergonhasse a alguém naquela terra; também estavam longe dos sidônios, e não tinham relação com ninguém.'),
('acf','jz',18,8,'Então voltaram a seus irmãos, a Zorá e a Estaol, os quais lhes disseram: Que dizeis vós?'),
('acf','jz',18,9,'E eles disseram: Levantai-vos, e subamos contra eles; porque examinamos a terra, e eis que é muitíssimo boa. E vós estareis aqui tranqüilos? Não sejais preguiçosos em irdes para entrar a possuir esta terra.'),
('acf','jz',18,10,'Quando lá chegardes, vereis um povo confiado, e a terra é larga de extensão; porque Deus vo-la entregou nas mãos; lugar em que não há falta de coisa alguma que há na terra.'),
('acf','jz',18,11,'Então partiram dali, da tribo dos danitas, de Zorá e de Estaol, seiscentos homens munidos de armas de guerra.'),
('acf','jz',18,12,'E subiram, e acamparam-se em Quiriate-Jearim, em Judá; então chamaram a este lugar Maané-Dã, até ao dia de hoje; eis que está por detrás de Quiriate-Jearim.'),
('acf','jz',18,13,'E dali passaram à montanha de Efraim; e chegaram até a casa de Mica.'),
('acf','jz',18,14,'Então responderam os cinco homens, que foram espiar a terra de Laís, e disseram a seus irmãos: Sabeis vós também que naquelas casas há um éfode, e terafins, e uma imagem de escultura e uma de fundição? Vede, pois, agora o que haveis de fazer.'),
('acf','jz',18,15,'Então se dirigiram para lá, e chegaram à casa do moço, o levita, em casa de Mica, e o saudaram.'),
('acf','jz',18,16,'E os seiscentos homens, que eram dos filhos de Dã, munidos com suas armas de guerra, ficaram à entrada da porta.'),
('acf','jz',18,17,'Porém subindo os cinco homens, que foram espiar a terra, entraram ali, e tomaram a imagem de escultura, o éfode, e os terafins, e a imagem de fundição, ficando o sacerdote em pé à entrada da porta, com os seiscentos homens que estavam munidos com as armas de guerra.'),
('acf','jz',18,18,'Entrando eles, pois, em casa de Mica, e tomando a imagem de escultura, e o éfode, e os terafins, e a imagem de fundição, disse-lhes o sacerdote: Que estais fazendo?'),
('acf','jz',18,19,'E eles lhe disseram: Cala-te, põe a mão na boca, e vem conosco, e sê-nos por pai e sacerdote. É melhor ser sacerdote da casa de um só homem, do que ser sacerdote de uma tribo e de uma família em Israel?'),
('acf','jz',18,20,'Então alegrou-se o coração do sacerdote, e tomou o éfode, e os terafins, e a imagem de escultura; e entrou no meio do povo.'),
('acf','jz',18,21,'Assim viraram, e partiram; e os meninos, e o gado, e a bagagem puseram diante de si.'),
('acf','jz',18,22,'E, estando já longe da casa de Mica, os homens que estavam nas casas junto à casa de Mica, reuniram-se, e alcançaram os filhos de Dã.'),
('acf','jz',18,23,'E clamaram após os filhos de Dã, os quais viraram os seus rostos, e disseram a Mica: Que tens, que tanta gente convocaste?'),
('acf','jz',18,24,'Então ele disse: Os meus deuses, que eu fiz, me tomastes, juntamente com o sacerdote, e partistes; que mais me resta agora? Como, pois, me dizeis: Que é que tens?'),
('acf','jz',18,25,'Porém os filhos de Dã lhe disseram: Não nos faças ouvir a tua voz, para que porventura homens de ânimo mau não se lancem sobre vós, e tu percas a tua vida, e a vida dos da tua casa.'),
('acf','jz',18,26,'Assim seguiram o seu caminho os filhos de Dã; e Mica, vendo que eram mais fortes do que ele, virou-se, e voltou à sua casa.'),
('acf','jz',18,27,'Eles, pois, tomaram o que Mica tinha feito, e o sacerdote que tivera, e chegaram a Laís, a um povo quieto e confiado, e os feriram ao fio da espada, e queimaram a cidade a fogo.'),
('acf','jz',18,28,'E ninguém houve que os livrasse, porquanto estavam longe de Sidom, e não tinham relações com ninguém, e a cidade estava no vale que está junto de Bete-Reobe; depois reedificaram a cidade e habitaram nela.'),
('acf','jz',18,29,'E chamaram-lhe Dã, conforme ao nome de Dã, seu pai, que nascera a Israel; era, porém, antes o nome desta cidade Laís.'),
('acf','jz',18,30,'E os filhos de Dã levantaram para si aquela imagem de escultura; e Jônatas, filho de Gérson, o filho de Manassés, ele e seus filhos foram sacerdotes da tribo dos danitas, até ao dia do cativeiro da terra.'),
('acf','jz',18,31,'Assim, pois, estabeleceram para si a imagem de escultura, que fizera Mica, por todos os dias em que a casa de Deus esteve em Siló.'),
('acf','jz',19,1,'Aconteceu também naqueles dias, em que não havia rei em Israel, que houve um homem levita, que, peregrinando aos lados da montanha de Efraim, tomou para si uma concubina, de Belém de Judá.'),
('acf','jz',19,2,'Porém a sua concubina adulterou contra ele, e deixando-o, foi para a casa de seu pai, em Belém de Judá, e esteve ali alguns dias, a saber, quatro meses.'),
('acf','jz',19,3,'E seu marido se levantou, e foi atrás dela, para lhe falar conforme ao seu coração, e para tornar a trazê-la; e o seu moço e um par de jumentos iam com ele; e ela o levou à casa de seu pai, e, vendo-o o pai da moça, alegrou-se ao encontrar-se com ele.'),
('acf','jz',19,4,'E seu sogro, o pai da moça, o deteve, e ficou com ele três dias; e comeram e beberam, e passaram ali a noite.'),
('acf','jz',19,5,'E sucedeu que ao quarto dia pela manhã, de madrugada, ele levantou-se para partir; então o pai da moça disse a seu genro: Fortalece o teu coração com um bocado de pão, e depois partireis.'),
('acf','jz',19,6,'Assentaram-se, pois, e comeram ambos juntos, e beberam; e disse o pai da moça ao homem: Peço-te que ainda esta noite queiras passá-la aqui, e alegre-se o teu coração.'),
('acf','jz',19,7,'Porém o homem levantou-se para partir; mas seu sogro o constrangeu a tornar a passar ali a noite.'),
('acf','jz',19,8,'E, madrugando ao quinto dia pela manhã para partir, disse o pai da moça: Ora, conforta o teu coração. E detiveram-se até já declinar o dia; e ambos juntos comeram.'),
('acf','jz',19,9,'Então o homem levantou-se para partir, ele, e a sua concubina, e o seu moço; e disse-lhe seu sogro, o pai da moça: Eis que já o dia declina e a tarde já vem chegando; peço-te que aqui passes a noite; eis que o dia já vai acabando, passa aqui a noite, e que o teu coração se alegre; e amanhã de madrugada levanta-te a caminhar, e irás para a tua tenda.'),
('acf','jz',19,10,'Porém o homem não quis ali passar a noite, mas levantou-se, e partiu, e chegou até defronte de Jebus (que é Jerusalém), e com ele o par de jumentos albardados, como também a sua concubina.'),
('acf','jz',19,11,'Estando, pois, já perto de Jebus, e tendo-se já declinado muito o dia, disse o moço a seu senhor: Vamos agora, e retiremo-nos a esta cidade dos jebuseus, e passemos ali a noite.'),
('acf','jz',19,12,'Porém disse-lhe seu senhor: Não nos retiraremos a nenhuma cidade estranha, que não seja dos filhos de Israel; mas iremos até Gibeá.'),
('acf','jz',19,13,'Disse mais a seu moço: Vamos, e cheguemos a um daqueles lugares, e passemos a noite em Gibeá ou em Ramá.'),
('acf','jz',19,14,'Passaram, pois, adiante, e caminharam, e o sol se lhes pôs junto a Gibeá, que é cidade de Benjamim.'),
('acf','jz',19,15,'E retiraram-se para lá, para passarem a noite em Gibeá; e, entrando ele, assentou-se na praça da cidade, porque não houve quem os recolhesse em casa para ali passarem a noite.'),
('acf','jz',19,16,'E eis que um velho homem vinha à tarde do seu trabalho do campo; e era este homem da montanha de Efraim, mas peregrinava em Gibeá; eram porém os homens deste lugar filhos de Benjamim.'),
('acf','jz',19,17,'Levantando ele, pois, os olhos, viu a este viajante na praça da cidade, e disse o ancião: Para onde vais, e donde vens?'),
('acf','jz',19,18,'E ele lhe disse: Viajamos de Belém de Judá até aos lados da montanha de Efraim, de onde sou; porquanto fui a Belém de Judá, porém agora vou à casa do Senhor; e ninguém há que me recolha em casa,'),
('acf','jz',19,19,'Todavia temos palha e pasto para os nossos jumentos, e também pão e vinho há para mim, e para a tua serva, e para o moço que vem com os teus servos; de coisa nenhuma há falta.'),
('acf','jz',19,20,'Então disse o ancião: Paz seja contigo; tudo quanto te faltar fique ao meu cargo; tão-somente não passes a noite na praça.'),
('acf','jz',19,21,'E levou-o à sua casa, e deu pasto aos jumentos; e, lavando-se os pés, comeram e beberam.'),
('acf','jz',19,22,'Estando eles alegrando o seu coração, eis que os homens daquela cidade (homens que eram filhos de Belial) cercaram a casa, batendo à porta; e falaram ao ancião, senhor da casa, dizendo: Tira para fora o homem que entrou em tua casa, para que o conheçamos.'),
('acf','jz',19,23,'E o homem, dono da casa, saiu a eles e disse-lhes: Não, irmãos meus, ora não façais semelhante mal; já que este homem entrou em minha casa, não façais tal loucura.'),
('acf','jz',19,24,'Eis que a minha filha virgem e a concubina dele vo-las tirarei fora; humilhai-as a elas, e fazei delas o que parecer bem aos vossos olhos; porém a este homem não façais essa loucura.'),
('acf','jz',19,25,'Porém aqueles homens não o quiseram ouvir; então aquele homem pegou da sua concubina, e lha tirou para fora; e eles a conheceram e abusaram dela toda a noite até pela manhã, e, subindo a alva, a deixaram.'),
('acf','jz',19,26,'E ao romper da manhã veio a mulher, e caiu à porta da casa daquele homem, onde estava seu senhor, e ficou ali até que se fez claro.'),
('acf','jz',19,27,'E, levantando-se seu senhor pela manhã, e abrindo as portas da casa, e saindo a seguir o seu caminho, eis que a mulher, sua concubina, jazia à porta da casa, com as mãos sobre o limiar.'),
('acf','jz',19,28,'E ele lhe disse: Levanta-te, e vamo-nos, porém ela não respondeu; então, levantando-se o homem a pôs sobre o jumento, e foi para o seu lugar.'),
('acf','jz',19,29,'Chegando, pois, à sua casa, tomou um cutelo, e pegou na sua concubina, e a despedaçou com os seus ossos em doze partes; e enviou-as por todos os termos de Israel.'),
('acf','jz',19,30,'E sucedeu que cada um que via aquilo dizia: Nunca tal se fez, nem se viu desde o dia em que os filhos de Israel subiram da terra do Egito, até ao dia de hoje; ponderai isto, considerai, e falai.'),
('acf','jz',20,1,'Então todos os filhos de Israel saíram, e a congregação se ajuntou, perante o SENHOR em Mizpá, como se fora um só homem, desde Dã até Berseba, como também a terra de Gileade.'),
('acf','jz',20,2,'E os principais de todo o povo, de todas as tribos de Israel, se apresentaram na congregação do povo de Deus; quatrocentos mil homens de pé que tiravam a espada'),
('acf','jz',20,3,'(Ouviram, pois, os filhos de Benjamim que os filhos de Israel haviam subido a Mizpá). E disseram os filhos de Israel: Falai, como sucedeu esta maldade?'),
('acf','jz',20,4,'Então respondeu o homem levita, marido da mulher que fora morta, e disse: Cheguei com a minha concubina a Gibeá, cidade de Benjamim, para passar a noite.'),
('acf','jz',20,5,'E os cidadãos de Gibeá se levantaram contra mim, e cercaram a casa de noite; intentaram matar-me, e violaram a minha concubina, de maneira que morreu.'),
('acf','jz',20,6,'Então peguei na minha concubina, e fi-la em pedaços, e a enviei por toda a terra da herança de Israel; porquanto fizeram tal malefício e loucura em Israel.'),
('acf','jz',20,7,'Eis que todos sois filhos de Israel; dai aqui a vossa palavra e conselho.'),
('acf','jz',20,8,'Então todo o povo se levantou como um só homem, dizendo: Nenhum de nós irá à sua tenda nem nenhum de nós voltará à sua casa.'),
('acf','jz',20,9,'Porém isto é o que faremos a Gibeá: procederemos contra ela por sorte.'),
('acf','jz',20,10,'E de todas as tribos de Israel, tomaremos dez homens de cada cem, e cem de cada mil, e mil de cada dez mil, para providenciarem mantimento para o povo; para que, vindo ele a Gibeá de Benjamim, lhe façam conforme a toda a loucura que tem feito em Israel.'),
('acf','jz',20,11,'Assim ajuntaram-se contra esta cidade todos os homens de Israel, unidos como um só homem.'),
('acf','jz',20,12,'E as tribos de Israel enviaram homens por toda a tribo de Benjamim, dizendo: Que maldade é esta que se fez entre vós?'),
('acf','jz',20,13,'Dai-nos, pois, agora aqueles homens, filhos de Belial, que estão em Gibeá, para que os matemos, e tiremos de Israel o mal. Porém os filhos de Benjamim não quiseram ouvir a voz de seus irmãos, os filhos de Israel.'),
('acf','jz',20,14,'Antes os filhos de Benjamim se ajuntaram das cidades em Gibeá, para saírem a pelejar contra os filhos de Israel.'),
('acf','jz',20,15,'E contaram-se naquele dia os filhos de Benjamim, das cidades, vinte e seis mil homens que tiravam a espada, afora os moradores de Gibeá, de que se contaram setecentos homens escolhidos.'),
('acf','jz',20,16,'Entre todo este povo havia setecentos homens escolhidos, canhotos, os quais atiravam com a funda uma pedra em um cabelo, e não erravam.'),
('acf','jz',20,17,'E contaram-se dos homens de Israel, afora os de Benjamim, quatrocentos mil homens que tiravam da espada, e todos eles homens de guerra.'),
('acf','jz',20,18,'E levantaram-se os filhos de Israel, e subiram a Betel; e consultaram a Deus, dizendo: Quem dentre nós subirá primeiro a pelejar contra Benjamim? E disse o Senhor: Judá subirá primeiro.'),
('acf','jz',20,19,'Levantaram-se, pois, os filhos de Israel pela manhã, e acamparam-se contra Gibeá.'),
('acf','jz',20,20,'E os homens de Israel saíram à peleja contra Benjamim; e os homens de Israel ordenaram a batalha contra eles, ao pé de Gibeá.'),
('acf','jz',20,21,'Então os filhos de Benjamim saíram de Gibeá, e derrubaram por terra, naquele dia, vinte e dois mil homens de Israel.'),
('acf','jz',20,22,'Porém esforçou-se o povo, isto é, os homens de Israel, e tornaram a ordenar a peleja no lugar onde no primeiro dia a tinham ordenado.'),
('acf','jz',20,23,'E subiram os filhos de Israel, e choraram perante o Senhor até à tarde, e perguntaram ao Senhor, dizendo: Tornar-me-ei a chegar à peleja contra os filhos de Benjamim, meu irmão? E disse o Senhor: Subi contra ele.'),
('acf','jz',20,24,'Chegaram-se, pois, os filhos de Israel aos filhos de Benjamim, no dia seguinte.'),
('acf','jz',20,25,'Também os de Benjamim no dia seguinte lhes saíram ao encontro fora de Gibeá, e derrubaram ainda por terra mais dezoito mil homens, todos dos que tiravam a espada.'),
('acf','jz',20,26,'Então todos os filhos de Israel, e todo o povo, subiram, e vieram a Betel e choraram, e estiveram ali perante o Senhor, e jejuaram aquele dia até à tarde; e ofereceram holocaustos e ofertas pacíficas perante o Senhor.'),
('acf','jz',20,27,'E os filhos de Israel perguntaram ao Senhor (porquanto a arca da aliança de Deus estava ali naqueles dias;'),
('acf','jz',20,28,'E Finéias, filho de Eleazar, filho de Arão, estava perante ele naqueles dias), dizendo: Tornarei ainda a pelejar contra os filhos de Benjamim, meu irmão, ou pararei? E disse o Senhor: Subi, que amanhã eu to entregarei na mão.'),
('acf','jz',20,29,'Então Israel pôs emboscadas em redor de Gibeá.'),
('acf','jz',20,30,'E subiram os filhos de Israel ao terceiro dia contra os filhos de Benjamim, e ordenaram a peleja junto a Gibeá, como das outras vezes.'),
('acf','jz',20,31,'Então os filhos de Benjamim saíram ao encontro do povo, e desviaram-se da cidade; e começaram a ferir alguns do povo, atravessando-os, como das outras vezes, pelos caminhos (um dos quais sobe para Betel, e o outro para Gibeá pelo campo), uns trinta dos homens de Israel.'),
('acf','jz',20,32,'Então os filhos de Benjamim disseram: Estão derrotados diante de nós como dantes. Porém os filhos de Israel disseram: Fujamos, e desviemo-los da cidade para os caminhos.'),
('acf','jz',20,33,'Então todos os homens de Israel se levantaram do seu lugar, e ordenaram a peleja em Baal-Tamar; e a emboscada de Israel saiu do seu lugar, da caverna de Gibeá.'),
('acf','jz',20,34,'E dez mil homens escolhidos de todo o Israel vieram contra Gibeá, e a peleja se agravou; porém eles não sabiam o mal que lhes tocaria.'),
('acf','jz',20,35,'Então feriu o Senhor a Benjamim diante de Israel; e destruíram os filhos de Israel, naquele dia, vinte e cinco mil e cem homens de Benjamim, todos dos que tiravam a espada.'),
('acf','jz',20,36,'E viram os filhos de Benjamim que estavam feridos; porque os homens de Israel deram lugar aos benjamitas, porquanto estavam confiados na emboscada que haviam posto contra Gibeá.'),
('acf','jz',20,37,'E a emboscada se apressou, e acometeu a Gibeá; e a emboscada arremeteu contra ela, e feriu ao fio da espada toda a cidade.'),
('acf','jz',20,38,'E os homens de Israel tinham um sinal determinado com a emboscada, que era fazer levantar da cidade uma grande nuvem de fumaça.'),
('acf','jz',20,39,'Viraram-se, pois, os homens de Israel na peleja; e já Benjamim começava a ferir, dos homens de Israel, quase trinta homens, pois diziam: Já infalivelmente estão derrotados diante de nós, como na peleja passada.'),
('acf','jz',20,40,'Então a nuvem de fumaça começou a se levantar da cidade, como uma coluna; e, virando-se Benjamim a olhar para trás de si, eis que a fumaça da cidade subia ao céu.'),
('acf','jz',20,41,'E os homens de Israel viraram os rostos, e os homens de Benjamim pasmaram; porque viram que o mal lhes tocaria.'),
('acf','jz',20,42,'E viraram as costas diante dos homens de Israel, para o caminho do deserto; porém a peleja os apertou; e os que saíam das cidades os destruíram no meio deles.'),
('acf','jz',20,43,'E cercaram aos de Benjamim, e os perseguiram, e à vontade os pisaram, até diante de Gibeá, para o nascente do sol.'),
('acf','jz',20,44,'E caíram de Benjamim dezoito mil homens, todos estes sendo homens valentes.'),
('acf','jz',20,45,'Então viraram as costas, e fugiram para o deserto, à penha de Rimom; colheram ainda deles pelos caminhos uns cinco mil homens; e de perto os seguiram até Gidom, e feriram deles dois mil homens.'),
('acf','jz',20,46,'E, todos os que caíram de Benjamim, naquele dia, foram vinte e cinco mil homens que tiravam a espada, todos eles homens valentes.'),
('acf','jz',20,47,'Porém seiscentos homens viraram as costas, e fugiram para o deserto, à penha de Rimom; e ficaram na penha de Rimom quatro meses.'),
('acf','jz',20,48,'E os homens de Israel voltaram para os filhos de Benjamim, e os feriram ao fio da espada, desde os homens da cidade até aos animais, até a tudo quanto se achava, como também a todas as cidades, quantas acharam, puseram fogo.'),
('acf','jz',21,1,'Ora, tinham jurado os homens de Israel em Mizpá, dizendo: Nenhum de nós dará sua filha por mulher aos benjamitas.'),
('acf','jz',21,2,'Veio, pois, o povo a Betel, e ali ficou até à tarde diante de Deus; e todos levantaram a sua voz, e prantearam com grande pranto,'),
('acf','jz',21,3,'E disseram: Ah! Senhor Deus de Israel, por que sucedeu isto, que hoje falte uma tribo em Israel?'),
('acf','jz',21,4,'E sucedeu que, no dia seguinte, o povo, pela manhã se levantou, e edificou ali um altar; e ofereceu holocaustos e ofertas pacíficas.'),
('acf','jz',21,5,'E disseram os filhos de Israel: Quem de todas as tribos de Israel não subiu à assembléia do Senhor? Porque se tinha feito um grande juramento acerca dos que não fossem ao Senhor em Mizpá, dizendo: Morrerá certamente.'),
('acf','jz',21,6,'E arrependeram-se os filhos de Israel acerca de Benjamim, seu irmão, e disseram: Cortada é hoje de Israel uma tribo.'),
('acf','jz',21,7,'Como havemos de conseguir mulheres para os que restaram deles, pois nós temos jurado pelo Senhor que nenhuma de nossas filhas lhes daríamos por mulher?'),
('acf','jz',21,8,'E disseram: Há algumas das tribos de Israel que não subiram ao Senhor a Mizpá? E eis que ninguém de Jabes-Gileade viera ao arraial, à assembléia.'),
('acf','jz',21,9,'Porquanto, quando se contou o povo, eis que nenhum dos moradores de Jabes-Gileade se achou ali.'),
('acf','jz',21,10,'Então a assembléia enviou para lá doze mil homens dos mais valentes, e lhes ordenou, dizendo: Ide, e ao fio da espada feri aos moradores de Jabes-Gileade, e às mulheres e aos meninos.'),
('acf','jz',21,11,'Porém isto é o que haveis de fazer: A todo o homem e a toda a mulher que se houver deitado com um homem totalmente destruireis.'),
('acf','jz',21,12,'E acharam entre os moradores de Jabes-Gileade quatrocentas moças virgens, que não tinham conhecido homem; e as trouxeram ao arraial, a Siló, que está na terra de Canaã.'),
('acf','jz',21,13,'Então toda a assembléia enviou, e falou aos filhos de Benjamim, que estavam na penha de Rimom, e lhes proclamou a paz.'),
('acf','jz',21,14,'E ao mesmo tempo voltaram os benjamitas; e deram-lhes as mulheres que haviam guardado com vida, das mulheres de Jabes-Gileade; porém estas ainda não lhes bastaram.'),
('acf','jz',21,15,'Então o povo se arrependeu por causa de Benjamim; porquanto o Senhor tinha feito brecha nas tribos de Israel.'),
('acf','jz',21,16,'E disseram os anciãos da assembléia: Que faremos acerca de mulheres para os que restaram, pois foram destruídas as mulheres de Benjamim?'),
('acf','jz',21,17,'Disseram mais: Tenha Benjamim uma herança nos que restaram, e não seja destruída nenhuma tribo de Israel.'),
('acf','jz',21,18,'Porém nós não lhes poderemos dar mulheres de nossas filhas, porque os filhos de Israel juraram, dizendo: Maldito aquele que der mulher aos benjamitas.'),
('acf','jz',21,19,'Então disseram: Eis que de ano em ano há solenidade do Senhor em Siló, que se celebra para o norte de Betel do lado do nascente do sol, pelo caminho alto que sobe de Betel a Siquém, e para o sul de Lebona.'),
('acf','jz',21,20,'E mandaram aos filhos de Benjamim, dizendo: Ide, e emboscai-vos nas vinhas.'),
('acf','jz',21,21,'E olhai, e eis aí as filhas de Siló a dançar em rodas, saí vós das vinhas, e arrebatai cada um sua mulher das filhas de Siló, e ide-vos à terra de Benjamim.'),
('acf','jz',21,22,'E será que, quando seus pais ou seus irmãos vierem a litigar conosco, nós lhes diremos: Por amor de nós, tende compaixão deles, pois nesta guerra não tomamos mulheres para cada um deles; porque não lhas destes vós, para que agora ficásseis culpados.'),
('acf','jz',21,23,'E os filhos de Benjamim o fizeram assim, e levaram mulheres conforme ao número deles, das que arrebataram das rodas que dançavam; e foram-se, e voltaram à sua herança, e reedificaram as cidades, e habitaram nelas.'),
('acf','jz',21,24,'Também os filhos de Israel partiram dali, cada um para a sua tribo e para a sua família; e saíram dali, cada um para a sua herança.'),
('acf','jz',21,25,'Naqueles dias não havia rei em Israel; porém cada um fazia o que parecia reto aos seus olhos.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','rt',1,1,'E sucedeu que, nos dias em que os juízes julgavam, houve uma fome na terra; por isso um homem de Belém de Judá saiu a peregrinar nos campos de Moabe, ele e sua mulher, e seus dois filhos;'),
('acf','rt',1,2,'E era o nome deste homem Elimeleque, e o de sua mulher Noemi, e os de seus dois filhos Malom e Quiliom, efrateus, de Belém de Judá; e chegaram aos campos de Moabe, e ficaram ali.'),
('acf','rt',1,3,'E morreu Elimeleque, marido de Noemi; e ficou ela com os seus dois filhos,'),
('acf','rt',1,4,'Os quais tomaram para si mulheres moabitas; e era o nome de uma Orfa, e o da outra Rute; e ficaram ali quase dez anos.'),
('acf','rt',1,5,'E morreram também ambos, Malom e Quiliom, ficando assim a mulher desamparada dos seus dois filhos e de seu marido.'),
('acf','rt',1,6,'Então se levantou ela com as suas noras, e voltou dos campos de Moabe, porquanto na terra de Moabe ouviu que o Senhor tinha visitado o seu povo, dando-lhe pão.'),
('acf','rt',1,7,'Por isso saiu do lugar onde estivera, e as suas noras com ela. E, indo elas caminhando, para voltarem para a terra de Judá,'),
('acf','rt',1,8,'Disse Noemi às suas noras: Ide, voltai cada uma à casa de sua mãe; e o Senhor use convosco de benevolência, como vós usastes com os falecidos e comigo.'),
('acf','rt',1,9,'O Senhor vos dê que acheis descanso cada uma em casa de seu marido. E, beijando-as ela, levantaram a sua voz e choraram.'),
('acf','rt',1,10,'E disseram-lhe: Certamente voltaremos contigo ao teu povo.'),
('acf','rt',1,11,'Porém Noemi disse: Voltai, minhas filhas. Por que iríeis comigo? Tenho eu ainda no meu ventre mais filhos, para que vos sejam por maridos?'),
('acf','rt',1,12,'Voltai, filhas minhas, ide-vos embora, que já mui velha sou para ter marido; ainda quando eu dissesse: Tenho esperança, ou ainda que esta noite tivesse marido e ainda tivesse filhos,'),
('acf','rt',1,13,'Esperá-los-íeis até que viessem a ser grandes? Deter-vos-íeis por eles, sem tomardes marido? Não, filhas minhas, que mais amargo me é a mim do que a vós mesmas; porquanto a mão do Senhor se descarregou contra mim.'),
('acf','rt',1,14,'Então levantaram a sua voz, e tornaram a chorar; e Orfa beijou a sua sogra, porém Rute se apegou a ela.'),
('acf','rt',1,15,'Por isso disse Noemi: Eis que voltou tua cunhada ao seu povo e aos seus deuses; volta tu também após tua cunhada.'),
('acf','rt',1,16,'Disse, porém, Rute: Não me instes para que te abandone, e deixe de seguir-te; porque aonde quer que tu fores irei eu, e onde quer que pousares, ali pousarei eu; o teu povo é o meu povo, o teu Deus é o meu Deus;'),
('acf','rt',1,17,'Onde quer que morreres morrerei eu, e ali serei sepultada. Faça-me assim o Senhor, e outro tanto, se outra coisa que não seja a morte me separar de ti.'),
('acf','rt',1,18,'Vendo Noemi, que de todo estava resolvida a ir com ela, deixou de lhe falar.'),
('acf','rt',1,19,'Assim, pois, foram-se ambas, até que chegaram a Belém; e sucedeu que, entrando elas em Belém, toda a cidade se comoveu por causa delas, e diziam: Não é esta Noemi?'),
('acf','rt',1,20,'Porém ela lhes dizia: Não me chameis Noemi; chamai-me Mara; porque grande amargura me tem dado o Todo-Poderoso.'),
('acf','rt',1,21,'Cheia parti, porém vazia o Senhor me fez tornar; por que pois me chamareis Noemi? O Senhor testifica contra mim, e o Todo-Poderoso me tem feito mal.'),
('acf','rt',1,22,'Assim Noemi voltou, e com ela Rute a moabita, sua nora, que veio dos campos de Moabe; e chegaram a Belém no princípio da colheita das cevadas.'),
('acf','rt',2,1,'E tinha Noemi um parente de seu marido, homem valente e poderoso, da família de Elimeleque; e era o seu nome Boaz.'),
('acf','rt',2,2,'E Rute, a moabita, disse a Noemi: Deixa-me ir ao campo, e apanharei espigas atrás daquele em cujos olhos eu achar graça. E ela disse: Vai, minha filha.'),
('acf','rt',2,3,'Foi, pois, e chegou, e apanhava espigas no campo após os segadores; e caiu-lhe em sorte uma parte do campo de Boaz, que era da família de Elimeleque.'),
('acf','rt',2,4,'E eis que Boaz veio de Belém, e disse aos segadores: O Senhor seja convosco. E disseram-lhe eles: O Senhor te abençoe.'),
('acf','rt',2,5,'Depois disse Boaz a seu moço, que estava posto sobre os segadores: De quem é esta moça?'),
('acf','rt',2,6,'E respondeu o moço, que estava posto sobre os segadores, e disse: Esta é a moça moabita que voltou com Noemi dos campos de Moabe.'),
('acf','rt',2,7,'Disse-me ela: Deixa-me colher espigas, e ajuntá-las entre as gavelas após os segadores. Assim ela veio, e desde pela manhã está aqui até agora, a não ser um pouco que esteve sentada em casa.'),
('acf','rt',2,8,'Então disse Boaz a Rute: Ouve, filha minha; não vás colher em outro campo, nem tampouco passes daqui; porém aqui ficarás com as minhas moças.'),
('acf','rt',2,9,'Os teus olhos estarão atentos no campo que segarem, e irás após elas; não dei ordem aos moços, que não te molestem? Tendo tu sede, vai aos vasos, e bebe do que os moços tirarem.'),
('acf','rt',2,10,'Então ela caiu sobre o seu rosto, e se inclinou à terra; e disse-lhe: Por que achei graça em teus olhos, para que faças caso de mim, sendo eu uma estrangeira?'),
('acf','rt',2,11,'E respondeu Boaz, e disse-lhe: Bem se me contou quanto fizeste à tua sogra, depois da morte de teu marido; e deixaste a teu pai e a tua mãe, e a terra onde nasceste, e vieste para um povo que antes não conheceste.'),
('acf','rt',2,12,'O Senhor retribua o teu feito; e te seja concedido pleno galardão da parte do Senhor Deus de Israel, sob cujas asas te vieste abrigar.'),
('acf','rt',2,13,'E disse ela: Ache eu graça em teus olhos, senhor meu, pois me consolaste, e falaste ao coração da tua serva, não sendo eu ainda como uma das tuas criadas.'),
('acf','rt',2,14,'E, sendo já hora de comer, disse-lhe Boaz: Achega-te aqui, e come do pão, e molha o teu bocado no vinagre. E ela se assentou ao lado dos segadores, e ele lhe deu do trigo tostado, e comeu, e se fartou, e ainda lhe sobejou.'),
('acf','rt',2,15,'E, levantando-se ela a colher, Boaz deu ordem aos seus moços, dizendo: Até entre as gavelas deixai-a colher, e não a censureis.'),
('acf','rt',2,16,'E deixai cair alguns punhados, e deixai-os ficar, para que os colha, e não a repreendais.'),
('acf','rt',2,17,'E esteve ela apanhando naquele campo até à tarde; e debulhou o que apanhou, e foi quase um efa de cevada.'),
('acf','rt',2,18,'E tomou-o, e veio à cidade; e viu sua sogra o que tinha apanhado; também tirou, e deu-lhe o que sobejara depois de fartar-se.'),
('acf','rt',2,19,'Então disse-lhe sua sogra: Onde colheste hoje, e onde trabalhaste? Bendito seja aquele que te reconheceu. E relatou à sua sogra com quem tinha trabalhado, e disse: O nome do homem com quem hoje trabalhei é Boaz.'),
('acf','rt',2,20,'Então Noemi disse à sua nora: Bendito seja ele do Senhor, que ainda não tem deixado a sua beneficência nem para com os vivos nem para com os mortos. Disse-lhe mais Noemi: Este homem é nosso parente chegado, e um dentre os nossos remidores.'),
('acf','rt',2,21,'E disse Rute, a moabita: Também ainda me disse: Com os moços que tenho te ajuntarás, até que acabem toda a sega que tenho.'),
('acf','rt',2,22,'E disse Noemi a sua nora: Melhor é, filha minha, que saias com as suas moças, para que noutro campo não te encontrem.'),
('acf','rt',2,23,'Assim, ajuntou-se com as moças de Boaz, para colher até que a sega das cevadas e dos trigos se acabou; e ficou com a sua sogra.'),
('acf','rt',3,1,'E disse-lhe Noemi, sua sogra: Minha filha, não hei de buscar descanso, para que fiques bem?'),
('acf','rt',3,2,'Ora, pois, não é Boaz, com cujas moças estiveste, de nossa parentela? Eis que esta noite padejará a cevada na eira.'),
('acf','rt',3,3,'Lava-te, pois, e unge-te, e veste os teus vestidos, e desce à eira; porém não te dês a conhecer ao homem, até que tenha acabado de comer e beber.'),
('acf','rt',3,4,'E há de ser que, quando ele se deitar, notarás o lugar em que se deitar; então entrarás, e descobrir-lhe-ás os pés, e te deitarás, e ele te fará saber o que deves fazer.'),
('acf','rt',3,5,'E ela lhe disse: Tudo quanto me disseres, farei.'),
('acf','rt',3,6,'Então foi para a eira, e fez conforme a tudo quanto sua sogra lhe tinha ordenado.'),
('acf','rt',3,7,'Havendo, pois, Boaz comido e bebido, e estando já o seu coração alegre, veio deitar-se ao pé de um monte de grãos; então veio ela de mansinho, e lhe descobriu os pés, e se deitou.'),
('acf','rt',3,8,'E sucedeu que, pela meia-noite, o homem estremeceu, e se voltou; e eis que uma mulher jazia a seus pés.'),
('acf','rt',3,9,'E disse ele: Quem és tu? E ela disse: Sou Rute, tua serva; estende pois tua capa sobre a tua serva, porque tu és o remidor.'),
('acf','rt',3,10,'E disse ele: Bendita sejas tu do Senhor, minha filha; melhor fizeste esta tua última benevolência do que a primeira, pois após nenhum dos jovens foste, quer pobre quer rico.'),
('acf','rt',3,11,'Agora, pois, minha filha, não temas; tudo quanto disseste te farei, pois toda a cidade do meu povo sabe que és mulher virtuosa.'),
('acf','rt',3,12,'Porém agora é verdade que eu sou remidor, mas ainda outro remidor há mais chegado do que eu.'),
('acf','rt',3,13,'Fica-te aqui esta noite, e será que, pela manhã, se ele te redimir, bem está, que te redima; porém, se não quiser te redimir, vive o Senhor, que eu te redimirei. Deita-te aqui até amanhã.'),
('acf','rt',3,14,'Ficou-se, pois, deitada a seus pés até pela manhã, e levantou-se antes que pudesse um conhecer o outro, porquanto ele disse: Não se saiba que alguma mulher veio à eira.'),
('acf','rt',3,15,'Disse mais: Dá-me a capa que tens sobre ti, e segura-a. E ela a segurou; e ele mediu seis medidas de cevada, e lhas pôs em cima; então foi para a cidade.'),
('acf','rt',3,16,'E foi à sua sogra, que lhe disse: Como foi, minha filha? E ela lhe contou tudo quanto aquele homem lhe fizera.'),
('acf','rt',3,17,'Disse mais: Estas seis medidas de cevada me deu, porque me disse: Não vás vazia à tua sogra.'),
('acf','rt',3,18,'Então disse ela: Espera, minha filha, até que saibas como irá o caso, porque aquele homem não descansará até que conclua hoje este negócio.'),
('acf','rt',4,1,'E Boaz subiu à porta, e assentou-se ali; e eis que o remidor de que Boaz tinha falado ia passando, e disse-lhe: Ó fulano, vem cá, assenta-te aqui. E desviou-se para ali, e assentou-se.'),
('acf','rt',4,2,'Então tomou dez homens dos anciãos da cidade, e disse: Assentai-vos aqui. E assentaram-se.'),
('acf','rt',4,3,'Então disse ao remidor: Aquela parte da terra que foi de Elimeleque, nosso irmão, Noemi, que tornou da terra dos moabitas, está vendendo.'),
('acf','rt',4,4,'E eu resolvi informar-te disso e dizer-te: Compra-a diante dos habitantes, e diante dos anciãos do meu povo; se a hás de redimir, redime-a, e se não a houveres de redimir, declara-mo, para que o saiba, pois outro não há senão tu que a redima, e eu depois de ti. Então disse ele: Eu a redimirei.'),
('acf','rt',4,5,'Disse porém Boaz: No dia em que comprares a terra da mão de Noemi, também a comprarás da mão de Rute, a moabita, mulher do falecido, para suscitar o nome do falecido sobre a sua herança.'),
('acf','rt',4,6,'Então disse o remidor: Para mim não a poderei redimir, para que não prejudique a minha herança; toma para ti o meu direito de remissão, porque eu não a poderei redimir.'),
('acf','rt',4,7,'Havia, pois, já de muito tempo este costume em Israel, quanto a remissão e permuta, para confirmar todo o negócio; o homem descalçava o sapato e o dava ao seu próximo; e isto era por testemunho em Israel.'),
('acf','rt',4,8,'Disse, pois, o remidor a Boaz: Toma-a para ti. E descalçou o sapato.'),
('acf','rt',4,9,'Então Boaz disse aos anciãos e a todo o povo: Sois hoje testemunhas de que tomei tudo quanto foi de Elimeleque, e de Quiliom, e de Malom, da mão de Noemi,'),
('acf','rt',4,10,'E de que também tomo por mulher a Rute, a moabita, que foi mulher de Malom, para suscitar o nome do falecido sobre a sua herança, para que o nome do falecido não seja desarraigado dentre seus irmãos e da porta do seu lugar; disto sois hoje testemunhas.'),
('acf','rt',4,11,'E todo o povo que estava na porta, e os anciãos, disseram: Somos testemunhas; o Senhor faça a esta mulher, que entra na tua casa, como a Raquel e como a Lia, que ambas edificaram a casa de Israel; e porta-te valorosamente em Efrata, e faze-te nome afamado em Belém.'),
('acf','rt',4,12,'E seja a tua casa como a casa de Perez (que Tamar deu à luz a Judá), pela descendência que o Senhor te der desta moça.'),
('acf','rt',4,13,'Assim tomou Boaz a Rute, e ela lhe foi por mulher; e ele a possuiu, e o Senhor lhe fez conceber, e deu à luz um filho.'),
('acf','rt',4,14,'Então as mulheres disseram a Noemi: Bendito seja o Senhor, que não deixou hoje de te dar remidor, e seja o seu nome afamado em Israel.'),
('acf','rt',4,15,'Ele te será por restaurador da alma, e nutrirá a tua velhice, pois tua nora, que te ama, o deu à luz, e ela te é melhor do que sete filhos.'),
('acf','rt',4,16,'E Noemi tomou o filho, e o pôs no seu colo, e foi sua ama.'),
('acf','rt',4,17,'E as vizinhas lhe deram um nome, dizendo: A Noemi nasceu um filho. E deram-lhe o nome de Obede. Este é o pai de Jessé, pai de Davi.'),
('acf','rt',4,18,'Estas são, pois, as gerações de Perez: Perez gerou a Hezrom,'),
('acf','rt',4,19,'E Hezrom gerou a Rão, e Rão gerou a Aminadabe,'),
('acf','rt',4,20,'E Aminadabe gerou a Naassom, e Naassom gerou a Salmom,'),
('acf','rt',4,21,'E Salmom gerou a Boaz, e Boaz gerou a Obede,'),
('acf','rt',4,22,'E Obede gerou a Jessé, e Jessé gerou a Davi.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','1sm',1,1,'Houve um homem de Ramataim-Zofim, da montanha de Efraim, cujo nome era Elcana, filho de Jeroão, filho de Eliú, filho de Toú, filho de Zufe, efrateu.'),
('acf','1sm',1,2,'E este tinha duas mulheres: o nome de uma era Ana, e o da outra Penina. E Penina tinha filhos, porém Ana não os tinha.'),
('acf','1sm',1,3,'Subia, pois, este homem, da sua cidade, de ano em ano, a adorar e a sacrificar ao Senhor dos Exércitos em Siló; e estavam ali os sacerdotes do Senhor, Hofni e Finéias, os dois filhos de Eli.'),
('acf','1sm',1,4,'E sucedeu que no dia em que Elcana sacrificava, dava ele porções a Penina, sua mulher, e a todos os seus filhos, e a todas as suas filhas.'),
('acf','1sm',1,5,'Porém a Ana dava uma parte excelente; porque amava a Ana, embora o Senhor lhe tivesse cerrado a madre.'),
('acf','1sm',1,6,'E a sua rival excessivamente a provocava, para a irritar; porque o Senhor lhe tinha cerrado a madre.'),
('acf','1sm',1,7,'E assim fazia ele de ano em ano. Sempre que Ana subia à casa do Senhor, a outra a irritava; por isso chorava, e não comia.'),
('acf','1sm',1,8,'Então Elcana, seu marido, lhe disse: Ana, por que choras? E por que não comes? E por que está mal o teu coração? Não te sou eu melhor do que dez filhos?'),
('acf','1sm',1,9,'Então Ana se levantou, depois que comeram e beberam em Siló; e Eli, sacerdote, estava assentado numa cadeira, junto a um pilar do templo do Senhor.'),
('acf','1sm',1,10,'Ela, pois, com amargura de alma, orou ao Senhor, e chorou abundantemente.'),
('acf','1sm',1,11,'E fez um voto, dizendo: Senhor dos Exércitos! Se benignamente atentares para a aflição da tua serva, e de mim te lembrares, e da tua serva não te esqueceres, mas à tua serva deres um filho homem, ao Senhor o darei todos os dias da sua vida, e sobre a sua cabeça não passará navalha.'),
('acf','1sm',1,12,'E sucedeu que, perseverando ela em orar perante o Senhor, Eli observou a sua boca.'),
('acf','1sm',1,13,'Porquanto Ana no seu coração falava; só se moviam os seus lábios, porém não se ouvia a sua voz; pelo que Eli a teve por embriagada.'),
('acf','1sm',1,14,'E disse-lhe Eli: Até quando estarás tu embriagada? Aparta de ti o teu vinho.'),
('acf','1sm',1,15,'Porém Ana respondeu: Não, senhor meu, eu sou uma mulher atribulada de espírito; nem vinho nem bebida forte tenho bebido; porém tenho derramado a minha alma perante o SENHOR.'),
('acf','1sm',1,16,'Não tenhas, pois, a tua serva por filha de Belial; porque da multidão dos meus cuidados e do meu desgosto tenho falado até agora.'),
('acf','1sm',1,17,'Então respondeu Eli: Vai em paz; e o Deus de Israel te conceda a petição que lhe fizeste.'),
('acf','1sm',1,18,'E disse ela: Ache a tua serva graça aos teus olhos. Assim a mulher foi o seu caminho, e comeu, e o seu semblante já não era triste.'),
('acf','1sm',1,19,'E levantaram-se de madrugada, e adoraram perante o Senhor, e voltaram, e chegaram à sua casa, em Ramá, e Elcana conheceu a Ana sua mulher, e o Senhor se lembrou dela.'),
('acf','1sm',1,20,'E sucedeu que, passado algum tempo, Ana concebeu, e deu à luz um filho, ao qual chamou Samuel; porque, dizia ela, o tenho pedido ao Senhor.'),
('acf','1sm',1,21,'E subiu aquele homem Elcana com toda a sua casa, a oferecer ao Senhor o sacrifício anual e a cumprir o seu voto.'),
('acf','1sm',1,22,'Porém Ana não subiu; mas disse a seu marido: Quando o menino for desmamado, então o levarei, para que apareça perante o Senhor, e lá fique para sempre.'),
('acf','1sm',1,23,'E Elcana, seu marido, lhe disse: Faze o que bem te parecer aos teus olhos; fica até que o desmames; então somente confirme o Senhor a sua palavra. Assim ficou a mulher, e deu leite a seu filho, até que o desmamou.'),
('acf','1sm',1,24,'E, havendo-o desmamado, tomou-o consigo, com três bezerros, e um efa de farinha, e um odre de vinho, e levou-o à casa do Senhor, em Siló, e era o menino ainda muito criança.'),
('acf','1sm',1,25,'E degolaram um bezerro, e trouxeram o menino a Eli.'),
('acf','1sm',1,26,'E disse ela: Ah, meu senhor, viva a tua alma, meu senhor; eu sou aquela mulher que aqui esteve contigo, para orar ao SENHOR.'),
('acf','1sm',1,27,'Por este menino orava eu; e o Senhor atendeu à minha petição, que eu lhe tinha feito.'),
('acf','1sm',1,28,'Por isso também ao Senhor eu o entreguei, por todos os dias que viver, pois ao Senhor foi pedido. E adorou ali ao Senhor.'),
('acf','1sm',2,1,'Então orou Ana, e disse: O meu coração exulta ao SENHOR, o meu poder está exaltado no SENHOR; a minha boca se dilatou sobre os meus inimigos, porquanto me alegro na tua salvação.'),
('acf','1sm',2,2,'Não há santo como o Senhor; porque não há outro fora de ti; e rocha nenhuma há como o nosso Deus.'),
('acf','1sm',2,3,'Não multipliqueis palavras de altivez, nem saiam coisas arrogantes da vossa boca; porque o Senhor é o Deus de conhecimento, e por ele são as obras pesadas na balança.'),
('acf','1sm',2,4,'O arco dos fortes foi quebrado, e os que tropeçavam foram cingidos de força.'),
('acf','1sm',2,5,'Os fartos se alugaram por pão, e cessaram os famintos; até a estéril deu à luz sete filhos, e a que tinha muitos filhos enfraqueceu.'),
('acf','1sm',2,6,'O Senhor é o que tira a vida e a dá; faz descer à sepultura e faz tornar a subir dela.'),
('acf','1sm',2,7,'O Senhor empobrece e enriquece; abaixa e também exalta.'),
('acf','1sm',2,8,'Levanta o pobre do pó, e desde o monturo exalta o necessitado, para o fazer assentar entre os príncipes, para o fazer herdar o trono de glória; porque do Senhor são os alicerces da terra, e assentou sobre eles o mundo.'),
('acf','1sm',2,9,'Os pés dos seus santos guardará, porém os ímpios ficarão mudos nas trevas; porque o homem não prevalecerá pela força.'),
('acf','1sm',2,10,'Os que contendem com o Senhor serão quebrantados, desde os céus trovejará sobre eles; o Senhor julgará as extremidades da terra; e dará força ao seu rei, e exaltará o poder do seu ungido.'),
('acf','1sm',2,11,'Então Elcana foi a Ramá, à sua casa; porém o menino ficou servindo ao Senhor, perante o sacerdote Eli.'),
('acf','1sm',2,12,'Eram, porém, os filhos de Eli filhos de Belial; não conheciam ao Senhor.'),
('acf','1sm',2,13,'Porquanto o costume daqueles sacerdotes com o povo era que, oferecendo alguém algum sacrifício, estando-se cozendo a carne, vinha o moço do sacerdote, com um garfo de três dentes em sua mão;'),
('acf','1sm',2,14,'E enfiava-o na caldeira, ou na panela, ou no caldeirão, ou na marmita; e tudo quanto o garfo tirava, o sacerdote tomava para si; assim faziam a todo o Israel que ia ali a Siló.'),
('acf','1sm',2,15,'Também antes de queimarem a gordura vinha o moço do sacerdote, e dizia ao homem que sacrificava: Dá essa carne para assar ao sacerdote; porque não receberá de ti carne cozida, mas crua.'),
('acf','1sm',2,16,'E, dizendo-lhe o homem: Queime-se primeiro a gordura de hoje, e depois toma para ti quanto desejar a tua alma, então ele lhe dizia: Não, agora a hás de dar, e, se não, por força a tomarei.'),
('acf','1sm',2,17,'Era, pois, muito grande o pecado destes moços perante o Senhor, porquanto os homens desprezavam a oferta do Senhor.'),
('acf','1sm',2,18,'Porém Samuel ministrava perante o Senhor, sendo ainda jovem, vestido com um éfode de linho.'),
('acf','1sm',2,19,'E sua mãe lhe fazia uma túnica pequena, e de ano em ano lha trazia, quando com seu marido subia para oferecer o sacrifício anual.'),
('acf','1sm',2,20,'E Eli abençoava a Elcana e a sua mulher, e dizia: O Senhor te dê descendência desta mulher, pela petição que fez ao Senhor. E voltavam para o seu lugar.'),
('acf','1sm',2,21,'Visitou, pois, o Senhor a Ana, que concebeu, e deu à luz três filhos e duas filhas; e o jovem Samuel crescia diante do Senhor.'),
('acf','1sm',2,22,'Era, porém, Eli já muito velho, e ouvia tudo quanto seus filhos faziam a todo o Israel, e de como se deitavam com as mulheres que em bandos se ajuntavam à porta da tenda da congregação.'),
('acf','1sm',2,23,'E disse-lhes: Por que fazeis tais coisas? Pois ouço de todo este povo os vossos malefícios.'),
('acf','1sm',2,24,'Não, filhos meus, porque não é boa esta fama que ouço; fazeis transgredir o povo do Senhor.'),
('acf','1sm',2,25,'Pecando homem contra homem, os juízes o julgarão; pecando, porém, o homem contra o Senhor, quem rogará por ele? Mas não ouviram a voz de seu pai, porque o Senhor os queria matar.'),
('acf','1sm',2,26,'E o jovem Samuel ia crescendo, e fazia-se agradável, assim para com o Senhor, como também para com os homens.'),
('acf','1sm',2,27,'E veio um homem de Deus a Eli, e disse-lhe: Assim diz o Senhor: Não me manifestei, na verdade, à casa de teu pai, estando eles ainda no Egito, na casa de Faraó?'),
('acf','1sm',2,28,'E eu o escolhi dentre todas as tribos de Israel por sacerdote, para oferecer sobre o meu altar, para acender o incenso, e para trazer o éfode perante mim; e dei à casa de teu pai todas as ofertas queimadas dos filhos de Israel.'),
('acf','1sm',2,29,'Por que pisastes o meu sacrifício e a minha oferta de alimentos, que ordenei na minha morada, e honras a teus filhos mais do que a mim, para vos engordardes do principal de todas as ofertas do meu povo de Israel?'),
('acf','1sm',2,30,'Portanto, diz o Senhor Deus de Israel: Na verdade tinha falado eu que a tua casa e a casa de teu pai andariam diante de mim perpetuamente; porém agora diz o Senhor: Longe de mim tal coisa, porque aos que me honram honrarei, porém os que me desprezam serão desprezados.'),
('acf','1sm',2,31,'Eis que vêm dias em que cortarei o teu braço e o braço da casa de teu pai, para que não haja mais ancião algum em tua casa.'),
('acf','1sm',2,32,'E verás o aperto da morada de Deus, em lugar de todo o bem que houvera de fazer a Israel; nem haverá por todos os dias ancião algum em tua casa.'),
('acf','1sm',2,33,'O homem, porém, a quem eu não desarraigar do meu altar será para te consumir os olhos e para te entristecer a alma; e toda a multidão da tua casa morrerá quando chegar à idade varonil.'),
('acf','1sm',2,34,'E isto te será por sinal, a saber: o que acontecerá a teus dois filhos, a Hofni e a Finéias; ambos morrerão no mesmo dia.'),
('acf','1sm',2,35,'E eu suscitarei para mim um sacerdote fiel, que procederá segundo o meu coração e a minha alma, e eu lhe edificarei uma casa firme, e andará sempre diante do meu ungido.'),
('acf','1sm',2,36,'E será que todo aquele que restar da tua casa virá a inclinar-se diante dele por uma moeda de prata e por um bocado de pão, e dirá: Rogo-te que me admitas a algum ministério sacerdotal, para que possa comer um pedaço de pão.'),
('acf','1sm',3,1,'E o jovem Samuel servia ao SENHOR perante Eli; e a palavra do SENHOR era de muita valia naqueles dias; não havia visão manifesta.'),
('acf','1sm',3,2,'E sucedeu, naquele dia, que, estando Eli deitado no seu lugar (e os seus olhos começavam a escurecer, pois não podia ver),'),
('acf','1sm',3,3,'E estando também Samuel já deitado, antes que a lâmpada de Deus se apagasse no templo do Senhor, onde estava a arca de Deus,'),
('acf','1sm',3,4,'O Senhor chamou a Samuel, e disse ele: Eis-me aqui.'),
('acf','1sm',3,5,'E correu a Eli, e disse: Eis-me aqui, porque tu me chamaste. Mas ele disse: Não te chamei eu, torna a deitar-te. E foi e se deitou.'),
('acf','1sm',3,6,'E o Senhor tornou a chamar outra vez a Samuel, e Samuel se levantou, e foi a Eli, e disse: Eis-me aqui, porque tu me chamaste. Mas ele disse: Não te chamei eu, filho meu, torna a deitar-te.'),
('acf','1sm',3,7,'Porém Samuel ainda não conhecia ao Senhor, e ainda não lhe tinha sido manifestada a palavra do Senhor.'),
('acf','1sm',3,8,'O Senhor, pois, tornou a chamar a Samuel terceira vez, e ele se levantou, e foi a Eli, e disse: Eis-me aqui, porque tu me chamaste. Então entendeu Eli que o Senhor chamava o jovem.'),
('acf','1sm',3,9,'Por isso Eli disse a Samuel: Vai deitar-te e há de ser que, se te chamar, dirás: Fala, Senhor, porque o teu servo ouve. Então Samuel foi e se deitou no seu lugar.'),
('acf','1sm',3,10,'Então veio o Senhor, e pôs-se ali, e chamou como das outras vezes: Samuel, Samuel. E disse Samuel: Fala, porque o teu servo ouve.'),
('acf','1sm',3,11,'E disse o Senhor a Samuel: Eis que vou fazer uma coisa em Israel, a qual todo o que ouvir lhe tinirão ambos os ouvidos.'),
('acf','1sm',3,12,'Naquele mesmo dia suscitarei contra Eli tudo quanto tenho falado contra a sua casa, começarei e acabarei.'),
('acf','1sm',3,13,'Porque eu já lhe fiz saber que julgarei a sua casa para sempre, pela iniqüidade que ele bem conhecia, porque, fazendo-se os seus filhos execráveis, não os repreendeu.'),
('acf','1sm',3,14,'Portanto, jurei à casa de Eli que nunca jamais será expiada a sua iniqüidade, nem com sacrifício, nem com oferta de alimentos.'),
('acf','1sm',3,15,'E Samuel ficou deitado até pela manhã, e então abriu as portas da casa do Senhor; porém temia Samuel relatar esta visão a Eli.'),
('acf','1sm',3,16,'Então chamou Eli a Samuel, e disse: Samuel, meu filho. E disse ele: Eis-me aqui.'),
('acf','1sm',3,17,'E ele disse: Qual é a palavra que te falou? Peço-te que não ma encubras; assim Deus te faça, e outro tanto, se me encobrires alguma palavra de todas as que te falou.'),
('acf','1sm',3,18,'Então Samuel lhe contou todas aquelas palavras, e nada lhe encobriu. E disse ele: Ele é o Senhor; faça o que bem parecer aos seus olhos.'),
('acf','1sm',3,19,'E crescia Samuel, e o Senhor era com ele, e nenhuma de todas as suas palavras deixou cair em terra.'),
('acf','1sm',3,20,'E todo o Israel, desde Dã até Berseba, conheceu que Samuel estava confirmado por profeta do Senhor.'),
('acf','1sm',3,21,'E continuou o Senhor a aparecer em Siló; porquanto o Senhor se manifestava a Samuel em Siló pela palavra do Senhor.'),
('acf','1sm',4,1,'E veio a palavra de Samuel a todo o Israel; e Israel saiu à peleja contra os filisteus e acampou-se junto a Ebenézer; e os filisteus se acamparam junto a Afeque.'),
('acf','1sm',4,2,'E os filisteus se dispuseram em ordem de batalha, para sair contra Israel; e, estendendo-se a peleja, Israel foi ferido diante dos filisteus, porque feriram na batalha, no campo, uns quatro mil homens.'),
('acf','1sm',4,3,'E voltando o povo ao arraial, disseram os anciãos de Israel: Por que nos feriu o Senhor hoje diante dos filisteus? Tragamos de Siló a arca da aliança do Senhor, e venha no meio de nós, para que nos livre da mão de nossos inimigos.'),
('acf','1sm',4,4,'Enviou, pois, o povo a Siló, e trouxeram de lá a arca da aliança do Senhor dos Exércitos, que habita entre os querubins; e os dois filhos de Eli, Hofni e Finéias, estavam ali com a arca da aliança de Deus.'),
('acf','1sm',4,5,'E sucedeu que, vindo a arca da aliança do Senhor ao arraial, todo o Israel gritou com grande júbilo, até que a terra estremeceu.'),
('acf','1sm',4,6,'E os filisteus, ouvindo a voz de júbilo, disseram: Que voz de grande júbilo é esta no arraial dos hebreus? Então souberam que a arca do Senhor era vinda ao arraial.'),
('acf','1sm',4,7,'Por isso os filisteus se atemorizaram, porque diziam: Deus veio ao arraial. E diziam mais: Ai de nós! Tal nunca jamais sucedeu antes.'),
('acf','1sm',4,8,'Ai de nós! Quem nos livrará da mão desses grandiosos deuses? Estes são os deuses que feriram aos egípcios com todas as pragas junto ao deserto.'),
('acf','1sm',4,9,'Esforçai-vos, e sede homens, ó filisteus, para que porventura não venhais a servir aos hebreus, como eles serviram a vós; sede, pois, homens, e pelejai.'),
('acf','1sm',4,10,'Então pelejaram os filisteus, e Israel foi ferido, fugindo cada um para a sua tenda; e foi tão grande o estrago, que caíram de Israel trinta mil homens de pé.'),
('acf','1sm',4,11,'E foi tomada a arca de Deus: e os dois filhos de Eli, Hofni e Finéias, morreram.'),
('acf','1sm',4,12,'Então correu, da batalha, um homem de Benjamim, e chegou no mesmo dia a Siló; e trazia as vestes rotas, e terra sobre a cabeça.'),
('acf','1sm',4,13,'E, chegando ele, eis que Eli estava assentado numa cadeira, olhando para o caminho; porquanto o seu coração estava tremendo pela arca de Deus. Entrando, pois, aquele homem a anunciar isto na cidade, toda a cidade gritou.'),
('acf','1sm',4,14,'E Eli, ouvindo os gritos, disse: Que alvoroço é esse? Então chegou aquele homem apressadamente, e veio, e o anunciou a Eli.'),
('acf','1sm',4,15,'E era Eli da idade de noventa e oito anos; e estavam os seus olhos tão escurecidos, que já não podia ver.'),
('acf','1sm',4,16,'E disse aquele homem a Eli: Eu sou o que venho da batalha; porque eu fugi hoje da batalha. E disse ele: Que coisa sucedeu, filho meu?'),
('acf','1sm',4,17,'Então respondeu o que trazia as notícias, e disse: Israel fugiu de diante dos filisteus, e houve também grande matança entre o povo; e, além disso, também teus dois filhos, Hofni e Finéias, morreram, e a arca de Deus foi tomada.'),
('acf','1sm',4,18,'E sucedeu que, fazendo ele menção da arca de Deus, Eli caiu da cadeira para trás, ao lado da porta, e quebrou-se-lhe o pescoço e morreu; porquanto o homem era velho e pesado; e tinha ele julgado Israel quarenta anos.'),
('acf','1sm',4,19,'E, estando sua nora, a mulher de Finéias, grávida, e próxima ao parto, e ouvindo estas notícias, de que a arca de Deus era tomada, e de que seu sogro e seu marido morreram, encurvou-se e deu à luz; porquanto as dores lhe sobrevieram.'),
('acf','1sm',4,20,'E, ao tempo em que ia morrendo, disseram as mulheres que estavam com ela: Não temas, pois deste à luz um filho. Ela porém não respondeu, nem fez caso disso.'),
('acf','1sm',4,21,'E chamou ao menino Icabode, dizendo: De Israel se foi a glória! Porque a arca de Deus foi tomada, e por causa de seu sogro e de seu marido.'),
('acf','1sm',4,22,'E disse: De Israel a glória é levada presa; pois é tomada a arca de Deus.'),
('acf','1sm',5,1,'Os filisteus, pois, tomaram a arca de Deus e a trouxeram de Ebenézer a Asdode.'),
('acf','1sm',5,2,'Tomaram os filisteus a arca de Deus, e a colocaram na casa de Dagom, e a puseram junto a Dagom.'),
('acf','1sm',5,3,'Levantando-se, porém, de madrugada no dia seguinte, os de Asdode, eis que Dagom estava caído com o rosto em terra, diante da arca do Senhor; e tomaram a Dagom, e tornaram a pô-lo no seu lugar.'),
('acf','1sm',5,4,'E, levantando-se de madrugada, no dia seguinte, pela manhã, eis que Dagom jazia caído com o rosto em terra diante da arca do Senhor; e a cabeça de Dagom e ambas as palmas das suas mãos estavam cortadas sobre o limiar; somente o tronco ficou a Dagom.'),
('acf','1sm',5,5,'Por isso nem os sacerdotes de Dagom, nem nenhum de todos os que entram na casa de Dagom pisam o limiar de Dagom em Asdode, até ao dia de hoje.'),
('acf','1sm',5,6,'Porém a mão do Senhor se agravou sobre os de Asdode, e os assolou; e os feriu com hemorróidas, em Asdode e nos seus termos.'),
('acf','1sm',5,7,'Vendo então os homens de Asdode que assim foi, disseram: Não fique conosco a arca do Deus de Israel; pois a sua mão é dura sobre nós, e sobre Dagom, nosso deus.'),
('acf','1sm',5,8,'Por isso enviaram mensageiros e congregaram a si todos os príncipes dos filisteus, e disseram: Que faremos nós da arca do Deus de Israel? E responderam: a arca do Deus de Israel será levada até Gate. Assim levaram para lá a arca do Deus de Israel.'),
('acf','1sm',5,9,'E sucedeu que, assim que a levaram, a mão do Senhor veio contra aquela cidade, com mui grande vexame; pois feriu aos homens daquela cidade, desde o pequeno até ao grande; e tinham hemorróidas nas partes íntimas.'),
('acf','1sm',5,10,'Então enviaram a arca de Deus a Ecrom. Sucedeu, porém, que, vindo a arca de Deus a Ecrom, os de Ecrom exclamaram, dizendo: Transportaram para nós a arca do Deus de Israel, para nos matarem, a nós e ao nosso povo.'),
('acf','1sm',5,11,'E enviaram, e congregaram a todos os príncipes dos filisteus, e disseram: Enviai a arca do Deus de Israel, e torne para o seu lugar, para que não mate nem a nós nem ao nosso povo. Porque havia mortal vexame em toda a cidade, e a mão de Deus muito se agravara ali.'),
('acf','1sm',5,12,'E os homens que não morriam eram tão atacados com hemorróidas que o clamor da cidade subia até o céu.'),
('acf','1sm',6,1,'Havendo, pois, estado a arca do SENHOR na terra dos filisteus sete meses,'),
('acf','1sm',6,2,'Os filisteus chamaram os sacerdotes e os adivinhadores, dizendo: Que faremos nós com a arca do Senhor? Fazei-nos saber como a tornaremos a enviar ao seu lugar.'),
('acf','1sm',6,3,'Os quais disseram: Se enviardes a arca do Deus de Israel, não a envieis vazia, porém sem falta enviareis uma oferta para a expiação da culpa; então sereis curados, e se vos fará saber porque a sua mão não se retira de vós.'),
('acf','1sm',6,4,'Então disseram: Qual é a expiação da culpa que lhe havemos de enviar? E disseram: Segundo o número dos príncipes dos filisteus, cinco hemorróidas de ouro e cinco ratos de ouro; porquanto a praga é uma mesma sobre todos vós e sobre todos os vossos príncipes.'),
('acf','1sm',6,5,'Fazei, pois, umas imagens das vossas hemorróidas e dos vossos ratos, que andam destruindo a terra, e dai glória ao Deus de Israel; porventura aliviará a sua mão de cima de vós, e de cima do vosso deus, e de cima da vossa terra.'),
('acf','1sm',6,6,'Por que, pois, endureceríeis o vosso coração, como os egípcios e Faraó endureceram os seus corações? Porventura depois de os haver tratado tão mal, os não deixaram ir, e eles não se foram?'),
('acf','1sm',6,7,'Agora, pois, tomai e fazei-vos um carro novo, e tomai duas vacas com crias, sobre as quais não tenha subido o jugo, e atai as vacas ao carro, e tirai delas os seus bezerros e levai-os para casa.'),
('acf','1sm',6,8,'Então tomai a arca do Senhor, e ponde-a sobre o carro, e colocai, num cofre, ao seu lado, as figuras de ouro que lhe haveis de oferecer em expiação da culpa, e assim a enviareis, para que se vá.'),
('acf','1sm',6,9,'Vede então: Se ela subir pelo caminho do seu termo a Bete-Semes, foi ele quem nos fez este grande mal; e, se não, saberemos que não nos tocou a sua mão, e que isto nos sucedeu por acaso.'),
('acf','1sm',6,10,'E assim fizeram aqueles homens, e tomaram duas vacas que criavam, e as ataram ao carro; e os seus bezerros encerraram em casa.'),
('acf','1sm',6,11,'E puseram a arca do Senhor sobre o carro, como também o cofre com os ratos de ouro e com as imagens das suas hemorróidas.'),
('acf','1sm',6,12,'Então as vacas se encaminharam diretamente pelo caminho de Bete-Semes, e seguiam um mesmo caminho, andando e berrando, sem se desviarem, nem para a direita nem para a esquerda; e os príncipes dos filisteus foram atrás delas, até ao termo de Bete-Semes.'),
('acf','1sm',6,13,'E andavam os de Bete-Semes fazendo a sega do trigo no vale, e, levantando os seus olhos, viram a arca, e, vendo-a, se alegraram.'),
('acf','1sm',6,14,'E o carro veio ao campo de Josué, o bete-semita, e parou ali onde havia uma grande pedra. E fenderam a madeira do carro, e ofereceram as vacas ao Senhor em holocausto.'),
('acf','1sm',6,15,'E os levitas desceram a arca do Senhor, como também o cofre que estava junto a ela, em que estavam os objetos de ouro, e puseram-nos sobre aquela grande pedra; e os homens de Bete-Semes ofereceram holocaustos e sacrifícios ao Senhor no mesmo dia.'),
('acf','1sm',6,16,'E, vendo aquilo os cinco príncipes dos filisteus, voltaram para Ecrom no mesmo dia.'),
('acf','1sm',6,17,'Estas, pois, são as hemorróidas de ouro que enviaram os filisteus ao Senhor em expiação da culpa: Por Asdode uma, por Gaza outra, por Ascalom outra, por Gate outra, por Ecrom outra.'),
('acf','1sm',6,18,'Como também os ratos de ouro, segundo o número de todas as cidades dos filisteus, pertencentes aos cinco príncipes, desde as cidades fortificadas até às aldeias, e até Abel. A grande pedra, sobre a qual puseram a arca do Senhor, ainda está até ao dia de hoje no campo de Josué, o bete-semita.'),
('acf','1sm',6,19,'E o Senhor feriu os homens de Bete-Semes, porquanto olharam para dentro da arca do Senhor; feriu do povo cinqüenta mil e setenta homens; então o povo se entristeceu, porquanto o Senhor fizera tão grande estrago entre o povo.'),
('acf','1sm',6,20,'Então disseram os homens de Bete-Semes: Quem poderia subsistir perante este santo Senhor Deus? E a quem subirá de nós?'),
('acf','1sm',6,21,'Enviaram, pois, mensageiros aos habitantes de Quiriate-Jearim, dizendo: Os filisteus remeteram a arca do Senhor; descei, pois, e fazei-a subir para vós.'),
('acf','1sm',7,1,'Então vieram os homens de Quiriate-Jearim, e levaram a arca do SENHOR, e a trouxeram à casa de Abinadabe, no outeiro; e consagraram a Eleazar, seu filho, para que guardasse a arca do SENHOR.'),
('acf','1sm',7,2,'E sucedeu que, desde aquele dia, a arca ficou em Quiriate-Jearim, e tantos dias se passaram que até chegaram vinte anos, e lamentava toda a casa de Israel pelo Senhor.'),
('acf','1sm',7,3,'Então falou Samuel a toda a casa de Israel, dizendo: Se com todo o vosso coração vos converterdes ao Senhor, tirai dentre vós os deuses estranhos e os astarotes, e preparai o vosso coração ao Senhor, e servi a ele só, e vos livrará da mão dos filisteus.'),
('acf','1sm',7,4,'Então os filhos de Israel tiraram dentre si aos baalins e aos astarotes, e serviram só ao Senhor.'),
('acf','1sm',7,5,'Disse mais Samuel: Congregai a todo o Israel em Mizpá; e orarei por vós ao Senhor.'),
('acf','1sm',7,6,'E congregaram-se em Mizpá, e tiraram água, e a derramaram perante o Senhor, e jejuaram aquele dia, e disseram ali: Pecamos contra o Senhor. E julgava Samuel os filhos de Israel em Mizpá.'),
('acf','1sm',7,7,'Ouvindo, pois, os filisteus que os filhos de Israel estavam congregados em Mizpá, subiram os maiorais dos filisteus contra Israel; o que ouvindo os filhos de Israel, temeram por causa dos filisteus.'),
('acf','1sm',7,8,'Por isso disseram os filhos de Israel a Samuel: Não cesses de clamar ao Senhor nosso Deus por nós, para que nos livre da mão dos filisteus.'),
('acf','1sm',7,9,'Então tomou Samuel um cordeiro de mama, e sacrificou-o inteiro em holocausto ao Senhor; e clamou Samuel ao Senhor por Israel, e o Senhor lhe deu ouvidos.'),
('acf','1sm',7,10,'E sucedeu que, estando Samuel sacrificando o holocausto, os filisteus chegaram à peleja contra Israel; e trovejou o Senhor aquele dia com grande estrondo sobre os filisteus, e os confundiu de tal modo que foram derrotados diante dos filhos de Israel.'),
('acf','1sm',7,11,'E os homens de Israel saíram de Mizpá; e perseguiram os filisteus, e os feriram até abaixo de Bete-Car.'),
('acf','1sm',7,12,'Então tomou Samuel uma pedra, e a pôs entre Mizpá e Sem, e chamou-lhe Ebenézer; e disse: Até aqui nos ajudou o Senhor.'),
('acf','1sm',7,13,'Assim os filisteus foram abatidos, e nunca mais vieram aos termos de Israel, porquanto foi a mão do Senhor contra os filisteus todos os dias de Samuel.'),
('acf','1sm',7,14,'E as cidades que os filisteus tinham tomado a Israel foram-lhe restituídas, desde Ecrom até Gate, e até os seus termos Israel arrebatou da mão dos filisteus; e houve paz entre Israel e entre os amorreus.'),
('acf','1sm',7,15,'E Samuel julgou a Israel todos os dias da sua vida.'),
('acf','1sm',7,16,'E ia de ano em ano, e rodeava a Betel, e a Gilgal, e a Mizpá, e julgava a Israel em todos aqueles lugares.'),
('acf','1sm',7,17,'Porém voltava a Ramá, porque estava ali a sua casa, e ali julgava a Israel; e edificou ali um altar ao Senhor.'),
('acf','1sm',8,1,'E sucedeu que, tendo Samuel envelhecido, constituiu a seus filhos por juízes sobre Israel.'),
('acf','1sm',8,2,'E o nome do seu filho primogênito era Joel, e o nome do seu segundo, Abia; e foram juízes em Berseba.'),
('acf','1sm',8,3,'Porém seus filhos não andaram pelos caminhos dele, antes se inclinaram à avareza, e aceitaram suborno, e perverteram o direito.'),
('acf','1sm',8,4,'Então todos os anciãos de Israel se congregaram, e vieram a Samuel, a Ramá,'),
('acf','1sm',8,5,'E disseram-lhe: Eis que já estás velho, e teus filhos não andam pelos teus caminhos; constitui-nos, pois, agora um rei sobre nós, para que ele nos julgue, como o têm todas as nações.'),
('acf','1sm',8,6,'Porém esta palavra pareceu mal aos olhos de Samuel, quando disseram: Dá-nos um rei, para que nos julgue. E Samuel orou ao Senhor.'),
('acf','1sm',8,7,'E disse o Senhor a Samuel: Ouve a voz do povo em tudo quanto te dizem, pois não te têm rejeitado a ti, antes a mim me têm rejeitado, para eu não reinar sobre eles.'),
('acf','1sm',8,8,'Conforme a todas as obras que fizeram desde o dia em que os tirei do Egito até ao dia de hoje, a mim me deixaram, e a outros deuses serviram, assim também fazem a ti.'),
('acf','1sm',8,9,'Agora, pois, ouve à sua voz, porém protesta-lhes solenemente, e declara-lhes qual será o costume do rei que houver de reinar sobre eles.'),
('acf','1sm',8,10,'E falou Samuel todas as palavras do Senhor ao povo, que lhe pedia um rei.'),
('acf','1sm',8,11,'E disse: Este será o costume do rei que houver de reinar sobre vós; ele tomará os vossos filhos, e os empregará nos seus carros, e como seus cavaleiros, para que corram adiante dos seus carros.'),
('acf','1sm',8,12,'E os porá por chefes de mil, e de cinqüenta; e para que lavrem a sua lavoura, e façam a sua sega, e fabriquem as suas armas de guerra e os petrechos de seus carros.'),
('acf','1sm',8,13,'E tomará as vossas filhas para perfumistas, cozinheiras e padeiras.'),
('acf','1sm',8,14,'E tomará o melhor das vossas terras, e das vossas vinhas, e dos vossos olivais, e os dará aos seus servos.'),
('acf','1sm',8,15,'E as vossas sementes, e as vossas vinhas dizimará, para dar aos seus oficiais, e aos seus servos.'),
('acf','1sm',8,16,'Também os vossos servos, e as vossas servas, e os vossos melhores moços, e os vossos jumentos tomará, e os empregará no seu trabalho.'),
('acf','1sm',8,17,'Dizimará o vosso rebanho, e vós lhe servireis de servos.'),
('acf','1sm',8,18,'Então naquele dia clamareis por causa do vosso rei, que vós houverdes escolhido; mas o Senhor não vos ouvirá naquele dia.'),
('acf','1sm',8,19,'Porém o povo não quis ouvir a voz de Samuel; e disseram: Não, mas haverá sobre nós um rei.'),
('acf','1sm',8,20,'E nós também seremos como todas as outras nações; e o nosso rei nos julgará, e sairá adiante de nós, e fará as nossas guerras.'),
('acf','1sm',8,21,'Ouvindo, pois, Samuel todas as palavras do povo, as repetiu aos ouvidos do Senhor.'),
('acf','1sm',8,22,'Então o Senhor disse a Samuel: Dá ouvidos à sua voz, e constitui-lhes rei. Então Samuel disse aos homens de Israel: Volte cada um à sua cidade.'),
('acf','1sm',9,1,'E havia um homem de Benjamim, cujo nome era Quis, filho de Abiel, filho de Zeror, filho de Becorate, filho de Afia, filho de um homem de Benjamim; homem poderoso.'),
('acf','1sm',9,2,'Este tinha um filho, cujo nome era Saul, moço, e tão belo que entre os filhos de Israel não havia outro homem mais belo do que ele; desde os ombros para cima sobressaía a todo o povo.'),
('acf','1sm',9,3,'E perderam-se as jumentas de Quis, pai de Saul; por isso disse Quis a Saul, seu filho: Toma agora contigo um dos moços, e levanta-te e vai procurar as jumentas.'),
('acf','1sm',9,4,'Passaram, pois, pela montanha de Efraim, e dali passaram à terra de Salisa, porém não as acharam; depois passaram à terra de Saalim, porém tampouco estavam ali; também passaram à terra de Benjamim, porém tampouco as acharam.'),
('acf','1sm',9,5,'Vindo eles então à terra de Zufe, Saul disse para o seu moço, com quem ele ia: Vem, e voltemos; para que porventura meu pai não deixe de inquietar-se pelas jumentas e se aflija por causa de nós.'),
('acf','1sm',9,6,'Porém ele lhe disse: Eis que há nesta cidade um homem de Deus, e homem honrado é; tudo quanto diz, sucede assim infalivelmente; vamo-nos agora lá; porventura nos mostrará o caminho que devemos seguir.'),
('acf','1sm',9,7,'Então Saul disse ao seu moço: Eis, porém, se lá formos, que levaremos então àquele homem? Porque o pão de nossos alforjes se acabou, e presente nenhum temos para levar ao homem de Deus; que temos?'),
('acf','1sm',9,8,'E o moço tornou a responder a Saul, e disse: Eis que ainda se acha na minha mão um quarto de um siclo de prata, o qual darei ao homem de Deus, para que nos mostre o caminho'),
('acf','1sm',9,9,'(Antigamente em Israel, indo alguém consultar a Deus, dizia assim: Vinde, e vamos ao vidente; porque ao profeta de hoje, antigamente se chamava vidente).'),
('acf','1sm',9,10,'Então disse Saul ao moço: Bem dizes; vem, pois, vamos. E foram-se à cidade onde estava o homem de Deus.'),
('acf','1sm',9,11,'E, subindo eles à cidade, acharam umas moças que saíam a tirar água; e disseram-lhes: Está aqui o vidente?'),
('acf','1sm',9,12,'E elas lhes responderam, e disseram: Sim, eis aí o tens diante de ti; apressa-te, pois, porque hoje veio à cidade; porquanto o povo tem hoje sacrifício no alto.'),
('acf','1sm',9,13,'Entrando vós na cidade, logo o achareis, antes que suba ao alto para comer; porque o povo não comerá, até que ele venha; porque ele é o que abençoa o sacrifício, e depois comem os convidados; subi, pois, agora, que hoje o achareis.'),
('acf','1sm',9,14,'Subiram, pois, à cidade; e, vindo eles no meio da cidade, eis que Samuel lhes saiu ao encontro, para subir ao alto.'),
('acf','1sm',9,15,'Porque o Senhor revelara isto aos ouvidos de Samuel, um dia antes que Saul viesse, dizendo:'),
('acf','1sm',9,16,'Amanhã a estas horas te enviarei um homem da terra de Benjamim, o qual ungirás por capitão sobre o meu povo de Israel, e ele livrará o meu povo da mão dos filisteus; porque tenho olhado para o meu povo; porque o seu clamor chegou a mim.'),
('acf','1sm',9,17,'E quando Samuel viu a Saul, o Senhor lhe respondeu: Eis aqui o homem de quem eu te falei. Este dominará sobre o meu povo.'),
('acf','1sm',9,18,'E Saul se chegou a Samuel no meio da porta, e disse: Mostra-me, peço-te, onde está a casa do vidente.'),
('acf','1sm',9,19,'E Samuel respondeu a Saul, e disse: Eu sou o vidente; sobe diante de mim ao alto, e comei hoje comigo; e pela manhã te despedirei, e tudo quanto está no teu coração, to declararei.'),
('acf','1sm',9,20,'E quanto às jumentas que há três dias se te perderam, não ocupes o teu coração com elas, porque já se acharam. E para quem é todo o desejo de Israel? Porventura não é para ti, e para toda a casa de teu pai?'),
('acf','1sm',9,21,'Então respondeu Saul, e disse: Porventura não sou eu filho de Benjamim, da menor das tribos de Israel? E a minha família a menor de todas as famílias da tribo de Benjamim? Por que, pois, me falas com semelhantes palavras?'),
('acf','1sm',9,22,'Porém Samuel tomou a Saul e ao seu moço, e os levou à câmara; e deu-lhes lugar acima de todos os convidados, que eram uns trinta homens.'),
('acf','1sm',9,23,'Então disse Samuel ao cozinheiro: Dá aqui a porção que te dei, de que te disse: Põe-na à parte contigo.'),
('acf','1sm',9,24,'Levantou, pois, o cozinheiro a espádua, com o que havia nela, e pô-la diante de Saul; e disse Samuel: Eis que o que foi reservado está diante de ti. Come; porque se guardou para ti para esta ocasião, dizendo eu: Tenho convidado o povo. Assim comeu Saul aquele dia com Samuel.'),
('acf','1sm',9,25,'Então desceram do alto para a cidade; e falou com Saul sobre o eirado.'),
('acf','1sm',9,26,'E se levantaram de madrugada; e sucedeu que, quase ao subir da alva, chamou Samuel a Saul ao eirado, dizendo: Levanta-te, e despedir-te-ei. Levantou-se Saul, e saíram ambos para fora, ele e Samuel.'),
('acf','1sm',9,27,'E, descendo eles para a extremidade da cidade, Samuel disse a Saul: Dize ao moço que passe adiante de nós (e passou); porém tu espera agora, e te farei ouvir a palavra de Deus.'),
('acf','1sm',10,1,'Então tomou Samuel um vaso de azeite, e lho derramou sobre a cabeça, e beijou-o, e disse: Porventura não te ungiu o SENHOR por capitão sobre a sua herança?'),
('acf','1sm',10,2,'Apartando-te hoje de mim, acharás dois homens junto ao sepulcro de Raquel, no termo de Benjamim, em Zelza, os quais te dirão: Acharam-se as jumentas que foste buscar, e eis que já o teu pai deixou o negócio das jumentas, e anda aflito por causa de vós, dizendo: Que farei eu por meu filho?'),
('acf','1sm',10,3,'E quando dali passares mais adiante, e chegares ao carvalho de Tabor, ali te encontrarão três homens, que vão subindo a Deus a Betel; um levando três cabritos, o outro três bolos de pão e o outro um odre de vinho.'),
('acf','1sm',10,4,'E te perguntarão como estás, e te darão dois pães, que tomarás das suas mãos.'),
('acf','1sm',10,5,'Então chegarás ao outeiro de Deus, onde está a guarnição dos filisteus; e há de ser que, entrando ali na cidade, encontrarás um grupo de profetas que descem do alto, e trazem diante de si saltérios, e tambores, e flautas, e harpas; e eles estarão profetizando.'),
('acf','1sm',10,6,'E o Espírito do Senhor se apoderará de ti, e profetizarás com eles, e tornar-te-ás um outro homem.'),
('acf','1sm',10,7,'E há de ser que, quando estes sinais te vierem, faze o que achar a tua mão, porque Deus é contigo.'),
('acf','1sm',10,8,'Tu, porém, descerás antes de mim a Gilgal, e eis que eu descerei a ti, para sacrificar holocaustos, e para oferecer ofertas pacíficas; ali sete dias esperarás, até que eu venha a ti, e te declare o que hás de fazer.'),
('acf','1sm',10,9,'Sucedeu, pois, que, virando ele as costas para partir de Samuel, Deus lhe mudou o coração em outro; e todos aqueles sinais aconteceram naquele mesmo dia.'),
('acf','1sm',10,10,'E, chegando eles ao outeiro, eis que um grupo de profetas lhes saiu ao encontro; e o Espírito de Deus se apoderou dele, e profetizou no meio deles.'),
('acf','1sm',10,11,'E aconteceu que, como todos os que antes o conheciam viram que ele profetizava com os profetas, então disse o povo, cada um ao seu companheiro: Que é o que sucedeu ao filho de Quis? Está também Saul entre os profetas?'),
('acf','1sm',10,12,'Então um homem dali respondeu, e disse: Pois quem é o pai deles? Pelo que se tornou em provérbio: Está Saul também entre os profetas?'),
('acf','1sm',10,13,'E, acabando de profetizar, foi ao alto.'),
('acf','1sm',10,14,'E disse-lhe o tio de Saul, a ele e ao seu moço: Aonde fostes? E disse ele: A buscar as jumentas, e, vendo que não apareciam, fomos a Samuel.'),
('acf','1sm',10,15,'Então disse o tio de Saul: Declara-me, peço-te, o que vos disse Samuel?'),
('acf','1sm',10,16,'E disse Saul a seu tio: Declarou-nos, na verdade, que as jumentas foram encontradas. Porém o negócio do reino, de que Samuel falara, não lhe declarou.'),
('acf','1sm',10,17,'Convocou, pois, Samuel o povo ao Senhor, em Mizpá.'),
('acf','1sm',10,18,'E disse aos filhos de Israel: Assim disse o Senhor Deus de Israel: Eu fiz subir a Israel do Egito, e livrei-vos da mão dos egípcios e da mão de todos os reinos que vos oprimiam.'),
('acf','1sm',10,19,'Mas vós tendes rejeitado hoje a vosso Deus, que vos livrou de todos os vossos males e trabalhos, e lhe tendes falado: Põe um rei sobre nós. Agora, pois, ponde-vos perante o Senhor, pelas vossas tribos e segundo os vossos milhares.'),
('acf','1sm',10,20,'Tendo, pois, Samuel feito chegar todas as tribos, tomou-se a tribo de Benjamim.'),
('acf','1sm',10,21,'E, fazendo chegar a tribo de Benjamim pelas suas famílias, tomou-se a família de Matri; e dela se tomou Saul, filho de Quis; e o buscaram, porém não se achou.'),
('acf','1sm',10,22,'Então tornaram a perguntar ao Senhor se aquele homem ainda viria ali. E disse o Senhor: Eis que se escondeu entre a bagagem.'),
('acf','1sm',10,23,'E correram, e o tomaram dali, e pôs-se no meio do povo; e era mais alto do que todo o povo desde o ombro para cima.'),
('acf','1sm',10,24,'Então disse Samuel a todo o povo: Vedes já a quem o Senhor escolheu? Pois em todo o povo não há nenhum semelhante a ele. Então jubilou todo o povo, e disse: Viva o rei!'),
('acf','1sm',10,25,'E declarou Samuel ao povo o direito do reino, e escreveu-o num livro, e pô-lo perante o Senhor; então despediu Samuel a todo o povo, cada um para sua casa.'),
('acf','1sm',10,26,'E foi também Saul à sua casa, em Gibeá; e foram com ele do exército aqueles cujos corações Deus tocara.'),
('acf','1sm',10,27,'Mas os filhos de Belial disseram: É este o que nos há de livrar? E o desprezaram, e não lhe trouxeram presentes; porém ele se fez como surdo.'),
('acf','1sm',11,1,'Então subiu Naás, amonita, e sitiou a Jabes-Gileade; e disseram todos os homens de Jabes a Naás: Faze aliança conosco, e te serviremos.'),
('acf','1sm',11,2,'Porém Naás, amonita, lhes disse: Com esta condição farei aliança convosco: que a todos vos arranque o olho direito, e assim ponha esta afronta sobre todo o Israel.'),
('acf','1sm',11,3,'Então os anciãos de Jabes lhe disseram: Deixa-nos por sete dias, para que enviemos mensageiros por todos os termos de Israel, e, não havendo ninguém que nos livre, então viremos a ti.'),
('acf','1sm',11,4,'E, vindo os mensageiros a Gibeá de Saul, falaram estas palavras aos ouvidos do povo. Então todo o povo levantou a sua voz, e chorou.'),
('acf','1sm',11,5,'E eis que Saul vinha do campo, atrás dos bois; e disse Saul: Que tem o povo, que chora? E contaram-lhe as palavras dos homens de Jabes.'),
('acf','1sm',11,6,'Então o Espírito de Deus se apoderou de Saul, ouvindo estas palavras; e acendeu-se em grande maneira a sua ira.'),
('acf','1sm',11,7,'E tomou uma junta de bois, e cortou-os em pedaços, e os enviou a todos os termos de Israel pelas mãos dos mensageiros, dizendo: Qualquer que não seguir a Saul e a Samuel, assim se fará aos seus bois. Então caiu o temor do Senhor sobre o povo, e saíram como um só homem.'),
('acf','1sm',11,8,'E contou-os em Bezeque; e houve dos filhos de Israel trezentos mil, e dos homens de Judá trinta mil.'),
('acf','1sm',11,9,'Então disseram aos mensageiros que vieram: Assim direis aos homens de Jabes-Gileade: Amanhã, em aquecendo o sol, vos virá livramento. Vindo, pois, os mensageiros, e anunciando-o aos homens de Jabes, se alegraram.'),
('acf','1sm',11,10,'E os homens de Jabes disseram aos amonitas: Amanhã sairemos a vós; então nos fareis conforme a tudo o que parecer bem aos vossos olhos.'),
('acf','1sm',11,11,'E sucedeu que ao outro dia Saul pôs o povo em três companhias, e vieram ao meio do arraial pela vigília da manhã, e feriram aos amonitas até que o dia aqueceu; e sucedeu que os restantes se espalharam, de modo que não ficaram dois deles juntos.'),
('acf','1sm',11,12,'Então disse o povo a Samuel: Quem é aquele que dizia que Saul não reinaria sobre nós? Dai-nos aqueles homens, e os mataremos.'),
('acf','1sm',11,13,'Porém Saul disse: Hoje não morrerá nenhum, pois hoje tem feito o Senhor um livramento em Israel.'),
('acf','1sm',11,14,'E disse Samuel ao povo: Vinde, vamos nós a Gilgal, e renovemos ali o reino.'),
('acf','1sm',11,15,'E todo o povo partiu para Gilgal, onde proclamaram a Saul por rei perante o Senhor, e ofereceram ali ofertas pacíficas perante o Senhor; e Saul se alegrou muito ali com todos os homens de Israel.'),
('acf','1sm',12,1,'Então disse Samuel a todo o Israel: Eis que ouvi a vossa voz em tudo quanto me dissestes, e constituí sobre vós um rei.'),
('acf','1sm',12,2,'Agora, pois, eis que o rei vai adiante de vós. Eu já envelheci e encaneci, e eis que meus filhos estão convosco, e tenho andado diante de vós desde a minha mocidade até ao dia de hoje.'),
('acf','1sm',12,3,'Eis-me aqui; testificai contra mim perante o Senhor, e perante o seu ungido, a quem o boi tomei, a quem o jumento tomei, e a quem defraudei, a quem tenho oprimido, e de cuja mão tenho recebido suborno e com ele encobri os meus olhos, e vo-lo restituirei.'),
('acf','1sm',12,4,'Então disseram: Em nada nos defraudaste, nem nos oprimiste, nem recebeste coisa alguma da mão de ninguém.'),
('acf','1sm',12,5,'E ele lhes disse: O Senhor seja testemunha contra vós, e o seu ungido seja hoje testemunha, que nada tendes achado na minha mão. E disse o povo: Ele é testemunha.'),
('acf','1sm',12,6,'Então disse Samuel ao povo: O Senhor é o que escolheu a Moisés e a Arão, e tirou a vossos pais da terra do Egito.'),
('acf','1sm',12,7,'Agora, pois, ponde-vos aqui em pé, e pleitearei convosco perante o Senhor, sobre todos os atos de justiça do Senhor, que fez a vós e a vossos pais.'),
('acf','1sm',12,8,'Havendo entrado Jacó no Egito, vossos pais clamaram ao Senhor, e o Senhor enviou a Moisés e a Arão que tiraram a vossos pais do Egito, e os fizeram habitar neste lugar.'),
('acf','1sm',12,9,'Porém esqueceram-se do Senhor seu Deus; então os vendeu à mão de Sísera, capitão do exército de Hazor, e na mão dos filisteus, e na mão do rei dos moabitas, que pelejaram contra eles.'),
('acf','1sm',12,10,'E clamaram ao Senhor, e disseram: Pecamos, pois deixamos ao Senhor, e servimos aos baalins e astarotes; agora, pois, livra-nos da mão de nossos inimigos, e te serviremos.'),
('acf','1sm',12,11,'E o Senhor enviou a Jerubaal, e a Bedã, e a Jefté, e a Samuel; e livrou-vos da mão de vossos inimigos em redor, e habitastes seguros.'),
('acf','1sm',12,12,'E vendo vós que Naás, rei dos filhos de Amom, vinha contra vós, me dissestes: Não, mas reinará sobre nós um rei; sendo, porém, o Senhor vosso Deus, o vosso rei.'),
('acf','1sm',12,13,'Agora, pois, vedes aí o rei que elegestes e que pedistes; e eis que o Senhor tem posto sobre vós um rei.'),
('acf','1sm',12,14,'Se temerdes ao Senhor, e o servirdes, e derdes ouvidos à sua voz, e não fordes rebeldes ao mandado do Senhor, assim vós, como o rei que reina sobre vós, seguireis o Senhor vosso Deus.'),
('acf','1sm',12,15,'Mas se não derdes ouvidos à voz do Senhor, e antes fordes rebeldes ao mandado do Senhor, a mão do Senhor será contra vós, como o era contra vossos pais.'),
('acf','1sm',12,16,'Ponde-vos também agora aqui, e vede esta grande coisa que o Senhor vai fazer diante dos vossos olhos.'),
('acf','1sm',12,17,'Não é hoje a sega do trigo? Clamarei, pois, ao Senhor, e dará trovões e chuva; e sabereis e vereis que é grande a vossa maldade, que tendes feito perante o Senhor, pedindo para vós um rei.'),
('acf','1sm',12,18,'Então invocou Samuel ao Senhor, e o Senhor deu trovões e chuva naquele dia; por isso todo o povo temeu sobremaneira ao Senhor e a Samuel.'),
('acf','1sm',12,19,'E todo o povo disse a Samuel: Roga pelos teus servos ao Senhor teu Deus, para que não venhamos a morrer; porque a todos os nossos pecados temos acrescentado este mal, de pedirmos para nós um rei.'),
('acf','1sm',12,20,'Então disse Samuel ao povo: Não temais; vós tendes cometido todo este mal; porém não vos desvieis de seguir ao Senhor, mas servi ao Senhor com todo o vosso coração.'),
('acf','1sm',12,21,'E não vos desvieis; pois seguiríeis as vaidades, que nada aproveitam, e tampouco vos livrarão, porque vaidades são.'),
('acf','1sm',12,22,'Pois o Senhor, por causa do seu grande nome, não desamparará o seu povo; porque aprouve ao Senhor fazer-vos o seu povo.'),
('acf','1sm',12,23,'E quanto a mim, longe de mim que eu peque contra o Senhor, deixando de orar por vós; antes vos ensinarei o caminho bom e direito.'),
('acf','1sm',12,24,'Tão-somente temei ao Senhor, e servi-o fielmente com todo o vosso coração; porque vede quão grandiosas coisas vos fez.'),
('acf','1sm',12,25,'Porém, se perseverardes em fazer mal, perecereis, assim vós como o vosso rei.'),
('acf','1sm',13,1,'Saul reinou um ano; e no segundo ano do seu reinado sobre Israel,'),
('acf','1sm',13,2,'Saul escolheu para si três mil homens de Israel; e estavam com Saul dois mil em Micmás e na montanha de Betel, e mil estavam com Jônatas em Gibeá de Benjamim; e o resto do povo despediu, cada um para sua casa.'),
('acf','1sm',13,3,'E Jônatas feriu a guarnição dos filisteus, que estava em Gibeá, o que os filisteus ouviram; pelo que Saul tocou a trombeta por toda a terra, dizendo: Ouçam os hebreus.'),
('acf','1sm',13,4,'Então todo o Israel ouviu dizer: Saul feriu a guarnição dos filisteus, e também Israel se fez abominável aos filisteus. Então o povo foi convocado para junto de Saul em Gilgal.'),
('acf','1sm',13,5,'E os filisteus se ajuntaram para pelejar contra Israel, trinta mil carros, e seis mil cavaleiros, e povo em multidão como a areia que está à beira do mar; e subiram, e se acamparam em Micmás, ao oriente de Bete-Áven.'),
('acf','1sm',13,6,'Vendo, pois, os homens de Israel que estavam em apuros (porque o povo estava angustiado), o povo se escondeu pelas cavernas, e pelos espinhais, e pelos penhascos, e pelas fortificações, e pelas covas.'),
('acf','1sm',13,7,'E alguns dos hebreus passaram o Jordão para a terra de Gade e Gileade; e, estando Saul ainda em Gilgal, todo o povo ia atrás dele tremendo.'),
('acf','1sm',13,8,'E esperou Saul sete dias, até ao tempo que Samuel determinara; não vindo, porém, Samuel a Gilgal, o povo se dispersava dele.'),
('acf','1sm',13,9,'Então disse Saul: Trazei-me aqui um holocausto, e ofertas pacíficas. E ofereceu o holocausto.'),
('acf','1sm',13,10,'E sucedeu que, acabando ele de oferecer o holocausto, eis que Samuel chegou; e Saul lhe saiu ao encontro, para o saudar.'),
('acf','1sm',13,11,'Então disse Samuel: Que fizeste? Disse Saul: Porquanto via que o povo se espalhava de mim, e tu não vinhas nos dias aprazados, e os filisteus já se tinham ajuntado em Micmás,'),
('acf','1sm',13,12,'Eu disse: Agora descerão os filisteus sobre mim a Gilgal, e ainda à face do Senhor não orei; e constrangi-me, e ofereci holocausto.'),
('acf','1sm',13,13,'Então disse Samuel a Saul: Procedeste nesciamente, e não guardaste o mandamento que o Senhor teu Deus te ordenou; porque agora o Senhor teria confirmado o teu reino sobre Israel para sempre;'),
('acf','1sm',13,14,'Porém agora não subsistirá o teu reino; já tem buscado o Senhor para si um homem segundo o seu coração, e já lhe tem ordenado o Senhor, que seja capitão sobre o seu povo, porquanto não guardaste o que o Senhor te ordenou.'),
('acf','1sm',13,15,'Então se levantou Samuel, e subiu de Gilgal a Gibeá de Benjamim; e Saul contou o povo que se achava com ele, uns seiscentos homens.'),
('acf','1sm',13,16,'E Saul e Jônatas, seu filho, e o povo que se achou com eles, ficaram em Gibeá de Benjamim; porém os filisteus se acamparam em Micmás.'),
('acf','1sm',13,17,'E os saqueadores saíram do campo dos filisteus em três companhias; uma das companhias foi pelo caminho de Ofra à terra de Sual.'),
('acf','1sm',13,18,'Outra companhia seguiu pelo caminho de Bete-Horom, e a outra companhia foi pelo caminho do termo que dá para o vale Zeboim na direção do deserto.'),
('acf','1sm',13,19,'E em toda a terra de Israel nem um ferreiro se achava, porque os filisteus tinham dito: Para que os hebreus não façam espada nem lança.'),
('acf','1sm',13,20,'Por isso todo o Israel tinha que descer aos filisteus para amolar cada um a sua relha, e a sua enxada, e o seu machado, e o seu sacho.'),
('acf','1sm',13,21,'Tinham porém limas para os seus sachos, e para as suas enxadas, e para as forquilhas de três dentes, e para os machados, e para consertar as aguilhadas.'),
('acf','1sm',13,22,'E sucedeu que, no dia da peleja, não se achou nem espada nem lança na mão de todo o povo que estava com Saul e com Jônatas; porém acharam-se com Saul e com Jônatas seu filho.'),
('acf','1sm',13,23,'E saiu a guarnição dos filisteus ao desfiladeiro de Micmás.'),
('acf','1sm',14,1,'Sucedeu, pois, que um dia disse Jônatas, filho de Saul, ao moço que lhe levava as armas: Vem, passemos à guarnição dos filisteus, que está lá daquele lado. Porém não o fez saber a seu pai.'),
('acf','1sm',14,2,'E estava Saul à extremidade de Gibeá, debaixo da romeira que havia em Migrom; e o povo que estava com ele era uns seiscentos homens.'),
('acf','1sm',14,3,'E Aías, filho de Aitube, irmão de Icabode, o filho de Finéias, filho de Eli, sacerdote do Senhor em Siló, trazia o éfode; porém o povo não sabia que Jônatas tinha ido.'),
('acf','1sm',14,4,'E entre os desfiladeiros pelos quais Jônatas procurava passar à guarnição dos filisteus, deste lado havia uma penha aguda, e do outro lado uma penha aguda; e era o nome de uma Bozez, e o nome da outra Sené.'),
('acf','1sm',14,5,'Uma penha para o norte estava defronte de Micmás, e a outra para o sul, defronte de Gibeá.'),
('acf','1sm',14,6,'Disse, pois, Jônatas ao moço que lhe levava as armas: Vem, passemos à guarnição destes incircuncisos; porventura operará o Senhor por nós, porque para com o Senhor nenhum impedimento há de livrar com muitos ou com poucos.'),
('acf','1sm',14,7,'Então o seu pajem de armas lhe disse: Faze tudo o que tens no coração; segue, eis-me aqui contigo, conforme o que quiseres.'),
('acf','1sm',14,8,'Disse, pois, Jônatas: Eis que passaremos àqueles homens, e nos revelaremos a eles.'),
('acf','1sm',14,9,'Se nos disserem assim: Parai até que cheguemos a vós; então ficaremos no nosso lugar, e não subiremos a eles.'),
('acf','1sm',14,10,'Porém, se disserem: Subi a nós; então subiremos, pois o Senhor os tem entregado nas nossas mãos, e isto nos será por sinal.'),
('acf','1sm',14,11,'Revelando-se eles à guarnição dos filisteus, disseram os filisteus: Eis que já os hebreus saíram das cavernas em que se tinham escondido.'),
('acf','1sm',14,12,'E os homens da guarnição responderam a Jônatas e ao seu pajem de armas, e disseram: Subi a nós, e nós vos ensinaremos uma lição. E disse Jônatas ao seu pajem de armas: Sobe atrás de mim, porque o Senhor os tem entregado na mão de Israel.'),
('acf','1sm',14,13,'Então subiu Jônatas com os pés e com as mãos, e o seu pajem de armas atrás dele; e os filisteus caíam diante de Jônatas, e o seu pajem de armas os matava atrás dele.'),
('acf','1sm',14,14,'E sucedeu esta primeira derrota, em que Jônatas e o seu pajem de armas feriram uns vinte homens, em cerca de meia jeira de terra que uma junta de bois podia lavrar.'),
('acf','1sm',14,15,'E houve tremor no arraial, no campo e em todo o povo; também a mesma guarnição e os saqueadores tremeram, até a terra se estremeceu porquanto era tremor de Deus.'),
('acf','1sm',14,16,'Olharam, pois, as sentinelas de Saul em Gibeá de Benjamim, e eis que a multidão se dissolvia, e fugia para cá e para lá.'),
('acf','1sm',14,17,'Disse então Saul ao povo que estava com ele: Ora contai, e vede quem é que saiu dentre nós. E contaram, e eis que nem Jônatas nem o seu pajem de armas estavam ali.'),
('acf','1sm',14,18,'Então Saul disse a Aías: Traze aqui a arca de Deus (porque naquele dia estava a arca de Deus com os filhos de Israel).'),
('acf','1sm',14,19,'E sucedeu que, estando Saul ainda falando com o sacerdote, o alvoroço que havia no arraial dos filisteus ia crescendo muito, e se multiplicava, pelo que disse Saul ao sacerdote: Retira a tua mão.'),
('acf','1sm',14,20,'Então Saul e todo o povo que havia com ele se reuniram, e foram à peleja; e eis que a espada de um era contra o outro, e houve mui grande tumulto.'),
('acf','1sm',14,21,'Também com os filisteus havia hebreus, como dantes, que subiram com eles ao arraial em redor; e também estes se ajuntaram com os israelitas que estavam com Saul e Jônatas.'),
('acf','1sm',14,22,'Ouvindo, pois, todos os homens de Israel que se esconderam pela montanha de Efraim que os filisteus fugiam, eles também os perseguiram de perto na peleja.'),
('acf','1sm',14,23,'Assim livrou o Senhor a Israel naquele dia; e o arraial passou a Bete-Áven.'),
('acf','1sm',14,24,'E estavam os homens de Israel já exaustos naquele dia, porquanto Saul conjurou o povo, dizendo: Maldito o homem que comer pão até à tarde, antes que me vingue de meus inimigos. Por isso todo o povo se absteve de provar pão.'),
('acf','1sm',14,25,'E todo o povo chegou a um bosque; e havia mel na superfície do campo.'),
('acf','1sm',14,26,'E, chegando o povo ao bosque, eis que havia um manancial de mel; porém ninguém chegou a mão à boca, porque o povo temia a conjuração.'),
('acf','1sm',14,27,'Porém Jônatas não tinha ouvido quando seu pai conjurara o povo, e estendeu a ponta da vara que tinha na mão, e a molhou no favo de mel; e, tornando a mão à boca, aclararam-se os seus olhos.'),
('acf','1sm',14,28,'Então respondeu um do povo, e disse: Solenemente conjurou teu pai o povo, dizendo: Maldito o homem que comer hoje pão. Por isso o povo desfalecia.'),
('acf','1sm',14,29,'Então disse Jônatas: Meu pai tem turbado a terra; ora vede como se me aclararam os olhos por ter provado um pouco deste mel,'),
('acf','1sm',14,30,'Quanto mais se o povo hoje livremente tivesse comido do despojo que achou de seus inimigos. Porém agora não foi tão grande o estrago dos filisteus.'),
('acf','1sm',14,31,'Feriram, porém, aquele dia aos filisteus, desde Micmás até Aijalom, e o povo desfaleceu em extremo.'),
('acf','1sm',14,32,'Então o povo se lançou ao despojo, e tomaram ovelhas, e vacas, e bezerros, e os degolaram no chão; e o povo os comeu com sangue.'),
('acf','1sm',14,33,'E o anunciaram a Saul, dizendo: Eis que o povo peca contra o Senhor, comendo com sangue. E disse: Aleivosamente procedestes; trazei-me aqui já uma grande pedra.'),
('acf','1sm',14,34,'Disse mais Saul: Dispersai-vos entre o povo, e dizei-lhes: Trazei-me cada um o seu boi, e cada um a sua ovelha, e degolai-os aqui, e comei, e não pequeis contra o Senhor, comendo com sangue. Então todo o povo trouxe de noite, cada um pela sua mão, o seu boi, e os degolaram ali.'),
('acf','1sm',14,35,'Então edificou Saul um altar ao Senhor; este foi o primeiro altar que edificou ao Senhor.'),
('acf','1sm',14,36,'Depois disse Saul: Desçamos de noite atrás dos filisteus, e despojemo-los, até que amanheça o dia, e não deixemos deles um só homem. E disseram: Tudo o que parecer bem aos teus olhos faze. Disse, porém, o sacerdote: Cheguemo-nos aqui a Deus.'),
('acf','1sm',14,37,'Então consultou Saul a Deus, dizendo: Descerei atrás dos filisteus? Entregá-los-ás na mão de Israel? Porém aquele dia não lhe respondeu.'),
('acf','1sm',14,38,'Então disse Saul: Chegai-vos para cá, todos os chefes do povo, e informai-vos, e vede em que se cometeu hoje este pecado.'),
('acf','1sm',14,39,'Porque vive o Senhor que salva a Israel, que, ainda que seja em meu filho Jônatas, certamente morrerá. E nenhum de todo o povo lhe respondeu.'),
('acf','1sm',14,40,'Disse mais a todo o Israel: Vós estareis de um lado, e eu e meu filho Jônatas estaremos do outro lado. Então disse o povo a Saul: Faze o que parecer bem aos teus olhos.'),
('acf','1sm',14,41,'Falou, pois, Saul ao Senhor Deus de Israel: Mostra o inocente. Então Jônatas e Saul foram tomados por sorte, e o povo saiu livre.'),
('acf','1sm',14,42,'Então disse Saul: Lançai a sorte entre mim e Jônatas, meu filho. E foi tomado Jônatas.'),
('acf','1sm',14,43,'Disse então Saul a Jônatas: Declara-me o que tens feito. E Jônatas lho declarou, e disse: Tão-somente provei um pouco de mel com a ponta da vara que tinha na mão; eis que devo morrer?'),
('acf','1sm',14,44,'Então disse Saul: Assim me faça Deus, e outro tanto, que com certeza morrerás, Jônatas.'),
('acf','1sm',14,45,'Porém o povo disse a Saul: Morrerá Jônatas, que efetuou tão grande salvação em Israel? Nunca tal suceda; vive o Senhor, que não lhe há de cair no chão um só cabelo da sua cabeça! pois com Deus fez isso hoje. Assim o povo livrou a Jônatas, para que não morresse.'),
('acf','1sm',14,46,'E Saul deixou de seguir os filisteus; e os filisteus se foram ao seu lugar.'),
('acf','1sm',14,47,'Então tomou Saul o reino sobre Israel; e pelejou contra todos os seus inimigos em redor; contra Moabe, e contra os filhos de Amom, e contra Edom, e contra os reis de Zobá, e contra os filisteus, e para onde quer que se tornava executava castigo.'),
('acf','1sm',14,48,'E houve-se valorosamente, e feriu aos amalequitas, e liberou a Israel da mão dos que o saqueavam.'),
('acf','1sm',14,49,'E os filhos de Saul eram Jônatas, e Isvi, e Malquisua; e os nomes de suas duas filhas eram estes: o da mais velha Merabe, e o da mais nova, Mical.'),
('acf','1sm',14,50,'E o nome da mulher de Saul, Ainoã, filha de Aimaás; e o nome do capitão do exército, Abner, filho de Ner, tio de Saul.'),
('acf','1sm',14,51,'E Quis, pai de Saul, e Ner, pai de Abner, eram filhos de Abiel.'),
('acf','1sm',14,52,'E houve uma forte guerra contra os filisteus, todos os dias de Saul; por isso Saul a todos os homens valentes e valorosos que via, os agregava a si.'),
('acf','1sm',15,1,'Então disse Samuel a Saul: Enviou-me o SENHOR a ungir-te rei sobre o seu povo, sobre Israel; ouve, pois, agora a voz das palavras do SENHOR.'),
('acf','1sm',15,2,'Assim diz o Senhor dos Exércitos: Eu me recordei do que fez Amaleque a Israel; como se lhe opôs no caminho, quando subia do Egito.'),
('acf','1sm',15,3,'Vai, pois, agora e fere a Amaleque; e destrói totalmente a tudo o que tiver, e não lhe perdoes; porém matarás desde o homem até à mulher, desde os meninos até aos de peito, desde os bois até às ovelhas, e desde os camelos até aos jumentos.'),
('acf','1sm',15,4,'O que Saul convocou ao povo, e os contou em Telaim, duzentos mil homens de pé, e dez mil homens de Judá.'),
('acf','1sm',15,5,'Chegando, pois, Saul à cidade de Amaleque, pôs emboscada no vale.'),
('acf','1sm',15,6,'E disse Saul aos queneus: Ide-vos, retirai-vos e saí do meio dos amalequitas, para que não vos destrua juntamente com eles, porque vós usastes de misericórdia com todos os filhos de Israel, quando subiram do Egito. Assim os queneus se retiraram do meio dos amalequitas.'),
('acf','1sm',15,7,'Então feriu Saul aos amalequitas desde Havilá até chegar a Sur, que está defronte do Egito.'),
('acf','1sm',15,8,'E tomou vivo a Agague, rei dos amalequitas; porém a todo o povo destruiu ao fio da espada.'),
('acf','1sm',15,9,'E Saul e o povo pouparam a Agague, e ao melhor das ovelhas e das vacas, e as da segunda ordem, e aos cordeiros e ao melhor que havia, e não os quiseram destruir totalmente; porém a toda a coisa vil e desprezível destruíram totalmente.'),
('acf','1sm',15,10,'Então veio a palavra do Senhor a Samuel, dizendo:'),
('acf','1sm',15,11,'Arrependo-me de haver posto a Saul como rei; porquanto deixou de me seguir, e não cumpriu as minhas palavras. Então Samuel se contristou, e toda a noite clamou ao Senhor.'),
('acf','1sm',15,12,'E madrugou Samuel para encontrar a Saul pela manhã: e anunciou-se a Samuel, dizendo: Já chegou Saul ao Carmelo, e eis que levantou para si uma coluna. Então voltando, passou e desceu a Gilgal.'),
('acf','1sm',15,13,'Veio, pois, Samuel a Saul; e Saul lhe disse: Bendito sejas tu do Senhor; cumpri a palavra do Senhor.'),
('acf','1sm',15,14,'Então disse Samuel: Que balido, pois, de ovelhas é este aos meus ouvidos, e o mugido de vacas que ouço?'),
('acf','1sm',15,15,'E disse Saul: De Amaleque as trouxeram; porque o povo poupou ao melhor das ovelhas, e das vacas, para as oferecer ao Senhor teu Deus; o resto, porém, temos destruído totalmente.'),
('acf','1sm',15,16,'Então disse Samuel a Saul: Espera, e te declararei o que o Senhor me disse esta noite. E ele disse-lhe: Fala.'),
('acf','1sm',15,17,'E disse Samuel: Porventura, sendo tu pequeno aos teus olhos, não foste por cabeça das tribos de Israel? E o Senhor te ungiu rei sobre Israel.'),
('acf','1sm',15,18,'E enviou-te o Senhor a este caminho, e disse: Vai, e destrói totalmente a estes pecadores, os amalequitas, e peleja contra eles, até que os aniquiles.'),
('acf','1sm',15,19,'Por que, pois, não deste ouvidos à voz do Senhor, antes te lançaste ao despojo, e fizeste o que parecia mau aos olhos do Senhor?'),
('acf','1sm',15,20,'Então disse Saul a Samuel: Antes dei ouvidos à voz do Senhor, e caminhei no caminho pelo qual o Senhor me enviou; e trouxe a Agague, rei de Amaleque, e os amalequitas destruí totalmente;'),
('acf','1sm',15,21,'Mas o povo tomou do despojo ovelhas e vacas, o melhor do interdito, para oferecer ao Senhor teu Deus em Gilgal.'),
('acf','1sm',15,22,'Porém Samuel disse: Tem porventura o Senhor tanto prazer em holocaustos e sacrifícios, como em que se obedeça à palavra do Senhor? Eis que o obedecer é melhor do que o sacrificar; e o atender melhor é do que a gordura de carneiros.'),
('acf','1sm',15,23,'Porque a rebelião é como o pecado de feitiçaria, e o porfiar é como iniqüidade e idolatria. Porquanto tu rejeitaste a palavra do Senhor, ele também te rejeitou a ti, para que não sejas rei.'),
('acf','1sm',15,24,'Então disse Saul a Samuel: Pequei, porquanto tenho transgredido a ordem do Senhor e as tuas palavras; porque temi ao povo, e dei ouvidos à sua voz.'),
('acf','1sm',15,25,'Agora, pois, rogo-te perdoa o meu pecado; e volta comigo, para que adore ao Senhor.'),
('acf','1sm',15,26,'Porém Samuel disse a Saul: Não voltarei contigo; porquanto rejeitaste a palavra do Senhor, já te rejeitou o Senhor, para que não sejas rei sobre Israel.'),
('acf','1sm',15,27,'E virando-se Samuel para se ir, ele lhe pegou pela orla da capa, e a rasgou.'),
('acf','1sm',15,28,'Então Samuel lhe disse: O Senhor tem rasgado de ti hoje o reino de Israel, e o tem dado ao teu próximo, melhor do que tu.'),
('acf','1sm',15,29,'E também aquele que é a Força de Israel não mente nem se arrepende; porquanto não é um homem para que se arrependa.'),
('acf','1sm',15,30,'Disse ele então: Pequei; honra-me, porém, agora diante dos anciãos do meu povo, e diante de Israel; e volta comigo, para que adore ao Senhor teu Deus.'),
('acf','1sm',15,31,'Então, voltando Samuel, seguiu a Saul; e Saul adorou ao Senhor.'),
('acf','1sm',15,32,'Então disse Samuel: Trazei-me aqui a Agague, rei dos amalequitas. E Agague veio a ele animosamente; e disse Agague: Na verdade já passou a amargura da morte.'),
('acf','1sm',15,33,'Disse, porém, Samuel: Assim como a tua espada desfilhou as mulheres, assim ficará desfilhada a tua mãe entre as mulheres. Então Samuel despedaçou a Agague perante o Senhor em Gilgal.'),
('acf','1sm',15,34,'Então Samuel se foi a Ramá; e Saul subiu à sua casa, a Gibeá de Saul.'),
('acf','1sm',15,35,'E nunca mais viu Samuel a Saul até ao dia da sua morte; porque Samuel teve dó de Saul. E o Senhor se arrependeu de haver posto a Saul rei sobre Israel.'),
('acf','1sm',16,1,'Então disse o SENHOR a Samuel: Até quando terás dó de Saul, havendo-o eu rejeitado, para que não reine sobre Israel? Enche um chifre de azeite, e vem, enviar-te-ei a Jessé o belemita; porque dentre os seus filhos me tenho provido de um rei.'),
('acf','1sm',16,2,'Porém disse Samuel: Como irei eu? pois, ouvindo-o Saul, me matará. Então disse o Senhor: Toma uma bezerra das vacas em tuas mãos, e dize: Vim para sacrificar ao Senhor.'),
('acf','1sm',16,3,'E convidarás a Jessé ao sacrifício; e eu te farei saber o que hás de fazer, e ungir-me-ás a quem eu te disser.'),
('acf','1sm',16,4,'Fez, pois, Samuel o que dissera o Senhor, e veio a Belém; então os anciãos da cidade saíram ao encontro, tremendo, e disseram: De paz é a tua vinda?'),
('acf','1sm',16,5,'E disse ele: É de paz, vim sacrificar ao Senhor; santificai-vos, e vinde comigo ao sacrifício. E santificou ele a Jessé e a seus filhos, e os convidou ao sacrifício.'),
('acf','1sm',16,6,'E sucedeu que, entrando eles, viu a Eliabe, e disse: Certamente está perante o Senhor o seu ungido.'),
('acf','1sm',16,7,'Porém o Senhor disse a Samuel: Não atentes para a sua aparência, nem para a grandeza da sua estatura, porque o tenho rejeitado; porque o Senhor não vê como vê o homem, pois o homem vê o que está diante dos olhos, porém o Senhor olha para o coração.'),
('acf','1sm',16,8,'Então chamou Jessé a Abinadabe, e o fez passar diante de Samuel, o qual disse: Nem a este tem escolhido o Senhor.'),
('acf','1sm',16,9,'Então Jessé fez passar a Sama; porém disse: Tampouco a este tem escolhido o Senhor.'),
('acf','1sm',16,10,'Assim fez passar Jessé a seus sete filhos diante de Samuel; porém Samuel disse a Jessé: O Senhor não tem escolhido a estes.'),
('acf','1sm',16,11,'Disse mais Samuel a Jessé: Acabaram-se os moços? E disse: Ainda falta o menor, que está apascentando as ovelhas. Disse, pois, Samuel a Jessé: Manda chamá-lo, porquanto não nos assentaremos até que ele venha aqui.'),
('acf','1sm',16,12,'Então mandou chamá-lo e fê-lo entrar (e era ruivo e formoso de semblante e de boa presença); e disse o Senhor: Levanta-te, e unge-o, porque é este mesmo.'),
('acf','1sm',16,13,'Então Samuel tomou o chifre do azeite, e ungiu-o no meio de seus irmãos; e desde aquele dia em diante o Espírito do Senhor se apoderou de Davi; então Samuel se levantou, e voltou a Ramá.'),
('acf','1sm',16,14,'E o Espírito do Senhor se retirou de Saul, e atormentava-o um espírito mau da parte do Senhor.'),
('acf','1sm',16,15,'Então os criados de Saul lhe disseram: Eis que agora o espírito mau da parte de Deus te atormenta;'),
('acf','1sm',16,16,'Diga, pois, nosso senhor a seus servos, que estão na tua presença, que busquem um homem que saiba tocar harpa, e será que, quando o espírito mau da parte de Deus vier sobre ti, então ele tocará com a sua mão, e te acharás melhor.'),
('acf','1sm',16,17,'Então disse Saul aos seus servos: Buscai-me, pois, um homem que toque bem, e trazei-mo.'),
('acf','1sm',16,18,'Então respondeu um dos moços, e disse: Eis que tenho visto a um filho de Jessé, o belemita, que sabe tocar e é valente e vigoroso, e homem de guerra, e prudente em palavras, e de gentil presença; o Senhor é com ele.'),
('acf','1sm',16,19,'E Saul enviou mensageiros a Jessé, dizendo: Envia-me Davi, teu filho, o que está com as ovelhas.'),
('acf','1sm',16,20,'Então tomou Jessé um jumento carregado de pão, e um odre de vinho, e um cabrito, e enviou-os a Saul pela mão de Davi, seu filho.'),
('acf','1sm',16,21,'Assim Davi veio a Saul, e esteve perante ele, e o amou muito, e foi seu pajem de armas.'),
('acf','1sm',16,22,'Então Saul mandou dizer a Jessé: Deixa estar a Davi perante mim, pois achou graça em meus olhos.'),
('acf','1sm',16,23,'E sucedia que, quando o espírito mau da parte de Deus vinha sobre Saul, Davi tomava a harpa, e a tocava com a sua mão; então Saul sentia alívio, e se achava melhor, e o espírito mau se retirava dele.'),
('acf','1sm',17,1,'E os filisteus ajuntaram as suas forças para a guerra e congregaram-se em Socó, que está em Judá, e acamparam-se entre Socó e Azeca, no termo de Damim.'),
('acf','1sm',17,2,'Porém Saul e os homens de Israel se ajuntaram e acamparam no vale do carvalho, e ordenaram a batalha contra os filisteus.'),
('acf','1sm',17,3,'E os filisteus estavam num monte de um lado, e os israelitas estavam num monte do outro lado; e o vale estava entre eles.'),
('acf','1sm',17,4,'Então saiu do arraial dos filisteus um homem guerreiro, cujo nome era Golias, de Gate, que tinha de altura seis côvados e um palmo.'),
('acf','1sm',17,5,'Trazia na cabeça um capacete de bronze, e vestia uma couraça de escamas; e era o peso da couraça de cinco mil siclos de bronze.'),
('acf','1sm',17,6,'E trazia grevas de bronze por cima de seus pés, e um escudo de bronze entre os seus ombros.'),
('acf','1sm',17,7,'E a haste da sua lança era como o eixo do tecelão, e a ponta da sua lança de seiscentos siclos de ferro, e diante dele ia o escudeiro.'),
('acf','1sm',17,8,'E parou, e clamou às companhias de Israel, e disse-lhes: Para que saireis a ordenar a batalha? Não sou eu filisteu e vós servos de Saul? Escolhei dentre vós um homem que desça a mim.'),
('acf','1sm',17,9,'Se ele puder pelejar comigo, e me ferir, a vós seremos por servos; porém, se eu o vencer, e o ferir, então a nós sereis por servos, e nos servireis.'),
('acf','1sm',17,10,'Disse mais o filisteu: Hoje desafio as companhias de Israel, dizendo: Dai-me um homem, para que ambos pelejemos.'),
('acf','1sm',17,11,'Ouvindo então Saul e todo o Israel estas palavras do filisteu, espantaram-se, e temeram muito.'),
('acf','1sm',17,12,'E Davi era filho de um homem efrateu, de Belém de Judá, cujo nome era Jessé, que tinha oito filhos; e nos dias de Saul era este homem já velho e adiantado em idade entre os homens.'),
('acf','1sm',17,13,'Foram-se os três filhos mais velhos de Jessé, e seguiram a Saul à guerra; e eram os nomes de seus três filhos, que se foram à guerra, Eliabe, o primogênito, e o segundo Abinadabe, e o terceiro Sama.'),
('acf','1sm',17,14,'E Davi era o menor; e os três maiores seguiram a Saul.'),
('acf','1sm',17,15,'Davi, porém, ia e voltava de Saul, para apascentar as ovelhas de seu pai em Belém.'),
('acf','1sm',17,16,'Chegava-se, pois, o filisteu pela manhã e à tarde; e apresentou-se por quarenta dias.'),
('acf','1sm',17,17,'E disse Jessé a Davi, seu filho: Toma, peço-te, para teus irmãos um efa deste grão tostado e estes dez pães, e corre a levá-los ao arraial, a teus irmãos.'),
('acf','1sm',17,18,'Porém estes dez queijos de leite leva ao capitão de mil; e visitarás a teus irmãos, a ver se vão bem; e tomarás o seu penhor.'),
('acf','1sm',17,19,'E estavam Saul, e eles, e todos os homens de Israel no vale do carvalho, pelejando com os filisteus.'),
('acf','1sm',17,20,'Davi então se levantou de madrugada, pela manhã, e deixou as ovelhas com um guarda, e carregou-se, e partiu, como Jessé lhe ordenara; e chegou ao lugar dos carros, quando já o exército saía em ordem de batalha, e a gritos chamavam à peleja.'),
('acf','1sm',17,21,'E os israelitas e filisteus se puseram em ordem, fileira contra fileira.'),
('acf','1sm',17,22,'E Davi deixou a carga que trouxera na mão do guarda da bagagem, e correu à batalha; e, chegando, perguntou a seus irmãos se estavam bem.'),
('acf','1sm',17,23,'E, estando ele ainda falando com eles, eis que vinha subindo do exército dos filisteus o homem guerreiro, cujo nome era Golias, o filisteu de Gate; e falou conforme àquelas palavras, e Davi as ouviu.'),
('acf','1sm',17,24,'Porém todos os homens em Israel, vendo aquele homem, fugiram de diante dele, e temiam grandemente.'),
('acf','1sm',17,25,'E diziam os homens de Israel: Vistes aquele homem que subiu? Pois subiu para afrontar a Israel; há de ser, pois, que, o homem que o ferir, o rei o enriquecerá de grandes riquezas, e lhe dará a sua filha, e fará livre a casa de seu pai em Israel.'),
('acf','1sm',17,26,'Então falou Davi aos homens que estavam com ele, dizendo: Que farão àquele homem, que ferir a este filisteu, e tirar a afronta de sobre Israel? Quem é, pois, este incircunciso filisteu, para afrontar os exércitos do Deus vivo?'),
('acf','1sm',17,27,'E o povo lhe tornou a falar conforme àquela palavra dizendo: Assim farão ao homem que o ferir.'),
('acf','1sm',17,28,'E, ouvindo Eliabe, seu irmão mais velho, falar àqueles homens, acendeu-se a ira de Eliabe contra Davi, e disse: Por que desceste aqui? Com quem deixaste aquelas poucas ovelhas no deserto? Bem conheço a tua presunção, e a maldade do teu coração, que desceste para ver a peleja.'),
('acf','1sm',17,29,'Então disse Davi: Que fiz eu agora? Porventura não há razão para isso?'),
('acf','1sm',17,30,'E desviou-se dele para outro, e falou conforme àquela palavra; e o povo lhe tornou a responder conforme às primeiras palavras.'),
('acf','1sm',17,31,'E, ouvidas as palavras que Davi havia falado, as anunciaram a Saul, que mandou chamá-lo.'),
('acf','1sm',17,32,'E Davi disse a Saul: Não desfaleça o coração de ninguém por causa dele; teu servo irá, e pelejará contra este filisteu.'),
('acf','1sm',17,33,'Porém Saul disse a Davi: Contra este filisteu não poderás ir para pelejar com ele; pois tu ainda és moço, e ele homem de guerra desde a sua mocidade.'),
('acf','1sm',17,34,'Então disse Davi a Saul: Teu servo apascentava as ovelhas de seu pai; e quando vinha um leão e um urso, e tomava uma ovelha do rebanho,'),
('acf','1sm',17,35,'Eu saía após ele e o feria, e livrava-a da sua boca; e, quando ele se levantava contra mim, lançava-lhe mão da barba, e o feria e o matava.'),
('acf','1sm',17,36,'Assim feria o teu servo o leão, como o urso; assim será este incircunciso filisteu como um deles; porquanto afrontou os exércitos do Deus vivo.'),
('acf','1sm',17,37,'Disse mais Davi: O Senhor me livrou das garras do leão, e das do urso; ele me livrará da mão deste filisteu. Então disse Saul a Davi: Vai, e o Senhor seja contigo.'),
('acf','1sm',17,38,'E Saul vestiu a Davi de suas vestes, e pôs-lhe sobre a cabeça um capacete de bronze; e o vestiu de uma couraça.'),
('acf','1sm',17,39,'E Davi cingiu a espada sobre as suas vestes, e começou a andar; porém nunca o havia experimentado; então disse Davi a Saul: Não posso andar com isto, pois nunca o experimentei. E Davi tirou aquilo de sobre si.'),
('acf','1sm',17,40,'E tomou o seu cajado na mão, e escolheu para si cinco seixos do ribeiro, e pô-los no alforje de pastor, que trazia, a saber, no surrão, e lançou mão da sua funda; e foi aproximando-se do filisteu.'),
('acf','1sm',17,41,'O filisteu também vinha se aproximando de Davi; e o que lhe levava o escudo ia adiante dele.'),
('acf','1sm',17,42,'E, olhando o filisteu, e vendo a Davi, o desprezou, porquanto era moço, ruivo, e de gentil aspecto.'),
('acf','1sm',17,43,'Disse, pois, o filisteu a Davi: Sou eu algum cão, para tu vires a mim com paus? E o filisteu pelos seus deuses amaldiçoou a Davi.'),
('acf','1sm',17,44,'Disse mais o filisteu a Davi: Vem a mim, e darei a tua carne às aves do céu e às bestas do campo.'),
('acf','1sm',17,45,'Davi, porém, disse ao filisteu: Tu vens a mim com espada, e com lança, e com escudo; porém eu venho a ti em nome do Senhor dos Exércitos, o Deus dos exércitos de Israel, a quem tens afrontado.'),
('acf','1sm',17,46,'Hoje mesmo o Senhor te entregará na minha mão, e ferir-te-ei, e tirar-te-ei a cabeça, e os corpos do arraial dos filisteus darei hoje mesmo às aves do céu e às feras da terra; e toda a terra saberá que há Deus em Israel;'),
('acf','1sm',17,47,'E saberá toda esta congregação que o Senhor salva, não com espada, nem com lança; porque do Senhor é a guerra, e ele vos entregará na nossa mão.'),
('acf','1sm',17,48,'E sucedeu que, levantando-se o filisteu, e indo encontrar-se com Davi, apressou-se Davi, e correu ao combate, a encontrar-se com o filisteu.'),
('acf','1sm',17,49,'E Davi pôs a mão no alforje, e tomou dali uma pedra e com a funda lha atirou, e feriu o filisteu na testa, e a pedra se lhe encravou na testa, e caiu sobre o seu rosto em terra.'),
('acf','1sm',17,50,'Assim Davi prevaleceu contra o filisteu, com uma funda e com uma pedra, e feriu o filisteu, e o matou; sem que Davi tivesse uma espada na mão.'),
('acf','1sm',17,51,'Por isso correu Davi, e pôs-se em pé sobre o filisteu, e tomou a sua espada, e tirou-a da bainha, e o matou, e lhe cortou com ela a cabeça; vendo então os filisteus, que o seu herói era morto, fugiram.'),
('acf','1sm',17,52,'Então os homens de Israel e Judá se levantaram, e jubilaram, e seguiram os filisteus, até chegar ao vale, e até às portas de Ecrom; e caíram os feridos dos filisteus pelo caminho de Saaraim até Gate e até Ecrom.'),
('acf','1sm',17,53,'Então voltaram os filhos de Israel de perseguirem os filisteus, e despojaram os seus arraiais.'),
('acf','1sm',17,54,'E Davi tomou a cabeça do filisteu, e a trouxe a Jerusalém; porém pôs as armas dele na sua tenda.'),
('acf','1sm',17,55,'Vendo, porém, Saul, sair Davi a encontrar-se com o filisteu, disse a Abner, o capitão do exército: De quem é filho este moço, Abner? E disse Abner: Vive a tua alma, ó rei, que o não sei.'),
('acf','1sm',17,56,'Disse então o rei: Pergunta, pois, de quem é filho este moço.'),
('acf','1sm',17,57,'Voltando, pois, Davi de ferir o filisteu, Abner o tomou consigo, e o trouxe à presença de Saul, trazendo ele na mão a cabeça do filisteu.'),
('acf','1sm',17,58,'E disse-lhe Saul: De quem és filho, jovem? E disse Davi: Filho de teu servo Jessé, belemita.'),
('acf','1sm',18,1,'E sucedeu que, acabando ele de falar com Saul, a alma de Jônatas se ligou com a alma de Davi; e Jônatas o amou, como à sua própria alma.'),
('acf','1sm',18,2,'E Saul naquele dia o tomou, e não lhe permitiu que voltasse para casa de seu pai.'),
('acf','1sm',18,3,'E Jônatas e Davi fizeram aliança; porque Jônatas o amava como à sua própria alma.'),
('acf','1sm',18,4,'E Jônatas se despojou da capa que trazia sobre si, e a deu a Davi, como também as suas vestes, até a sua espada, e o seu arco, e o seu cinto.'),
('acf','1sm',18,5,'E saía Davi aonde quer que Saul o enviasse e conduzia-se com prudência, e Saul o pôs sobre os homens de guerra; e era aceito aos olhos de todo o povo, e até aos olhos dos servos de Saul.'),
('acf','1sm',18,6,'Sucedeu, porém, que, vindo eles, quando Davi voltava de ferir os filisteus, as mulheres de todas as cidades de Israel saíram ao encontro do rei Saul, cantando e dançando, com adufes, com alegria, e com instrumentos de música.'),
('acf','1sm',18,7,'E as mulheres dançando e cantando se respondiam umas às outras, dizendo: Saul feriu os seus milhares, porém, Davi os seus dez milhares.'),
('acf','1sm',18,8,'Então Saul se indignou muito, e aquela palavra pareceu mal aos seus olhos, e disse: Dez milhares deram a Davi, e a mim somente milhares; na verdade, que lhe falta, senão só o reino?'),
('acf','1sm',18,9,'E, desde aquele dia em diante, Saul tinha Davi em suspeita.'),
('acf','1sm',18,10,'E aconteceu no outro dia, que o mau espírito da parte de Deus se apoderou de Saul, e profetizava no meio da casa; e Davi tocava a harpa com a sua mão, como nos outros dias; Saul, porém, tinha na mão uma lança.'),
('acf','1sm',18,11,'E Saul atirou com a lança, dizendo: Encravarei a Davi na parede. Porém Davi se desviou dele por duas vezes.'),
('acf','1sm',18,12,'E temia Saul a Davi, porque o Senhor era com ele e se tinha retirado de Saul.'),
('acf','1sm',18,13,'Por isso Saul o desviou de si, e o pôs por capitão de mil; e saía e entrava diante do povo.'),
('acf','1sm',18,14,'E Davi se conduzia com prudência em todos os seus caminhos, e o Senhor era com ele.'),
('acf','1sm',18,15,'Vendo então Saul que tão prudentemente se conduzia, tinha receio dele.'),
('acf','1sm',18,16,'Porém todo o Israel e Judá amava a Davi, porquanto saía e entrava diante deles.'),
('acf','1sm',18,17,'Por isso Saul disse a Davi: Eis que Merabe, minha filha mais velha, te darei por mulher; sê-me somente filho valoroso, e guerreia as guerras do Senhor (porque Saul dizia consigo: Não seja contra ele a minha mão, mas sim a dos filisteus).'),
('acf','1sm',18,18,'Mas Davi disse a Saul: Quem sou eu, e qual é a minha vida e a família de meu pai em Israel, para vir a ser genro do rei?'),
('acf','1sm',18,19,'Sucedeu, porém, que ao tempo que Merabe, filha de Saul, devia ser dada a Davi, ela foi dada por mulher a Adriel, meolatita.'),
('acf','1sm',18,20,'Mas Mical, a outra filha de Saul amava a Davi; o que, sendo anunciado a Saul, pareceu isto bom aos seus olhos.'),
('acf','1sm',18,21,'E Saul disse: Eu lha darei, para que lhe sirva de laço, e para que a mão dos filisteus venha a ser contra ele. Pelo que Saul disse a Davi: Com a outra serás hoje meu genro.'),
('acf','1sm',18,22,'E Saul deu ordem aos seus servos: Falai em segredo a Davi, dizendo: Eis que o rei te está mui afeiçoado, e todos os seus servos te amam; agora, pois, consente em ser genro do rei.'),
('acf','1sm',18,23,'E os servos de Saul falaram todas estas palavras aos ouvidos de Davi. Então disse Davi: Parece-vos pouco aos vossos olhos ser genro do rei, sendo eu homem pobre e desprezível?'),
('acf','1sm',18,24,'E os servos de Saul lhe anunciaram isto, dizendo: Foram tais as palavras que falou Davi.'),
('acf','1sm',18,25,'Então disse Saul: Assim direis a Davi: O rei não tem necessidade de dote, senão de cem prepúcios de filisteus, para se tomar vingança dos inimigos do rei. Porquanto Saul tentava fazer cair a Davi pela mão dos filisteus.'),
('acf','1sm',18,26,'E anunciaram os seus servos estas palavras a Davi, e este negócio pareceu bem aos olhos de Davi, de que fosse genro do rei; porém ainda os dias não se haviam cumprido.'),
('acf','1sm',18,27,'Então Davi se levantou, e partiu com os seus homens, e feriu dentre os filisteus duzentos homens, e Davi trouxe os seus prepúcios, e os entregou todos ao rei, para que fosse genro do rei; então Saul lhe deu por mulher a sua filha.'),
('acf','1sm',18,28,'E viu Saul, e notou que o Senhor era com Davi; e Mical, filha de Saul, o amava.'),
('acf','1sm',18,29,'Então Saul temeu muito mais a Davi; e Saul foi todos os seus dias inimigo de Davi.'),
('acf','1sm',18,30,'E, saindo os príncipes dos filisteus à campanha, sucedia que Davi se conduzia com mais êxito do que todos os servos de Saul; portanto o seu nome era muito estimado.'),
('acf','1sm',19,1,'E falou Saul a Jônatas, seu filho, e a todos os seus servos, para que matassem a Davi. Porém Jônatas, filho de Saul, estava mui afeiçoado a Davi.'),
('acf','1sm',19,2,'E Jônatas o anunciou a Davi, dizendo: Meu pai, Saul, procura matar-te, pelo que agora guarda-te pela manhã, e fica-te em oculto, e esconde-te.'),
('acf','1sm',19,3,'E sairei eu, e estarei à mão de meu pai no campo em que estiverdes, e eu falarei de ti a meu pai, e verei o que há, e to anunciarei.'),
('acf','1sm',19,4,'Então Jônatas falou bem de Davi a Saul, seu pai, e disse-lhe: Não peque o rei contra seu servo Davi, porque ele não pecou contra ti, e porque os seus feitos te são muito bons.'),
('acf','1sm',19,5,'Porque expôs a sua vida, e feriu aos filisteus, e fez o Senhor um grande livramento a todo o Israel; tu mesmo o viste, e te alegraste; porque, pois, pecarias contra o sangue inocente, matando a Davi, sem causa?'),
('acf','1sm',19,6,'E Saul deu ouvidos à voz de Jônatas, e jurou Saul: Vive o Senhor, que não morrerá.'),
('acf','1sm',19,7,'E Jônatas chamou a Davi, e contou-lhe todas estas palavras; e Jônatas levou Davi a Saul, e esteve perante ele como antes.'),
('acf','1sm',19,8,'E tornou a haver guerra; e saiu Davi, e pelejou contra os filisteus, e feriu-os com grande matança, e fugiram diante dele.'),
('acf','1sm',19,9,'Porém o espírito mau da parte do Senhor se tornou sobre Saul, estando ele assentado em sua casa, e tendo na mão a sua lança; e tocava Davi com a mão, a harpa.'),
('acf','1sm',19,10,'E procurou Saul encravar a Davi na parede, porém ele se desviou de diante de Saul, o qual feriu com a lança a parede; então fugiu Davi, e escapou naquela mesma noite.'),
('acf','1sm',19,11,'Porém Saul mandou mensageiros à casa de Davi, que o guardassem, e o matassem pela manhã; do que Mical, sua mulher, avisou a Davi, dizendo: Se não salvares a tua vida esta noite, amanhã te matarão.'),
('acf','1sm',19,12,'Então Mical desceu a Davi por uma janela; e ele se foi, e fugiu, e escapou.'),
('acf','1sm',19,13,'E Mical tomou uma estátua e a deitou na cama, e pôs-lhe à cabeceira uma pele de cabra, e a cobriu com uma coberta.'),
('acf','1sm',19,14,'E, mandando Saul mensageiros que trouxessem a Davi, ela disse: Está doente.'),
('acf','1sm',19,15,'Então Saul tornou a mandar mensageiros que fossem a Davi, dizendo: Trazei-mo na cama, para que o mate.'),
('acf','1sm',19,16,'Vindo, pois, os mensageiros, eis que a estátua estava na cama, e a pele de cabra à sua cabeceira.'),
('acf','1sm',19,17,'Então disse Saul a Mical: Por que assim me enganaste, e deixaste ir e escapar o meu inimigo? E disse Mical a Saul: Porque ele me disse: Deixa-me ir, por que hei de eu matar-te?'),
('acf','1sm',19,18,'Assim Davi fugiu e escapou, e foi a Samuel, em Ramá, e lhe participou tudo quanto Saul lhe fizera; e foram, ele e Samuel, e ficaram em Naiote.'),
('acf','1sm',19,19,'E o anunciaram a Saul, dizendo: Eis que Davi está em Naiote, em Ramá.'),
('acf','1sm',19,20,'Então enviou Saul mensageiros para trazerem a Davi, os quais viram uma congregação de profetas profetizando, onde estava Samuel que presidia sobre eles; e o Espírito de Deus veio sobre os mensageiros de Saul, e também eles profetizaram.'),
('acf','1sm',19,21,'E, avisado disto Saul, enviou outros mensageiros, e também estes profetizaram; então enviou Saul ainda uns terceiros mensageiros, os quais também profetizaram.'),
('acf','1sm',19,22,'Então foi também ele mesmo a Ramá, e chegou ao poço grande que estava em Secu; e, perguntando, disse: Onde estão Samuel e Davi? E disseram-lhe: Eis que estão em Naiote, em Ramá.'),
('acf','1sm',19,23,'Então foi para Naiote, em Ramá; e o mesmo Espírito de Deus veio sobre ele, e ia profetizando, até chegar a Naiote, em Ramá.'),
('acf','1sm',19,24,'E ele também despiu as suas vestes, e profetizou diante de Samuel, e esteve nu por terra todo aquele dia e toda aquela noite; por isso se diz: Está também Saul entre os profetas?'),
('acf','1sm',20,1,'Então fugiu Davi de Naiote, em Ramá; e veio, e disse a Jônatas: Que fiz eu? Qual é o meu crime? E qual é o meu pecado diante de teu pai, que procura tirar-me a vida?'),
('acf','1sm',20,2,'E ele lhe disse: Tal não suceda; não morrerás; eis que meu pai não faz coisa nenhuma grande, nem pequena, sem primeiro me informar; por que, pois, meu pai me encobriria este negócio? Não será assim.'),
('acf','1sm',20,3,'Então Davi tornou a jurar, e disse: Teu pai sabe muito bem que achei graça em teus olhos; por isso disse: Não saiba isto Jônatas, para que não se magoe. Mas, na verdade, como vive o Senhor, e como vive a tua alma, há apenas um passo entre mim e a morte.'),
('acf','1sm',20,4,'E disse Jônatas a Davi: O que disser a tua alma, eu te farei.'),
('acf','1sm',20,5,'Disse Davi a Jônatas: Eis que amanhã é a lua nova, em que costumo assentar-me com o rei para comer; porém deixa-me ir, e esconder-me-ei no campo, até à tarde do terceiro dia.'),
('acf','1sm',20,6,'Se teu pai notar a minha ausência, dirás: Davi me pediu muito que o deixasse ir correndo a Belém, sua cidade; porquanto se faz lá o sacrifício anual para toda a linhagem.'),
('acf','1sm',20,7,'Se disser assim: Está bem; então teu servo tem paz; porém se muito se indignar, sabe que já está inteiramente determinado no mal.'),
('acf','1sm',20,8,'Usa, pois, de misericórdia com o teu servo, porque o fizeste entrar contigo em aliança do Senhor; se, porém, há em mim crime, mata-me tu mesmo; por que me levarias a teu pai?'),
('acf','1sm',20,9,'Então disse Jônatas: Longe de ti tal coisa; porém se de alguma forma soubesse que já este mal está inteiramente determinado por meu pai, para que viesse sobre ti, não to revelaria eu?'),
('acf','1sm',20,10,'E disse Davi a Jônatas: Quem me fará saber, se por acaso teu pai te responder asperamente?'),
('acf','1sm',20,11,'Então disse Jônatas a Davi: Vem e saiamos ao campo. E saíram ambos ao campo.'),
('acf','1sm',20,12,'E disse Jônatas a Davi: O Senhor Deus de Israel seja testemunha! Sondando eu a meu pai amanhã a estas horas, ou depois de amanhã, e eis que se houver coisa favorável para Davi, e eu então não enviar a ti, e não to fizer saber;'),
('acf','1sm',20,13,'O Senhor faça assim com Jônatas outro tanto; que se aprouver a meu pai fazer-te mal, também to farei saber, e te deixarei partir, e irás em paz; e o Senhor seja contigo, assim como foi com meu pai.'),
('acf','1sm',20,14,'E, se eu então ainda viver, porventura não usarás comigo da beneficência do Senhor, para que não morra?'),
('acf','1sm',20,15,'Nem tampouco cortarás da minha casa a tua beneficência eternamente; nem ainda quando o Senhor desarraigar da terra a cada um dos inimigos de Davi.'),
('acf','1sm',20,16,'Assim fez Jônatas aliança com a casa de Davi, dizendo: O Senhor o requeira da mão dos inimigos de Davi.'),
('acf','1sm',20,17,'E Jônatas fez jurar a Davi de novo, porquanto o amava; porque o amava com todo o amor da sua alma.'),
('acf','1sm',20,18,'E disse-lhe Jônatas: Amanhã é a lua nova, e não te acharão no teu lugar, pois o teu assento se achará vazio.'),
('acf','1sm',20,19,'E, ausentando-te tu três dias, desce apressadamente, e vai àquele lugar onde te escondeste no dia do negócio; e fica-te junto à pedra de Ezel.'),
('acf','1sm',20,20,'E eu atirarei três flechas para aquele lado, como se atirasse ao alvo.'),
('acf','1sm',20,21,'E eis que mandarei o moço dizendo: Anda, busca as flechas. Se eu expressamente disser ao moço: Olha que as flechas estão para cá de ti; toma-o contigo, e vem, porque há paz para ti, e não há nada, vive o Senhor.'),
('acf','1sm',20,22,'Porém se disser ao moço assim: Olha que as flechas estão para lá de ti; vai-te embora, porque o Senhor te deixa ir.'),
('acf','1sm',20,23,'E quanto ao negócio de que eu e tu falamos, eis que o Senhor está entre mim e ti eternamente.'),
('acf','1sm',20,24,'Escondeu-se, pois, Davi no campo; e, sendo a lua nova, assentou-se o rei para comer pão.'),
('acf','1sm',20,25,'E, assentando-se o rei, como das outras vezes, no seu assento, no lugar junto à parede, Jônatas se levantou, e assentou-se Abner ao lado de Saul; e o lugar de Davi apareceu vazio.'),
('acf','1sm',20,26,'Porém naquele dia não disse Saul nada, porque dizia: Aconteceu-lhe alguma coisa, pela qual não está limpo; certamente não está limpo.'),
('acf','1sm',20,27,'Sucedeu também no outro dia, o segundo da lua nova, que o lugar de Davi apareceu vazio; disse, pois, Saul a Jônatas, seu filho: Por que não veio o filho de Jessé nem ontem nem hoje a comer pão?'),
('acf','1sm',20,28,'E respondeu Jônatas a Saul: Davi me pediu encarecidamente que o deixasse ir a Belém.'),
('acf','1sm',20,29,'Dizendo: Peço-te que me deixes ir, porquanto a nossa linhagem tem um sacrifício na cidade, e meu irmão mesmo me mandou ir; se, pois, agora tenho achado graça em teus olhos, peço-te que me deixes partir, para que veja a meus irmãos; por isso não veio à mesa do rei.'),
('acf','1sm',20,30,'Então se acendeu a ira de Saul contra Jônatas, e disse-lhe: Filho da mulher perversa e rebelde; não sei eu que tens escolhido o filho de Jessé, para vergonha tua e para vergonha da nudez de tua mãe?'),
('acf','1sm',20,31,'Porque todos os dias que o filho de Jessé viver sobre a terra nem tu estarás seguro, nem o teu reino; pelo que envia, e traze-mo nesta hora; porque é digno de morte.'),
('acf','1sm',20,32,'Então respondeu Jônatas a Saul, seu pai, e lhe disse: Por que há de morrer? Que tem feito?'),
('acf','1sm',20,33,'Então Saul atirou-lhe com a lança, para o ferir; assim entendeu Jônatas que já seu pai tinha determinado matar a Davi.'),
('acf','1sm',20,34,'Por isso Jônatas, todo encolerizado, se levantou da mesa; e no segundo dia da lua nova não comeu pão; porque se magoava por causa de Davi, porque seu pai o tinha humilhado.'),
('acf','1sm',20,35,'E aconteceu, pela manhã, que Jônatas saiu ao campo, ao tempo que tinha ajustado com Davi, e um moço pequeno com ele.'),
('acf','1sm',20,36,'Então disse ao seu moço: Corre a buscar as flechas que eu atirar. Correu, pois, o moço, e ele atirou uma flecha, que fez passar além dele.'),
('acf','1sm',20,37,'E, chegando o moço ao lugar da flecha que Jônatas tinha atirado, gritou Jônatas atrás do moço, e disse: Não está porventura a flecha mais para lá de ti?'),
('acf','1sm',20,38,'E tornou Jônatas a gritar atrás do moço: Apressa-te, corre, não te demores. E o moço de Jônatas apanhou as flechas, e veio a seu senhor.'),
('acf','1sm',20,39,'E o moço não entendeu coisa alguma; só Jônatas e Davi sabiam deste negócio.'),
('acf','1sm',20,40,'Então Jônatas deu as suas armas ao moço que trazia, e disse-lhe: Anda, e leva-as à cidade.'),
('acf','1sm',20,41,'E, indo-se o moço, levantou-se Davi do lado do sul, e lançou-se sobre o seu rosto em terra, e inclinou-se três vezes; e beijaram-se um ao outro, e choraram juntos, mas Davi chorou muito mais.'),
('acf','1sm',20,42,'E disse Jônatas a Davi: Vai-te em paz; o que nós temos jurado ambos em nome do Senhor, dizendo: O Senhor seja entre mim e ti, e entre a minha descendência e a tua descendência, seja perpetuamente.'),
('acf','1sm',20,43,'Então se levantou Davi, e partiu; e Jônatas entrou na cidade.'),
('acf','1sm',21,1,'Então veio Davi a Nobe, ao sacerdote Aimeleque; e Aimeleque, tremendo, saiu ao encontro de Davi, e disse-lhe: Por que vens só, e ninguém contigo?'),
('acf','1sm',21,2,'E disse Davi ao sacerdote Aimeleque: O rei me encomendou um negócio, e me disse: Ninguém saiba deste negócio, pelo qual eu te enviei, e o qual te ordenei; quanto aos moços, apontei-lhes tal e tal lugar.'),
('acf','1sm',21,3,'Agora, pois, que tens à mão? Dá-me cinco pães na minha mão, ou o que se achar.'),
('acf','1sm',21,4,'E, respondendo o sacerdote a Davi, disse: Não tenho pão comum à mão; há, porém, pão sagrado, se ao menos os moços se abstiveram das mulheres.'),
('acf','1sm',21,5,'E respondeu Davi ao sacerdote, e lhe disse: As mulheres, na verdade, se nos vedaram desde ontem e anteontem; quando eu saí, os vasos dos moços eram santos; e de algum modo é pão comum, sendo que hoje santifica-se outro no vaso.'),
('acf','1sm',21,6,'Então o sacerdote lhe deu o pão sagrado, porquanto não havia ali outro pão senão os pães da proposição, que se tiraram de diante do Senhor, para se pôr ali pão quente no dia em que aquele se tirasse.'),
('acf','1sm',21,7,'Estava, porém, ali naquele dia um dos criados de Saul, detido perante o Senhor, e era seu nome Doegue, edomeu, o mais poderoso dos pastores de Saul.'),
('acf','1sm',21,8,'E disse Davi a Aimeleque: Não tens aqui à mão lança ou espada alguma? Porque não trouxe à mão nem a minha espada nem as minhas armas, porque o negócio do rei era apressado.'),
('acf','1sm',21,9,'E disse o sacerdote: A espada de Golias, o filisteu, a quem tu feriste no vale do carvalho, eis que está aqui envolta num pano detrás do éfode. Se tu a queres tomar, toma-a, porque nenhuma outra há aqui, senão aquela. E disse Davi: Não há outra semelhante; dá-ma.'),
('acf','1sm',21,10,'E Davi levantou-se, e fugiu aquele dia de diante de Saul, e foi a Aquis, rei de Gate.'),
('acf','1sm',21,11,'Porém os criados de Aquis lhe disseram: Não é este Davi, o rei da terra? Não se cantava deste nas danças, dizendo: Saul feriu os seus milhares, porém Davi os seus dez milhares?'),
('acf','1sm',21,12,'E Davi considerou estas palavras no seu ânimo, e temeu muito diante de Aquis, rei de Gate.'),
('acf','1sm',21,13,'Por isso se contrafez diante dos olhos deles, e fez-se como doido entre as suas mãos, e esgravatava nas portas de entrada, e deixava correr a saliva pela barba.'),
('acf','1sm',21,14,'Então disse Aquis aos seus criados: Eis que bem vedes que este homem está louco; por que mo trouxestes a mim?'),
('acf','1sm',21,15,'Faltam-me a mim doidos, para que trouxésseis a este para que fizesse doidices diante de mim? Há de entrar este na minha casa?'),
('acf','1sm',22,1,'Então Davi se retirou dali, e escapou para a caverna de Adulão; e ouviram-no seus irmãos e toda a casa de seu pai, e desceram ali para ter com ele.'),
('acf','1sm',22,2,'E ajuntou-se a ele todo o homem que se achava em aperto, e todo o homem endividado, e todo o homem de espírito desgostoso, e ele se fez capitão deles; e eram com ele uns quatrocentos homens.'),
('acf','1sm',22,3,'E foi Davi dali a Mizpá dos moabitas, e disse ao rei dos moabitas: Deixa estar meu pai e minha mãe convosco, até que saiba o que Deus há de fazer de mim.'),
('acf','1sm',22,4,'E trouxe-os perante o rei dos moabitas, e ficaram com ele todos os dias que Davi esteve no lugar forte.'),
('acf','1sm',22,5,'Porém o profeta Gade disse a Davi: Não fiques naquele lugar forte; vai, e entra na terra de Judá. Então Davi saiu, e foi para o bosque de Herete.'),
('acf','1sm',22,6,'E ouviu Saul que já se sabia de Davi e dos homens que estavam com ele; e estava Saul em Gibeá, debaixo de um arvoredo, em Ramá, e tinha na mão a sua lança, e todos os seus criados estavam com ele.'),
('acf','1sm',22,7,'Então disse Saul a todos os seus criados que estavam com ele: Ouvi, peço-vos, filhos de Benjamim, dar-vos-á também o filho de Jessé, a todos vós, terras e vinhas, e far-vos-á a todos capitães de milhares e capitães de centenas,'),
('acf','1sm',22,8,'Para que todos vós tenhais conspirado contra mim, e ninguém há que me dê aviso de que meu filho tem feito aliança com o filho de Jessé, e nenhum dentre vós há que se doa de mim, e mo participe, pois meu filho tem contra mim sublevado a meu servo, para me armar ciladas, como se vê neste dia?'),
('acf','1sm',22,9,'Então respondeu Doegue, o edomeu, que também estava com os criados de Saul, e disse: Vi o filho de Jessé chegar a Nobe, a Aimeleque, filho de Aitube,'),
('acf','1sm',22,10,'O qual consultou por ele ao Senhor, e lhe deu mantimento, e lhe deu também a espada de Golias, o filisteu.'),
('acf','1sm',22,11,'Então o rei mandou chamar a Aimeleque, sacerdote, filho de Aitube, e a toda a casa de seu pai, os sacerdotes que estavam em Nobe; e todos eles vieram ao rei.'),
('acf','1sm',22,12,'E disse Saul: Ouve, peço-te, filho de Aitube. E ele disse: Eis-me aqui, senhor meu.'),
('acf','1sm',22,13,'Então lhe disse Saul: Por que conspirastes contra mim, tu e o filho de Jessé? Pois deste-lhe pão e espada, e consultaste por ele a Deus, para que se levantasse contra mim a armar-me ciladas, como se vê neste dia?'),
('acf','1sm',22,14,'E respondeu Aimeleque ao rei e disse: E quem, entre todos os teus criados, há tão fiel como Davi, o genro do rei, pronto na sua obediência, e honrado na tua casa?'),
('acf','1sm',22,15,'Comecei, porventura, hoje a consultar por ele a Deus? Longe de mim tal! Não impute o rei coisa nenhuma a seu servo, nem a toda a casa de meu pai, pois o teu servo não soube nada de tudo isso, nem muito nem pouco.'),
('acf','1sm',22,16,'Porém o rei disse: Aimeleque, morrerás certamente, tu e toda a casa de teu pai,'),
('acf','1sm',22,17,'E disse o rei aos da sua guarda que estavam com ele: Virai-vos, e matai os sacerdotes do Senhor, porque também a sua mão é com Davi, e porque souberam que fugiu e não mo fizeram saber. Porém os criados do rei não quiseram estender as suas mãos para arremeter contra os sacerdotes do Senhor.'),
('acf','1sm',22,18,'Então disse o rei a Doegue: Vira-te, e arremete contra os sacerdotes. Então se virou Doegue, o edomeu, e arremeteu contra os sacerdotes, e matou naquele dia oitenta e cinco homens que vestiam éfode de linho.'),
('acf','1sm',22,19,'Também a Nobe, cidade destes sacerdotes, passou a fio de espada, desde o homem até à mulher, desde os meninos até aos de peito, e até os bois, jumentos e ovelhas passou a fio de espada.'),
('acf','1sm',22,20,'Porém escapou um dos filhos de Aimeleque, filho de Aitube, cujo nome era Abiatar, o qual fugiu para Davi.'),
('acf','1sm',22,21,'E Abiatar anunciou a Davi que Saul tinha matado os sacerdotes do Senhor.'),
('acf','1sm',22,22,'Então Davi disse a Abiatar: Bem sabia eu naquele dia que, estando ali Doegue, o edomeu, não deixaria de o denunciar a Saul; eu dei ocasião contra todas as almas da casa de teu pai.'),
('acf','1sm',22,23,'Fica comigo, não temas, porque quem procurar a minha morte também procurará a tua, pois estarás salvo comigo.'),
('acf','1sm',23,1,'E foi anunciado a Davi, dizendo: Eis que os filisteus pelejam contra Queila, e saqueiam as eiras.'),
('acf','1sm',23,2,'E consultou Davi ao Senhor, dizendo: Irei eu, e ferirei a estes filisteus? E disse o Senhor a Davi: Vai, e ferirás aos filisteus, e livrarás a Queila.'),
('acf','1sm',23,3,'Porém os homens de Davi lhe disseram: Eis que tememos aqui em Judá, quanto mais indo a Queila contra os esquadrões dos filisteus.'),
('acf','1sm',23,4,'Então Davi tornou a consultar ao Senhor, e o Senhor lhe respondeu, e disse: Levanta-te, desce a Queila, porque te dou os filisteus na tua mão.'),
('acf','1sm',23,5,'Então Davi partiu com os seus homens a Queila, e pelejou contra os filisteus, e levou os gados, e fez grande estrago entre eles; e Davi livrou os moradores de Queila.'),
('acf','1sm',23,6,'E sucedeu que, quando Abiatar, filho de Aimeleque, fugiu para Davi, a Queila, desceu com o éfode na mão.'),
('acf','1sm',23,7,'E foi anunciado a Saul que Davi tinha ido a Queila, e disse Saul: Deus o entregou nas minhas mãos, pois está encerrado, entrando numa cidade de portas e ferrolhos.'),
('acf','1sm',23,8,'Então Saul mandou chamar a todo o povo à peleja, para que descessem a Queila, para cercar a Davi e os seus homens.'),
('acf','1sm',23,9,'Sabendo, pois, Davi, que Saul maquinava este mal contra ele, disse a Abiatar, sacerdote: Traze aqui o éfode.'),
('acf','1sm',23,10,'E disse Davi: Ó Senhor, Deus de Israel, teu servo tem ouvido que Saul procura vir a Queila, para destruir a cidade por causa de mim.'),
('acf','1sm',23,11,'Entregar-me-ão os cidadãos de Queila na sua mão? Descerá Saul, como o teu servo tem ouvido? Ah! Senhor Deus de Israel! Faze-o saber ao teu servo. E disse o Senhor: Descerá.'),
('acf','1sm',23,12,'Disse mais Davi: Entregar-me-ão os cidadãos de Queila, a mim e aos meus homens, nas mãos de Saul? E disse o Senhor: Entregarão.'),
('acf','1sm',23,13,'Então Davi se levantou com os seus homens, uns seiscentos, e saíram de Queila, e foram-se aonde puderam; e sendo anunciado a Saul, que Davi escapara de Queila, cessou de sair contra ele.'),
('acf','1sm',23,14,'E Davi permaneceu no deserto, nos lugares fortes, e ficou em um monte no deserto de Zife; e Saul o buscava todos os dias, porém Deus não o entregou na sua mão.'),
('acf','1sm',23,15,'Vendo, pois, Davi, que Saul saíra à busca da sua vida, permaneceu no deserto de Zife, num bosque.'),
('acf','1sm',23,16,'Então se levantou Jônatas, filho de Saul, e foi para Davi no bosque, e confortou a sua mão em Deus;'),
('acf','1sm',23,17,'E disse-lhe: Não temas, que não te achará a mão de Saul, meu pai; porém tu reinarás sobre Israel, e eu serei contigo o segundo; o que também Saul, meu pai, bem sabe.'),
('acf','1sm',23,18,'E ambos fizeram aliança perante o Senhor; Davi ficou no bosque, e Jônatas voltou para a sua casa.'),
('acf','1sm',23,19,'Então subiram os zifeus a Saul, a Gibeá, dizendo: Não se escondeu Davi entre nós, nos lugares fortes no bosque, no outeiro de Haquilá, que está à mão direita de Jesimom?'),
('acf','1sm',23,20,'Agora, pois, ó rei, apressadamente desce conforme a todo o desejo da tua alma; a nós cumpre entregá-lo nas mãos do rei.'),
('acf','1sm',23,21,'Então disse Saul: Bendito sejais vós do Senhor, porque vos compadecestes de mim.'),
('acf','1sm',23,22,'Ide, pois, e diligenciai ainda mais, e sabei e notai o lugar que freqüenta, e quem o tenha visto ali; porque me foi dito que é astutíssimo.'),
('acf','1sm',23,23,'Por isso atentai bem, e informai-vos acerca de todos os esconderijos, em que ele se esconde; e então voltai para mim com toda a certeza, e ir-me-ei convosco; e há de ser que, se estiver naquela terra, o buscarei entre todos os milhares de Judá.'),
('acf','1sm',23,24,'Então se levantaram eles e se foram a Zife, adiante de Saul; Davi, porém, e os seus homens estavam no deserto de Maom, na campina, à direita de Jesimom.'),
('acf','1sm',23,25,'E Saul e os seus homens se foram em busca dele; o que anunciaram a Davi, que desceu para aquela penha, e ficou no deserto de Maom; o que ouvindo Saul, seguiu a Davi para o deserto de Maom.'),
('acf','1sm',23,26,'E Saul ia deste lado do monte, e Davi e os seus homens do outro lado do monte; e, temeroso, Davi se apressou a escapar de Saul; Saul, porém, e os seus homens cercaram a Davi e aos seus homens, para lançar mão deles.'),
('acf','1sm',23,27,'Então veio um mensageiro a Saul, dizendo: Apressa-te, e vem, porque os filisteus com ímpeto entraram na terra.'),
('acf','1sm',23,28,'Por isso Saul voltou de perseguir a Davi, e foi ao encontro dos filisteus; por esta razão aquele lugar se chamou Rochedo das Divisões.'),
('acf','1sm',23,29,'E subiu Davi dali, e ficou nos lugares fortes de En-Gedi.'),
('acf','1sm',24,1,'E sucedeu que, voltando Saul de perseguir os filisteus, anunciaram-lhe, dizendo: Eis que Davi está no deserto de En-Gedi.'),
('acf','1sm',24,2,'Então tomou Saul três mil homens, escolhidos dentre todo o Israel, e foi em busca de Davi e dos seus homens, até sobre os cumes das penhas das cabras montesas.'),
('acf','1sm',24,3,'E chegou a uns currais de ovelhas no caminho, onde estava uma caverna; e entrou nela Saul, a cobrir seus pés; e Davi e os seus homens estavam nos fundos da caverna.'),
('acf','1sm',24,4,'Então os homens de Davi lhe disseram: Eis aqui o dia, do qual o Senhor te diz: Eis que te dou o teu inimigo nas tuas mãos, e far-lhe-ás como te parecer bem aos teus olhos. E levantou-se Davi, e mansamente cortou a orla do manto de Saul.'),
('acf','1sm',24,5,'Sucedeu, porém, que depois o coração doeu a Davi, por ter cortado a orla do manto de Saul.'),
('acf','1sm',24,6,'E disse aos seus homens: O SENHOR me guarde de que eu faça tal coisa ao meu senhor, ao ungido do SENHOR, estendendo eu a minha mão contra ele; pois é o ungido do SENHOR.'),
('acf','1sm',24,7,'E com estas palavras Davi conteve os seus homens, e não lhes permitiu que se levantassem contra Saul; e Saul se levantou da caverna, e prosseguiu o seu caminho.'),
('acf','1sm',24,8,'Depois também Davi se levantou, e saiu da caverna, e gritou por detrás de Saul, dizendo: Rei, meu senhor! E, olhando Saul para trás, Davi se inclinou com o rosto em terra, e se prostrou.'),
('acf','1sm',24,9,'E disse Davi a Saul: Por que dás tu ouvidos às palavras dos homens que dizem: Eis que Davi procura o teu mal?'),
('acf','1sm',24,10,'Eis que este dia os teus olhos viram, que o SENHOR hoje te pôs em minhas mãos nesta caverna, e alguns disseram que te matasse; porém a minha mão te poupou; porque disse: Não estenderei a minha mão contra o meu senhor, pois é o ungido do SENHOR.'),
('acf','1sm',24,11,'Olha, pois, meu pai, vê aqui a orla do teu manto na minha mão; porque cortando-te eu a orla do manto, não te matei. Sabe, pois, e vê que não há na minha mão nem mal nem rebeldia alguma, e não pequei contra ti; porém tu andas à caça da minha vida, para ma tirares.'),
('acf','1sm',24,12,'Julgue o Senhor entre mim e ti, e vingue-me o Senhor de ti; porém a minha mão não será contra ti.'),
('acf','1sm',24,13,'Como diz o provérbio dos antigos: Dos ímpios procede a impiedade; porém a minha mão não será contra ti.'),
('acf','1sm',24,14,'Após quem saiu o rei de Israel? A quem persegues? A um cão morto? A uma pulga?'),
('acf','1sm',24,15,'O Senhor, porém, será juiz, e julgará entre mim e ti, e verá, e advogará a minha causa, e me defenderá da tua mão.'),
('acf','1sm',24,16,'E sucedeu que, acabando Davi de falar a Saul todas estas palavras, disse Saul: É esta a tua voz, meu filho Davi? Então Saul levantou a sua voz e chorou.'),
('acf','1sm',24,17,'E disse a Davi: Mais justo és do que eu; pois tu me recompensaste com bem, e eu te recompensei com mal.'),
('acf','1sm',24,18,'E tu mostraste hoje que procedeste bem para comigo, pois o Senhor me tinha posto em tuas mãos, e tu não me mataste.'),
('acf','1sm',24,19,'Porque, quem há que, encontrando o seu inimigo, o deixaria ir por bom caminho? O Senhor, pois, te pague com bem, por isso que hoje me fizeste.'),
('acf','1sm',24,20,'Agora, pois, eis que bem sei que certamente hás de reinar, e que o reino de Israel há de ser firme na tua mão.'),
('acf','1sm',24,21,'Portanto agora jura-me pelo Senhor que não desarraigarás a minha descendência depois de mim, nem desfarás o meu nome da casa de meu pai.'),
('acf','1sm',24,22,'Então jurou Davi a Saul. E foi Saul para a sua casa; porém Davi e os seus homens subiram ao lugar forte.'),
('acf','1sm',25,1,'E faleceu Samuel, e todo o Israel se ajuntou, e o prantearam, e o sepultaram na sua casa, em Ramá. E Davi se levantou e desceu ao deserto de Parã.'),
('acf','1sm',25,2,'E havia um homem em Maom, que tinha as suas possessões no Carmelo; e era este homem muito poderoso, e tinha três mil ovelhas e mil cabras; e estava tosquiando as suas ovelhas no Carmelo.'),
('acf','1sm',25,3,'E era o nome deste homem Nabal, e o nome de sua mulher Abigail; e era a mulher de bom entendimento e formosa; porém o homem era duro, e maligno nas obras, e era da casa de Calebe.'),
('acf','1sm',25,4,'E ouviu Davi no deserto que Nabal tosquiava as suas ovelhas,'),
('acf','1sm',25,5,'E enviou Davi dez moços, e disse aos moços: Subi ao Carmelo, e, indo a Nabal, perguntai-lhe, em meu nome, como está.'),
('acf','1sm',25,6,'E assim direis àquele próspero: Paz tenhas, e que a tua casa tenha paz, e tudo o que tens tenha paz!'),
('acf','1sm',25,7,'Agora, pois, tenho ouvido que tens tosquiadores. Ora, os pastores que tens estiveram conosco; agravo nenhum lhes fizemos, nem coisa alguma lhes faltou todos os dias que estiveram no Carmelo.'),
('acf','1sm',25,8,'Pergunta-o aos teus moços, e eles to dirão. Estes moços, pois, achem graça em teus olhos, porque viemos em boa ocasião. Dá, pois, a teus servos e a Davi, teu filho, o que achares à mão.'),
('acf','1sm',25,9,'Chegando, pois, os moços de Davi, e falando a Nabal todas aquelas palavras em nome de Davi, se calaram.'),
('acf','1sm',25,10,'E Nabal respondeu aos criados de Davi, e disse: Quem é Davi, e quem é o filho de Jessé? Muitos servos há hoje, que fogem ao seu senhor.'),
('acf','1sm',25,11,'Tomaria eu, pois, o meu pão, e a minha água, e a carne das minhas reses que degolei para os meus tosquiadores, e o daria a homens que eu não sei donde vêm?'),
('acf','1sm',25,12,'Então os moços de Davi puseram-se a caminho e voltaram, e chegando, lhe anunciaram tudo conforme a todas estas palavras.'),
('acf','1sm',25,13,'Por isso disse Davi aos seus homens: Cada um cinja a sua espada. E cada um cingiu a sua espada, e cingiu também Davi a sua; e subiram após Davi uns quatrocentos homens, e duzentos ficaram com a bagagem.'),
('acf','1sm',25,14,'Porém um dentre os moços o anunciou a Abigail, mulher de Nabal, dizendo: Eis que Davi enviou mensageiros desde o deserto a saudar o nosso amo; porém ele os destratou.'),
('acf','1sm',25,15,'Todavia, aqueles homens têm-nos sido muito bons, e nunca fomos agravados por eles, e nada nos faltou em todos os dias que convivemos com eles quando estavam no campo.'),
('acf','1sm',25,16,'De muro em redor nos serviram, assim de dia como de noite, todos os dias que andamos com eles apascentando as ovelhas.'),
('acf','1sm',25,17,'Considera, pois, agora, e vê o que hás de fazer, porque o mal já está de todo determinado contra o nosso amo e contra toda a sua casa, e ele é um homem vil, que não há quem lhe possa falar.'),
('acf','1sm',25,18,'Então Abigail se apressou, e tomou duzentos pães, e dois odres de vinho, e cinco ovelhas guisadas, e cinco medidas de trigo tostado, e cem cachos de passas, e duzentas pastas de figos passados, e os pôs sobre jumentos.'),
('acf','1sm',25,19,'E disse aos seus moços: Ide adiante de mim, eis que vos seguirei de perto. O que, porém, não declarou a seu marido Nabal.'),
('acf','1sm',25,20,'E sucedeu que, andando ela montada num jumento, desceu pelo encoberto do monte, e eis que Davi e os seus homens lhe vinham ao encontro, e ela encontrou-se com eles.'),
('acf','1sm',25,21,'E disse Davi: Na verdade que em vão tenho guardado tudo quanto este tem no deserto, e nada lhe faltou de tudo quanto tem, e ele me pagou mal por bem.'),
('acf','1sm',25,22,'Assim faça Deus aos inimigos de Davi, e outro tanto, se eu deixar até amanhã de tudo o que tem, até mesmo um menino.'),
('acf','1sm',25,23,'Vendo, pois, Abigail a Davi, apressou-se, e desceu do jumento, e prostrou-se sobre o seu rosto diante de Davi, e se inclinou à terra.'),
('acf','1sm',25,24,'E lançou-se a seus pés, e disse: Ah, senhor meu, minha seja a transgressão; deixa, pois, falar a tua serva aos teus ouvidos, e ouve as palavras da tua serva.'),
('acf','1sm',25,25,'Meu senhor, agora não faça este homem vil, a saber, Nabal, impressão no seu coração, porque tal é ele qual é o seu nome. Nabal é o seu nome, e a loucura está com ele, e eu, tua serva, não vi os moços de meu senhor, que enviaste.'),
('acf','1sm',25,26,'Agora, pois, meu senhor, vive o SENHOR, e vive a tua alma, que o SENHOR te impediu de vires com sangue, e de que a tua mão te salvasse; e, agora, tais quais Nabal sejam os teus inimigos e os que procuram mal contra o meu senhor.'),
('acf','1sm',25,27,'E agora este é o presente que trouxe a tua serva a meu senhor; seja dado aos moços que seguem ao meu senhor.'),
('acf','1sm',25,28,'Perdoa, pois, à tua serva esta transgressão, porque certamente fará o SENHOR casa firme a meu senhor, porque meu senhor guerreia as guerras do SENHOR, e não se tem achado mal em ti por todos os teus dias,'),
('acf','1sm',25,29,'E, levantando-se algum homem para te perseguir, e para procurar a tua morte, contudo a vida de meu senhor será atada no feixe dos que vivem com o SENHOR teu Deus; porém a vida de teus inimigos ele arrojará ao longe, como do meio do côncavo de uma funda.'),
('acf','1sm',25,30,'E há de ser que, usando o SENHOR com o meu senhor conforme a todo o bem que já tem falado de ti, e te houver estabelecido príncipe sobre Israel,'),
('acf','1sm',25,31,'Então, meu senhor, não te será por tropeço, nem por pesar no coração, o sangue que sem causa derramaste, nem tampouco por ter se vingado o meu senhor a si mesmo; e quando o SENHOR fizer bem a meu senhor, lembra-te então da tua serva.'),
('acf','1sm',25,32,'Então Davi disse a Abigail: Bendito o Senhor Deus de Israel, que hoje te enviou ao meu encontro.'),
('acf','1sm',25,33,'E bendito o teu conselho, e bendita tu, que hoje me impediste de derramar sangue, e de vingar-me pela minha própria mão.'),
('acf','1sm',25,34,'Porque, na verdade, vive o Senhor Deus de Israel, que me impediu de que te fizesse mal, que se tu não te apressaras, e não me vieras ao encontro, não ficaria a Nabal até a luz da manhã nem mesmo um menino.'),
('acf','1sm',25,35,'Então Davi tomou da sua mão o que tinha trazido, e lhe disse: Sobe em paz à tua casa; vês aqui que tenho dado ouvidos à tua voz, e tenho aceitado a tua face.'),
('acf','1sm',25,36,'E, vindo Abigail a Nabal, eis que tinha em sua casa um banquete, como banquete de rei; e o coração de Nabal estava alegre nele, e ele já muito embriagado, pelo que ela não lhe deu a entender coisa alguma, pequena nem grande, até à luz da manhã.'),
('acf','1sm',25,37,'Sucedeu, pois, que pela manhã, estando Nabal já livre do vinho, sua mulher lhe deu a entender aquelas coisas; e se amorteceu o seu coração, e ficou ele como pedra.'),
('acf','1sm',25,38,'E aconteceu que, passados quase dez dias, feriu o Senhor a Nabal, e este morreu.'),
('acf','1sm',25,39,'E, ouvindo Davi que Nabal morrera, disse: Bendito seja o Senhor, que julgou a causa de minha afronta recebida da mão de Nabal, e deteve a seu servo do mal, fazendo o Senhor tornar o mal de Nabal sobre a sua cabeça. E mandou Davi falar a Abigail, para tomá-la por sua mulher.'),
('acf','1sm',25,40,'Vindo, pois, os criados de Davi a Abigail, no Carmelo, lhe falaram, dizendo: Davi nos tem mandado a ti, para te tomar por sua mulher.'),
('acf','1sm',25,41,'Então ela se levantou, e se inclinou com o rosto em terra, e disse: Eis que a tua serva servirá de criada para lavar os pés dos criados de meu senhor.'),
('acf','1sm',25,42,'E Abigail se apressou, e se levantou, e montou num jumento com as suas cinco moças que seguiam as suas pisadas; e ela seguiu os mensageiros de Davi, e foi sua mulher.'),
('acf','1sm',25,43,'Também tomou Davi a Ainoã de Jizreel; e ambas foram suas mulheres.'),
('acf','1sm',25,44,'Porque Saul tinha dado sua filha Mical, mulher de Davi, a Palti, filho de Laís, o qual era de Galim.'),
('acf','1sm',26,1,'E vieram os zifeus a Saul, a Gibeá, dizendo: Não está Davi escondido no outeiro de Haquilá, defronte de Jesimom?'),
('acf','1sm',26,2,'Então Saul se levantou e desceu ao deserto de Zife, e com ele três mil homens escolhidos de Israel, a buscar a Davi no deserto de Zife.'),
('acf','1sm',26,3,'E acampou-se Saul no outeiro de Haquilá, que está defronte de Jesimom, junto ao caminho; porém Davi ficou no deserto, e viu que Saul vinha seguindo-o no deserto.'),
('acf','1sm',26,4,'Pois Davi enviou espias, e soube que Saul tinha vindo.'),
('acf','1sm',26,5,'E Davi se levantou, e foi ao lugar onde Saul se tinha acampado; viu Davi o lugar onde se tinha deitado Saul, e Abner, filho de Ner, capitão do seu exército; e Saul estava deitado dentro do lugar dos carros, e o povo estava acampado ao redor dele.'),
('acf','1sm',26,6,'E dirigindo-se Davi a Aimeleque, o heteu, e a Abisai, filho de Zeruia, irmão de Joabe, disse: Quem descerá comigo a Saul ao arraial? E respondeu Abisai: Eu descerei contigo.'),
('acf','1sm',26,7,'Foram, pois, Davi e Abisai de noite ao povo, e eis que Saul estava deitado dormindo dentro do lugar dos carros, e a sua lança estava fincada na terra à sua cabeceira; e Abner e o povo deitavam-se ao redor dele.'),
('acf','1sm',26,8,'Então disse Abisai a Davi: Deus te entregou hoje nas mãos o teu inimigo; deixa-me, pois, agora encravá-lo com a lança de uma vez na terra, e não o ferirei segunda vez.'),
('acf','1sm',26,9,'E disse Davi a Abisai: Nenhum dano lhe faças; porque quem estendeu a sua mão contra o ungido do Senhor, e ficou inocente?'),
('acf','1sm',26,10,'Disse mais Davi: Vive o Senhor que o Senhor o ferirá, ou o seu dia chegará em que morra, ou descerá para a batalha e perecerá.'),
('acf','1sm',26,11,'O Senhor me guarde, de que eu estenda a mão contra o ungido do Senhor; agora, porém, toma a lança que está à sua cabeceira e a bilha de água, e vamo-nos.'),
('acf','1sm',26,12,'Tomou, pois, Davi a lança e a bilha de água, da cabeceira de Saul, e foram-se; e ninguém houve que o visse, nem que o advertisse, nem que acordasse; porque todos estavam dormindo, porque da parte do Senhor havia caído sobre eles um profundo sono.'),
('acf','1sm',26,13,'E Davi, passando ao outro lado, pôs-se no cume do monte ao longe, de maneira que entre eles havia grande distância.'),
('acf','1sm',26,14,'E Davi bradou ao povo, e a Abner, filho de Ner, dizendo: Não responderás, Abner? Então Abner respondeu e disse: Quem és tu, que bradas ao rei?'),
('acf','1sm',26,15,'Então disse Davi a Abner: Porventura não és homem? E quem há em Israel como tu? Por que, pois, não guardaste o rei, teu senhor? Porque um do povo veio para destruir o rei, teu senhor.'),
('acf','1sm',26,16,'Não é bom isso, que fizeste; vive o SENHOR, que sois dignos de morte, vós que não guardastes a vosso senhor, o ungido do SENHOR; vede, pois, agora onde está a lança do rei, e a bilha de água, que tinha à sua cabeceira.'),
('acf','1sm',26,17,'Então conheceu Saul a voz de Davi, e disse: Não é esta a tua voz, meu filho Davi? E disse Davi: É minha voz, ó rei meu senhor.'),
('acf','1sm',26,18,'Disse mais: Por que persegue o meu senhor tanto o seu servo? Que fiz eu? E que maldade se acha nas minhas mãos?'),
('acf','1sm',26,19,'Ouve, pois, agora, te rogo, rei meu senhor, as palavras de teu servo: Se o SENHOR te incita contra mim, receba ele a oferta de alimentos; se, porém, são os filhos dos homens, malditos sejam perante o SENHOR; pois eles me têm expulsado hoje para que eu não tenha parte na herança do SENHOR, dizendo: Vai, serve a outros deuses.'),
('acf','1sm',26,20,'Agora, pois, não se derrame o meu sangue na terra diante do Senhor; pois saiu o rei de Israel em busca de uma pulga, como quem persegue uma perdiz nos montes.'),
('acf','1sm',26,21,'Então disse Saul: Pequei; volta, meu filho Davi, porque não tornarei a fazer-te mal; porque foi hoje preciosa a minha vida aos teus olhos; eis que procedi loucamente, e errei grandissimamente.'),
('acf','1sm',26,22,'Davi então respondeu, e disse: Eis aqui a lança do rei; venha cá um dos moços, e leve-a.'),
('acf','1sm',26,23,'O Senhor, porém, pague a cada um a sua justiça e a sua lealdade; pois o Senhor te entregou hoje na minha mão, porém não quis estender a minha mão contra o ungido do Senhor.'),
('acf','1sm',26,24,'E eis que, assim como foi a tua vida hoje de tanta estima aos meus olhos, assim seja a minha vida de muita estima aos olhos do Senhor, e ele me livre de toda a tribulação.'),
('acf','1sm',26,25,'Então Saul disse a Davi: Bendito sejas tu, meu filho Davi; pois grandes coisas farás e também prevalecerás. Então Davi se foi pelo seu caminho e Saul voltou para o seu lugar.'),
('acf','1sm',27,1,'Disse, porém, Davi no seu coração: Ora, algum dia ainda perecerei pela mão de Saul; não há coisa melhor para mim do que escapar apressadamente para a terra dos filisteus, para que Saul perca a esperança de mim, e cesse de me buscar por todos os termos de Israel; e assim escaparei da sua mão.'),
('acf','1sm',27,2,'Então Davi se levantou, e passou, com os seiscentos homens que com ele estavam, a Aquis, filho de Maoque, rei de Gate.'),
('acf','1sm',27,3,'E Davi ficou com Aquis em Gate, ele e os seus homens, cada um com a sua casa; Davi com ambas as suas mulheres, Ainoã, a jizreelita, e Abigail, a mulher de Nabal, o carmelita.'),
('acf','1sm',27,4,'E, sendo Saul avisado que Davi tinha fugido para Gate, não cuidou mais de buscá-lo.'),
('acf','1sm',27,5,'E disse Davi a Aquis: Se eu tenho achado graça em teus olhos, dá-me lugar numa das cidades da terra, para que ali habite; pois por que razão habitaria o teu servo contigo na cidade real?'),
('acf','1sm',27,6,'Então lhe deu Aquis, naquele dia, a cidade de Ziclague (por isso Ziclague pertence aos reis de Judá, até ao dia de hoje).'),
('acf','1sm',27,7,'E foi o número dos dias, que Davi habitou na terra dos filisteus, um ano e quatro meses.'),
('acf','1sm',27,8,'E subia Davi com os seus homens, e davam sobre os gesuritas, e os gersitas, e os amalequitas; porque antigamente foram estes os moradores da terra que se estende na direção de Sur, até à terra do Egito.'),
('acf','1sm',27,9,'E Davi feria aquela terra, e não dava vida nem a homem nem a mulher, e tomava ovelhas, e vacas, e jumentos, e camelos, e vestes; e voltava, e vinha a Aquis.'),
('acf','1sm',27,10,'E dizendo Aquis: Onde atacastes hoje? Davi dizia: Sobre o sul de Judá, e sobre o sul dos jerameelitas, e sobre o sul dos queneus.'),
('acf','1sm',27,11,'E Davi não deixava com vida nem a homem nem a mulher, para trazê-los a Gate, dizendo: Para que porventura não nos denunciem, dizendo: Assim Davi o fazia. E este era o seu costume por todos os dias que habitou na terra dos filisteus.'),
('acf','1sm',27,12,'E Aquis confiava em Davi, dizendo: Fez-se ele por certo aborrecível para com o seu povo em Israel; por isso me será por servo para sempre.'),
('acf','1sm',28,1,'E sucedeu naqueles dias que, juntando os filisteus os seus exércitos à peleja, para fazer guerra contra Israel, disse Aquis a Davi: Sabe de certo que comigo sairás ao arraial, tu e os teus homens.'),
('acf','1sm',28,2,'Então disse Davi a Aquis: Assim saberás o que fará o teu servo. E disse Aquis a Davi: Por isso te terei por guarda da minha pessoa para sempre.'),
('acf','1sm',28,3,'E Samuel já estava morto, e todo o Israel o tinha chorado, e o tinha sepultado em Ramá, que era a sua cidade; e Saul tinha desterrado os adivinhos e os encantadores.'),
('acf','1sm',28,4,'E ajuntaram-se os filisteus, e vieram, e acamparam-se em Suném; e ajuntou Saul a todo o Israel, e se acamparam em Gilboa.'),
('acf','1sm',28,5,'E, vendo Saul o arraial dos filisteus, temeu, e estremeceu muito o seu coração.'),
('acf','1sm',28,6,'E perguntou Saul ao Senhor, porém o Senhor não lhe respondeu, nem por sonhos, nem por Urim, nem por profetas.'),
('acf','1sm',28,7,'Então disse Saul aos seus criados: Buscai-me uma mulher que tenha o espírito de feiticeira, para que vá a ela, e consulte por ela. E os seus criados lhe disseram: Eis que em En-Dor há uma mulher que tem o espírito de adivinhar.'),
('acf','1sm',28,8,'E Saul se disfarçou, e vestiu outras roupas, e foi ele com dois homens, e de noite chegaram à mulher; e disse: Peço-te que me adivinhes pelo espírito de feiticeira, e me faças subir a quem eu te disser.'),
('acf','1sm',28,9,'Então a mulher lhe disse: Eis aqui tu sabes o que Saul fez, como tem destruído da terra os adivinhos e os encantadores; por que, pois, me armas um laço à minha vida, para me fazeres morrer?'),
('acf','1sm',28,10,'Então Saul lhe jurou pelo Senhor, dizendo: Vive o Senhor, que nenhum mal te sobrevirá por isso.'),
('acf','1sm',28,11,'A mulher então lhe disse: A quem te farei subir? E disse ele: Faze-me subir a Samuel.'),
('acf','1sm',28,12,'Vendo, pois, a mulher a Samuel, gritou com alta voz, e falou a Saul, dizendo: Por que me tens enganado? Pois tu mesmo és Saul.'),
('acf','1sm',28,13,'E o rei lhe disse: Não temas; que é que vês? Então a mulher disse a Saul: Vejo deuses que sobem da terra.'),
('acf','1sm',28,14,'E lhe disse: Como é a sua figura? E disse ela: Vem subindo um homem ancião, e está envolto numa capa. Entendendo Saul que era Samuel, inclinou-se com o rosto em terra, e se prostrou.'),
('acf','1sm',28,15,'Samuel disse a Saul: Por que me inquietaste, fazendo-me subir? Então disse Saul: Mui angustiado estou, porque os filisteus guerreiam contra mim, e Deus se tem desviado de mim, e não me responde mais, nem pelo ministério dos profetas, nem por sonhos; por isso te chamei a ti, para que me faças saber o que hei de fazer.'),
('acf','1sm',28,16,'Então disse Samuel: Por que, pois, me perguntas a mim, visto que o Senhor te tem desamparado, e se tem feito teu inimigo?'),
('acf','1sm',28,17,'Porque o Senhor tem feito para contigo como pela minha boca te disse, e o Senhor tem rasgado o reino da tua mão, e o tem dado ao teu próximo, a Davi.'),
('acf','1sm',28,18,'Como tu não deste ouvidos à voz do Senhor, e não executaste o fervor da sua ira contra Amaleque, por isso o Senhor te fez hoje isto.'),
('acf','1sm',28,19,'E o Senhor entregará também a Israel contigo na mão dos filisteus, e amanhã tu e teus filhos estareis comigo; e o arraial de Israel o Senhor entregará na mão dos filisteus.'),
('acf','1sm',28,20,'E imediatamente Saul caiu estendido por terra, e grandemente temeu por causa daquelas palavras de Samuel; e não houve força nele; porque não tinha comido pão todo aquele dia e toda aquela noite.'),
('acf','1sm',28,21,'Então veio a mulher a Saul e, vendo que estava tão perturbado, disse-lhe: Eis que a tua criada deu ouvidos à tua voz, e pus a minha vida na minha mão, e ouvi as palavras que disseste.'),
('acf','1sm',28,22,'Agora, pois, ouve também tu as palavras da tua serva, e porei um bocado de pão diante de ti, e come, para que tenhas forças para te pores a caminho.'),
('acf','1sm',28,23,'Porém ele o recusou, e disse: Não comerei. Porém os seus criados e a mulher o constrangeram; e deu ouvidos à sua voz; e levantou-se do chão, e se assentou sobre uma cama.'),
('acf','1sm',28,24,'E tinha a mulher em casa um bezerro cevado, e se apressou, e o matou, e tomou farinha, e a amassou, e a cozeu em bolos ázimos.'),
('acf','1sm',28,25,'E os trouxe diante de Saul e de seus criados, e comeram; depois levantaram-se e partiram naquela mesma noite.'),
('acf','1sm',29,1,'E ajuntaram os filisteus todos os seus exércitos em Afeque; e acamparam-se os israelitas junto à fonte que está em Jizreel.'),
('acf','1sm',29,2,'E os príncipes dos filisteus se foram para lá com centenas e com milhares; porém Davi e os seus homens iam com Aquis na retaguarda.'),
('acf','1sm',29,3,'Disseram então os príncipes dos filisteus: Que fazem aqui estes hebreus? E disse Aquis aos príncipes dos filisteus: Não é este Davi, o servo de Saul, rei de Israel, que esteve comigo há alguns dias ou anos? Coisa nenhuma achei nele desde o dia em que se revoltou, até ao dia de hoje.'),
('acf','1sm',29,4,'Porém os príncipes dos filisteus muito se indignaram contra ele; e disseram-lhe os príncipes dos filisteus: Faze voltar este homem, para que torne ao lugar em que tu o puseste, e não desça conosco à batalha, para que não se torne nosso adversário na batalha; pois, com que poderia este agradar a seu Senhor? Porventura não seria com as cabeças destes homens?'),
('acf','1sm',29,5,'Não é este aquele Davi, de quem uns aos outros cantaram nas danças, dizendo: Saul feriu os seus milhares, porém Davi os seus dez milhares?'),
('acf','1sm',29,6,'Então Aquis chamou a Davi e disse-lhe: Vive o Senhor, que tu és reto, e que a tua entrada e a tua saída comigo no arraial é boa aos meus olhos; porque nenhum mal em ti achei, desde o dia em que a mim vieste, até ao dia de hoje; porém aos olhos dos príncipes não agradas.'),
('acf','1sm',29,7,'Volta, pois, agora, e vai em paz; para que não faças mal aos olhos dos príncipes dos filisteus.'),
('acf','1sm',29,8,'Então Davi disse a Aquis: Por quê? Que fiz? Ou que achaste no teu servo, desde o dia em que estive diante de ti, até ao dia de hoje, para que não vá e peleje contra os inimigos do rei, meu senhor?'),
('acf','1sm',29,9,'Respondeu, porém, Aquis, e disse a Davi: Bem o sei; e que na verdade aos meus olhos és bom como um anjo de Deus; porém disseram os príncipes dos filisteus: Não suba este conosco à batalha.'),
('acf','1sm',29,10,'Agora, pois, amanhã de madrugada levanta-te com os servos de teu senhor, que têm vindo contigo; e, levantando-vos pela manhã, de madrugada, e havendo luz, parti.'),
('acf','1sm',29,11,'Então Davi de madrugada se levantou, ele e os seus homens, para partirem pela manhã, e voltarem à terra dos filisteus; e os filisteus subiram a Jizreel.'),
('acf','1sm',30,1,'Sucedeu, pois, que, chegando Davi e os seus homens ao terceiro dia a Ziclague, já os amalequitas tinham invadido o sul, e Ziclague, e tinham ferido a Ziclague e a tinham queimado a fogo.'),
('acf','1sm',30,2,'E tinham levado cativas as mulheres, e todos os que estavam nela, tanto pequenos como grandes; a ninguém, porém, mataram, tão-somente os levaram consigo, e foram o seu caminho.'),
('acf','1sm',30,3,'E Davi e os seus homens chegaram à cidade e eis que estava queimada a fogo, e suas mulheres, seus filhos e suas filhas tinham sido levados cativos.'),
('acf','1sm',30,4,'Então Davi e o povo que se achava com ele alçaram a sua voz, e choraram, até que neles não houve mais forças para chorar.'),
('acf','1sm',30,5,'Também as duas mulheres de Davi foram levadas cativas; Ainoã, a jizreelita, e Abigail, a mulher de Nabal, o carmelita.'),
('acf','1sm',30,6,'E Davi muito se angustiou, porque o povo falava de apedrejá-lo, porque a alma de todo o povo estava em amargura, cada um por causa dos seus filhos e das suas filhas; todavia Davi se fortaleceu no Senhor seu Deus.'),
('acf','1sm',30,7,'E disse Davi a Abiatar, o sacerdote, filho de Aimeleque: Traze-me, peço-te, aqui o éfode. E Abiatar trouxe o éfode a Davi.'),
('acf','1sm',30,8,'Então consultou Davi ao Senhor, dizendo: Perseguirei eu a esta tropa? Alcançá-la-ei? E lhe disse: Persegue-a, porque decerto a alcançarás e tudo libertarás.'),
('acf','1sm',30,9,'Partiu, pois, Davi, ele e os seiscentos homens que com ele se achavam, e chegaram ao ribeiro de Besor, onde pararam os que ficaram atrás.'),
('acf','1sm',30,10,'E perseguiu-os Davi, ele e os quatrocentos homens, pois que duzentos homens ficaram, por não poderem, de cansados que estavam, passar o ribeiro de Besor.'),
('acf','1sm',30,11,'E acharam no campo um homem egípcio, e o trouxeram a Davi; deram-lhe pão, e comeu, e deram-lhe a beber água.'),
('acf','1sm',30,12,'Deram-lhe também um pedaço de massa de figos secos e dois cachos de passas, e comeu, e voltou-lhe o seu espírito, porque havia três dias e três noites que não tinha comido pão nem bebido água.'),
('acf','1sm',30,13,'Então Davi lhe disse: De quem és tu, e de onde és? E disse o moço egípcio: Sou servo de um homem amalequita, e meu senhor me deixou, porque adoeci há três dias.'),
('acf','1sm',30,14,'Nós invadimos o lado do sul dos queretitas, e o lado de Judá, e o lado do sul de Calebe, e pusemos fogo a Ziclague.'),
('acf','1sm',30,15,'E disse-lhe Davi: Poderias, descendo, guiar-me a essa tropa? E disse-lhe: Por Deus jura-me que não me matarás, nem me entregarás na mão de meu senhor, e, descendo, te guiarei a essa tropa.'),
('acf','1sm',30,16,'E, descendo, o guiou e eis que estavam espalhados sobre a face de toda a terra, comendo, e bebendo, e dançando, por todo aquele grande despojo que tomaram da terra dos filisteus e da terra de Judá.'),
('acf','1sm',30,17,'E feriu-os Davi, desde o crepúsculo até à tarde do dia seguinte; nenhum deles escapou, senão só quatrocentos moços que, montados sobre camelos, fugiram.'),
('acf','1sm',30,18,'Assim salvou Davi tudo quanto tomaram os amalequitas; também as suas duas mulheres salvou Davi.'),
('acf','1sm',30,19,'E ninguém lhes faltou, desde o menor até ao maior, e até os filhos e as filhas; e também desde o despojo até tudo quanto lhes tinham tomado, tudo Davi tornou a trazer.'),
('acf','1sm',30,20,'Também tomou Davi todas as ovelhas e vacas, e levavam-nas adiante do outro gado, e diziam: Este é o despojo de Davi.'),
('acf','1sm',30,21,'E, chegando Davi aos duzentos homens que, de cansados que estavam, não puderam seguir a Davi, e que deixaram ficar no ribeiro de Besor, estes saíram ao encontro de Davi e do povo que com ele vinha; e, chegando-se Davi com o povo, os saudou em paz.'),
('acf','1sm',30,22,'Então todos os maus e perversos, dentre os homens que tinham ido com Davi, responderam, e disseram: Visto que não foram conosco, não lhes daremos do despojo que libertamos; mas que leve cada um sua mulher e seus filhos, e se vá.'),
('acf','1sm',30,23,'Porém Davi disse: Não fareis assim, irmãos meus, com o que nos deu o Senhor, que nos guardou, e entregou a tropa que contra nós vinha, nas nossas mãos.'),
('acf','1sm',30,24,'E quem vos daria ouvidos nisso? Porque qual é a parte dos que desceram à peleja, tal também será a parte dos que ficaram com a bagagem; igualmente repartirão.'),
('acf','1sm',30,25,'O que assim foi desde aquele dia em diante, porquanto o pôs por estatuto e direito em Israel até ao dia de hoje.'),
('acf','1sm',30,26,'E, chegando Davi a Ziclague, enviou do despojo aos anciãos de Judá, seus amigos, dizendo: Eis aí para vós uma bênção do despojo dos inimigos do Senhor;'),
('acf','1sm',30,27,'Aos de Betel, e aos de Ramote do sul, e aos de Jater,'),
('acf','1sm',30,28,'E aos de Aroer, e aos de Sifmote, e aos de Estemoa,'),
('acf','1sm',30,29,'E aos de Racal, e aos que estavam nas cidades jerameelitas e nas cidades dos queneus,'),
('acf','1sm',30,30,'E aos de Hormá, e aos de Corasã, e aos de Ataca,'),
('acf','1sm',30,31,'E aos de Hebrom, e a todos os lugares em que andara Davi, ele e os seus homens.'),
('acf','1sm',31,1,'Os filisteus, pois, pelejaram contra Israel; e os homens de Israel fugiram de diante dos filisteus, e caíram mortos na montanha de Gilboa.'),
('acf','1sm',31,2,'E os filisteus perseguiram a Saul e a seus filhos; e mataram a Jônatas, e a Abinadabe, e a Malquisua, filhos de Saul.'),
('acf','1sm',31,3,'E a peleja se agravou contra Saul, e os flecheiros o alcançaram; e muito temeu por causa dos flecheiros.'),
('acf','1sm',31,4,'Então disse Saul ao seu pajem de armas: Arranca a tua espada, e atravessa-me com ela, para que porventura não venham estes incircuncisos, e me atravessem e escarneçam de mim. Porém o seu pajem de armas não quis, porque temia muito; então Saul tomou a espada, e se lançou sobre ela.'),
('acf','1sm',31,5,'Vendo, pois, o seu pajem de armas que Saul já era morto, também ele se lançou sobre a sua espada, e morreu com ele.'),
('acf','1sm',31,6,'Assim faleceu Saul, e seus três filhos, e o seu pajem de armas, e também todos os seus homens morreram juntamente naquele dia.'),
('acf','1sm',31,7,'E, vendo os homens de Israel, que estavam deste lado do vale e deste lado do Jordão, que os homens de Israel fugiram, e que Saul e seus filhos estavam mortos, abandonaram as cidades, e fugiram; e vieram os filisteus, e habitaram nelas.'),
('acf','1sm',31,8,'Sucedeu, pois, que, vindo os filisteus no outro dia para despojar os mortos, acharam a Saul e a seus três filhos estirados na montanha de Gilboa.'),
('acf','1sm',31,9,'E cortaram-lhe a cabeça, e o despojaram das suas armas, e enviaram pela terra dos filisteus, em redor, a anunciá-lo no templo dos seus ídolos e entre o povo.'),
('acf','1sm',31,10,'E puseram as suas armas no templo de Astarote, e o seu corpo o afixaram no muro de Bete-Sã.'),
('acf','1sm',31,11,'Ouvindo então os moradores de Jabes-Gileade, o que os filisteus fizeram a Saul,'),
('acf','1sm',31,12,'Todo o homem valoroso se levantou, e caminharam toda a noite, e tiraram o corpo de Saul e os corpos de seus filhos do muro, de Bete-Sã, e, vindo a Jabes, os queimaram.'),
('acf','1sm',31,13,'E tomaram os seus ossos, e os sepultaram debaixo de um arvoredo, em Jabes, e jejuaram sete dias.')
